async function getUserId() {
  if (!supabaseClient) return null;
  try {
    const { data: { user } } = await supabaseClient.auth.getUser();
    return user?.id || null;
  } catch {
    return null;
  }
}

async function supabaseLoadPortfolio() {
  if (!supabaseClient) return null;
  const userId = await getUserId();
  if (!userId) return null;
  try {
    const { data, error } = await supabaseClient
      .from('user_portfolios')
      .select('*')
      .eq('user_id', userId)
      .single();
    if (error) {
      if (IS_DEV) console.warn('[SUPABASE] load error', error);
      return null;
    }
    return data;
  } catch (err) {
    if (IS_DEV) console.warn('[SUPABASE] load exception', err);
    return null;
  }
}

async function supabaseSavePortfolio(catalogAssets, holdings) {
  if (!supabaseClient) return;
  const userId = await getUserId();
  if (!userId) return;
  // SPEC MULTI-DEVICE STATE HARDENING — reconciliation WRITE BARRIER on this legacy assets/holdings writer.
  if (typeof _aurixPersistenceReady === 'function' && !_aurixPersistenceReady()) return;
  try {
    const { error } = await supabaseClient
      .from('user_portfolios')
      .upsert({
        user_id: userId,
        assets:  catalogAssets,
        holdings,
        updated_at: new Date().toISOString()
      });
    if (error && IS_DEV) console.warn('[SUPABASE] save error', error);
  } catch (err) {
    if (IS_DEV) console.warn('[SUPABASE] save exception', err);
  }
}

async function saveRemoteSafe(catalogAssets, holdings) {
  try {
    await supabaseSavePortfolio(catalogAssets, holdings);
  } catch (e) {
    if (IS_DEV) console.warn('[DATA] saveRemoteSafe retry', e);
    try {
      await supabaseSavePortfolio(catalogAssets, holdings);
    } catch (e2) {
      if (IS_DEV) console.warn('[DATA] saveRemoteSafe failed', e2);
    }
  }
}

// SAVE-INDICATOR-1: subtle autosave status. State machine fires only
// at existing scheduleSave / autoSaveToBackend lifecycle points, so the
// save flow itself is untouched. The DOM node starts hidden, so any
// session that never triggers a save (anonymous browse, boot-only) never
// sees the indicator. Lazy lookup keeps DOM-init ordering safe.
let _saveSyncedFadeTimer = null;
function _setSaveStatus(state) {
  const el = document.getElementById('saveStatus');
  if (!el) return;
  clearTimeout(_saveSyncedFadeTimer);
  if (state === 'hidden') {
    el.hidden = true;
    el.removeAttribute('data-state');
    el.textContent = '';
    return;
  }
  const labels = {
    saving:   t('saveSaving'),
    saved:    t('saveSaved'),
    retrying: t('saveRetrying'),
    offline:  t('saveOffline'),
    failed:   t('saveFailed'),
  };
  const label = labels[state];
  if (!label) return;
  el.hidden = false;
  el.setAttribute('data-state', state);
  el.textContent = label;
  if (state === 'saved') {
    // After a successful save the badge recedes (lower opacity via CSS)
    // so the user is reassured but the indicator is not nagging. It stays
    // readable; the next save cycle promotes it back to full opacity.
    _saveSyncedFadeTimer = setTimeout(() => {
      if (el.getAttribute('data-state') === 'saved') {
        el.setAttribute('data-state', 'saved-faded');
      }
    }, 3500);
  }
}

// AURIX-PERSIST-HARDEN-1: decide what is SAFE to write to the backend's
// assets/holdings columns. Prevents the clobber class behind the observed
// "added on mobile → gone, never reached web" bug: a save/flush firing while
// local state is empty/ambiguous (e.g. web first-login before the remote row is
// written to localStorage, or a 'legacy'/missing-keys source) must NEVER push an
// empty array over a populated remote.
//   • Real local assets present            → send them.
//   • Empty AND authoritative (remote already merged via _bootLoadComplete, OR an
//     explicit reset) → send [] (so a genuine "deleted my last asset" / reset
//     does sync).
//   • Empty AND not-yet-loaded / ambiguous → { omit:true } → caller leaves the
//     assets/holdings columns untouched so the remote is preserved.
// User-created assets are therefore never wiped by a race or a source mismatch.
function _aurixAssetsForBackend() {
  // The in-memory working set is the runtime source of truth (localStorage can
  // lag during boot, before the first save()). If it holds assets, ALWAYS send
  // them — converted to the persisted catalog/holdings shape.
  const live = (typeof assets !== 'undefined' && Array.isArray(assets)) ? assets : [];
  if (live.length > 0) {
    try {
      const conv = convertToNewModel(live);
      return { assets: conv.assets, holdings: conv.holdings, omit: false, reason: 'live-data' };
    } catch (_) { /* fall through to the empty path */ }
  }
  // Empty working set. An empty array is written ONLY on an EXPLICIT reset
  // (resetInProgress or the reset tombstone — the DELETE-LAST path sets it, so a
  // genuine "deleted my last asset" still syncs). Any other empty (boot race,
  // failed remote load, 'legacy'/missing-keys source) is treated as ambiguous →
  // omit the assets/holdings columns so a populated remote is NEVER clobbered.
  const resetting = (typeof _aurixResetInProgress !== 'undefined' && _aurixResetInProgress) ||
                    ((typeof _aurixResetAt === 'function') && _aurixResetAt() > 0);
  if (resetting) return { assets: [], holdings: [], omit: false, reason: 'reset' };
  return { assets: null, holdings: null, omit: true, reason: 'empty-not-reset' };
}

function scheduleSave() {
  clearTimeout(_saveTimer);
  _saveTimer = setTimeout(() => { autoSaveToBackend(); }, 500);
  // SAVE-INDICATOR-1: surface the pending state immediately so the user
  // gets feedback during the 500 ms debounce window, not just when the
  // upsert actually fires. If the user is offline the indicator reflects
  // that instead; the existing retry path will recover when online.
  _setSaveStatus((typeof navigator !== 'undefined' && navigator.onLine === false) ? 'offline' : 'saving');
}

async function autoSaveToBackend(attempt = 1) {
  if (_isSaving || !currentUser || !supabaseClient) {
    _persistDebug('[persist-save-backend] skip', { reason: _isSaving ? 'in-flight' : (!currentUser ? 'no-user' : 'no-client') });
    return;
  }
  // RESET-5: while the atomic orchestrator is running, the reset
  // routine pushes empty state itself via _pushEmptyPortfolioToBackend.
  // A second push from a debounced save() here would race with that
  // and could write a half-cleared state.
  if (typeof _aurixResetInProgress !== 'undefined' && _aurixResetInProgress) return;
  // SPEC MULTI-DEVICE STATE HARDENING — reconciliation WRITE BARRIER (assets/holdings too). Never push
  // over the canonical row until the remote reconcile has settled safely; a blocked autosave keeps its
  // data in localStorage and syncs on the next mutation/flush once reconcile succeeds.
  if (typeof _aurixPersistenceReady === 'function' && !_aurixPersistenceReady()) {
    _persistDebug('[persist-save-backend] autosave BLOCKED (reconcile not ready)', { outcome: (typeof _aurixRemoteLoadOutcome !== 'undefined') ? _aurixRemoteLoadOutcome : null });
    return;
  }

  const tombstone = (typeof _aurixResetAt === 'function') ? _aurixResetAt() : 0;
  // AURIX-PERSIST-HARDEN-1: never push an empty/ambiguous assets array over a
  // populated remote — only live data or an explicit reset writes the columns.
  const safe = _aurixAssetsForBackend();
  if (safe.omit) {
    _persistDebug('[persist-save-backend] skip (omit assets → preserve remote)', { reason: safe.reason });
    if (IS_DEV) console.warn('[DATA] skip autosave (empty/ambiguous, remote preserved)');
    return;
  }
  const assets   = safe.assets;
  const holdings = safe.holdings;

  // P0-DATA-INTEGRITY-LOCK — never propagate a REDUCED set to Supabase over the last-good local
  // state unless an explicit destructive action just occurred (delete/sell/reset within 5s) or
  // it's an explicit reset push. Protects remote even if a reduced set reached in-memory.
  if (_AURIX_BLOCK_DESTRUCTIVE_SAVES && safe.reason !== 'reset') {
    const prev = _aurixReadPersistedCounts();
    const next = _aurixCountModel(assets, holdings);
    const recentlyDestructive = (Date.now() - _aurixLastDestructiveSaveAt) < 5000;
    if (prev && !recentlyDestructive && (next.assets < prev.assets || next.holdings < prev.holdings || next.transactions < prev.transactions)) {
      try { console.error('[DATA][SAVE_BLOCKED_DESTRUCTIVE] backend push skipped (reduction vs local last-good)', { prev, next }); } catch (_) {}
      _aurixAuditSave({ allowed: false, destructive: true, reason: 'backend reduction without explicit destructive context', previous: prev, next: next }, 'backend-sync');
      return;
    }
  }

  try {
    _isSaving = true;
    const _syncedAt = new Date().toISOString();
    _persistDebug('[persist-save-backend] upsert →', {
      reason: safe.reason, assetCount: Array.isArray(assets) ? assets.length : 0,
      symbols: Array.isArray(assets) ? assets.map(a => a.symbol || a.ticker) : [],
    });
    try { console.log('[SYNC][SAVE_START]', { reason: safe.reason, assetCount: Array.isArray(assets) ? assets.length : 0 }); } catch (_) {}
    const { error } = await supabaseClient
      .from('user_portfolios')
      .upsert({
        user_id:    currentUser.id,
        assets,
        holdings,
        updated_at: _syncedAt
      }, { onConflict: 'user_id' });

    if (error) throw error;   // never mark synced/OK if the remote write failed
    _persistDebug('[persist-save-backend] OK', { assetCount: Array.isArray(assets) ? assets.length : 0 });
    if (IS_DEV) console.log('[DATA] autosave success');
    try { _aurixMarkSynced(new Date(_syncedAt).getTime()); } catch (_) {}   // local is now in sync with remote
    try { console.log('[SYNC][SAVE_OK]', { syncedAt: _syncedAt, assetCount: Array.isArray(assets) ? assets.length : 0 }); } catch (_) {}
    try { if (typeof _aurixSyncState !== 'undefined') _aurixSyncState.lastRemoteSaveStatus = 'ok:' + (Array.isArray(assets) ? assets.length : 0) + '@' + _syncedAt; } catch (_) {}
    _setSaveStatus('saved');
    // Tombstone served its purpose — remote is now in sync with local.
    if (tombstone) {
      try { localStorage.removeItem(RESET_AT_KEY); } catch (_) {}
      if (IS_DEV) console.log('[DATA] reset tombstone cleared after sync');
    }
  } catch (e) {
    _persistDebug('[persist-save-backend] ERROR', e && e.message ? e.message : e);
    if (IS_DEV) console.error('[DATA] autosave error:', e);
    try { if (typeof _aurixSyncState !== 'undefined') { _aurixSyncState.lastRemoteSaveStatus = 'error: ' + (e && e.message ? e.message : e); _aurixSyncState.lastError = (e && e.message) ? e.message : String(e); } } catch (_) {}
    const offline = typeof navigator !== 'undefined' && navigator.onLine === false;
    if (attempt < 3) {
      _setSaveStatus(offline ? 'offline' : 'retrying');
      setTimeout(() => autoSaveToBackend(attempt + 1), 1000 * attempt);
    } else {
      _setSaveStatus(offline ? 'offline' : 'failed');
    }
  } finally {
    _isSaving = false;
  }
}

// SAVE-INDICATOR-1: react to connectivity changes. Going offline mid-save
// surfaces the offline state immediately; coming back online retries the
// pending save once (the function self-guards if nothing is pending).
if (typeof window !== 'undefined') {
  window.addEventListener('offline', () => { _setSaveStatus('offline'); });
  window.addEventListener('online',  () => { try { autoSaveToBackend(); } catch (_) {} });
}

// DELETE-LAST-1: when a delete empties the portfolio, the
// autoSaveToBackend guard (`if (!hasAny && !tombstone) return`)
// skips the upsert — so the remote keeps the stale row and the
// deleted asset resurrects on reload. Calling this before save()
// sets the reset tombstone so the same autosave path pushes the
// empty state and self-clears the marker on success (autosave
// success branch already handles tombstone cleanup).
// Preserves _shouldDistrustRemote semantics: a tombstone newer than
// remote.updated_at distrusts the stale row until autosave drains,
// identical to performSafeReset behaviour.
function _persistEmptyPortfolioIfNeeded(reason) {
  try {
    if (!Array.isArray(assets) || assets.length > 0) return;
    if (typeof _aurixResetAt === 'function' && _aurixResetAt()) return;
    localStorage.setItem(RESET_AT_KEY, String(Date.now()));
    if (IS_DEV) console.log('[DATA] empty-state tombstone set (' + (reason || 'delete') + ')');
  } catch (_) {}
}

// ── AURIX-PERSISTENCE-REMOTE-HISTORY-WATCHLIST-1 ───────────────────────
// Histórico (portfolio_history / category_history) and the watchlist were
// local-only, so the iOS standalone PWA (a SEPARATE storage container from
// Safari) showed them empty and deleting/recreating the home-screen shortcut
// wiped them. They now ride in user_portfolios alongside assets/holdings.
//
//   • History    → union-by-ts merge on load (monotonic, never shrinks
//                   except via the existing reset epoch / tombstone).
//   • Watchlist  → last-write-wins by `watchlist_updated_at`, so explicit
//                   deletions stick. Pre-existing (unstamped) lists union
//                   once during migration to guarantee zero data loss.
//
// localStorage stays the hot path (recordSnapshot is untouched); a throttled
// flush mirrors state to Supabase (≤1/60s) plus an immediate flush on
// pagehide/visibilitychange so nothing is lost when the PWA backgrounds.
const WATCHLIST_TS_KEY = 'aurix_watchlist_updated_at';
// AURIX-LAUNCH-P0-PERSISTENCE: critical display preferences (language + base
// currency) now sync to Supabase via the same last-write-wins protocol as the
// watchlist. NOT in PORTFOLIO_KEYS — prefs are preserved across reset/sign-out
// (a language/currency choice is not user-private portfolio state).
const PREFS_TS_KEY     = 'aurix_prefs_updated_at';
let _bootLoadComplete  = false;
// AURIX-CHART-LOADING-1: set true once the first price refresh settles (success
// OR failure). Until then the live investable value is partial/stale, so the
// chart shows a discreet LOADING state instead of prematurely deciding "building",
// and the 24H anti-divergence gate is deferred (it would otherwise drop valid
// points when measured against an incomplete live value → false building on 24H).
let _aurixPricesReady  = false;
let _stateFlushTimer   = null;
let _lastStateFlushMs  = 0;
let _watchlistFlushTimer = null;

function _aurixWatchlistTs() {
  try { return parseInt(localStorage.getItem(WATCHLIST_TS_KEY) || '0', 10) || 0; }
  catch (_) { return 0; }
}

function _aurixPrefsTs() {
  try { return parseInt(localStorage.getItem(PREFS_TS_KEY) || '0', 10) || 0; }
  catch (_) { return 0; }
}

// Stamp a user-driven preference change and flush it to the backend. Called
// from switchLang / _applyCurrencyChange so an explicit choice always wins
// (newer timestamp) over any other container's stored value.
function _touchPrefs() {
  try { localStorage.setItem(PREFS_TS_KEY, String(Date.now())); } catch (_) {}
  try { if (typeof scheduleStateFlush === 'function') scheduleStateFlush(); } catch (_) {}
}

// Apply remote preferences into local memory + DOM WITHOUT triggering the heavy
// re-render paths in switchLang/_applyCurrencyChange (which assume an
// initialised chart/DOM). The boot render + chart init that run later in the
// boot sequence read `lang`/`baseCurrency` fresh, so setting the values here is
// sufficient; applyI18n covers the already-parsed static chrome.
function _applyRemotePrefs(prefs) {
  if (!prefs || typeof prefs !== 'object') return;
  // Language — whitelist to the supported set.
  if ((prefs.lang === 'es' || prefs.lang === 'en') && typeof lang !== 'undefined' && prefs.lang !== lang) {
    try {
      lang = prefs.lang;
      localStorage.setItem(LANG_KEY, lang);
      document.documentElement.lang = lang;
      document.querySelectorAll('[data-lang]').forEach(b => b.classList.toggle('active', b.dataset.lang === lang));
      if (typeof applyI18n === 'function') applyI18n();
      if (typeof applyTypeMetaLabels === 'function') applyTypeMetaLabels();
    } catch (_) {}
  }
  // Base currency — whitelist to the supported set.
  if ((prefs.baseCurrency === 'USD' || prefs.baseCurrency === 'EUR') && typeof baseCurrency !== 'undefined' && prefs.baseCurrency !== baseCurrency) {
    try {
      baseCurrency = prefs.baseCurrency;
      localStorage.setItem(BASE_KEY, baseCurrency);
      document.querySelectorAll('.menu-curr-btn').forEach(b => b.classList.toggle('active', b.dataset.currency === baseCurrency));
      _syncPerfCurrencyButtons();
    } catch (_) {}
  }
}

// ── AURIX-ACCOUNT-SOURCE-OF-TRUTH-1 · Phase 1: UI state (workspace + orders) ──
// Same last-write-wins protocol as preferences. Keys (literals to avoid TDZ on
// the later-declared CARD_ORDER_KEY / CAT_ORDER_KEY / _AW73_STORAGE_KEY consts).
const UI_STATE_TS_KEY = 'aurix_ui_state_updated_at';
function _aurixUiStateTs() {
  try { return parseInt(localStorage.getItem(UI_STATE_TS_KEY) || '0', 10) || 0; }
  catch (_) { return 0; }
}
// Stamp a user-driven UI-state change (workspace edit / card reorder / category
// reorder) and flush. Called from saveWorkspacePersistence + the order savers.
function _touchUiState() {
  try { localStorage.setItem(UI_STATE_TS_KEY, String(Date.now())); } catch (_) {}
  try { if (typeof scheduleStateFlush === 'function') scheduleStateFlush(); } catch (_) {}
}
// Snapshot the current UI state for the remote flush payload.
function _collectUiState() {
  let workspace = null, cardOrder = [], catOrder = [], planOrder = [];
  try { const raw = localStorage.getItem('aurix.workspace.v1'); workspace = raw ? JSON.parse(raw) : null; } catch (_) {}
  try { cardOrder = JSON.parse(localStorage.getItem('portfolio_card_order') || 'null') || []; } catch (_) {}
  try { catOrder  = JSON.parse(localStorage.getItem('portfolio_cat_order')  || 'null') || []; } catch (_) {}
  // Orden de «Tus planes» (identidades «kind:id»). Mismo raíl LWW que el de categorías.
  try { planOrder = JSON.parse(localStorage.getItem('aurix_plan_order')  || 'null') || []; } catch (_) {}
  return { workspace, cardOrder, catOrder, planOrder };
}
// Apply remote UI state into localStorage + the in-memory order vars. The boot
// render reads _cardOrder/_catOrder and the workspace mounts from localStorage,
// so writing here (before render) is sufficient — no heavy re-render needed.
function _applyRemoteUiState(ui) {
  if (!ui || typeof ui !== 'object') return;
  try {
    if (ui.workspace && typeof ui.workspace === 'object') {
      localStorage.setItem('aurix.workspace.v1', JSON.stringify(ui.workspace));
    }
  } catch (_) {}
  try {
    if (Array.isArray(ui.cardOrder)) {
      localStorage.setItem('portfolio_card_order', JSON.stringify(ui.cardOrder));
      if (typeof _cardOrder !== 'undefined') _cardOrder = ui.cardOrder;
    }
  } catch (_) {}
  let reorder = false;
  try {
    if (Array.isArray(ui.catOrder)) {
      reorder = reorder || localStorage.getItem('portfolio_cat_order') !== JSON.stringify(ui.catOrder);
      localStorage.setItem('portfolio_cat_order', JSON.stringify(ui.catOrder));
      if (typeof _catOrder !== 'undefined') _catOrder = ui.catOrder;
    }
  } catch (_) {}
  // Una fila remota ANTERIOR a este campo no trae `planOrder`: ausencia NO es «orden vacío»,
  // así que no se borra el local.
  try {
    if (Array.isArray(ui.planOrder)) {
      reorder = reorder || localStorage.getItem('aurix_plan_order') !== JSON.stringify(ui.planOrder);
      localStorage.setItem('aurix_plan_order', JSON.stringify(ui.planOrder));
    }
  } catch (_) {}
  // Si el orden llegó cuando el Dashboard ya estaba pintado, se repinta UNA vez con él. En el
  // arranque normal la fila remota llega antes que las tarjetas y esto no cambia nada visible.
  if (reorder) { try { if (typeof updateCategoryCards === 'function') updateCategoryCards(); } catch (_) {} }
}

// ── Subscription / plan sync (AURIX-MONETIZATION-1) ───────────────
// The active plan (tier + status + commercial metadata) is an account-level
// fact, so it rides the same last-write-wins remote-sync rail as preferences /
// ui_state. Storage + tier logic live with the plan model (PLAN_KEY, defined in
// the SETTINGS-1 block); here we only expose the timestamp + collect/apply
// helpers the sync layer uses. This is pure persistence — nunca gatea una feature
// (el gate es `hasFeature()` contra el RPC del servidor).
const SUBSCRIPTION_TS_KEY = 'aurix_subscription_updated_at';
function _aurixSubscriptionTs() {
  try { return parseInt(localStorage.getItem(SUBSCRIPTION_TS_KEY) || '0', 10) || 0; }
  catch (_) { return 0; }
}
