function isValidPortfolioData(data) {
  return data &&
    Array.isArray(data.assets) &&
    data.holdings !== null &&
    typeof data.holdings === 'object';
}

// LEGACY-LOAD-1: loadInitialData removed. It accepted
// { assets: [], holdings: [] } as a valid remote payload via
// isValidPortfolioData, which would have let an empty Supabase row
// authoritatively clobber a populated local cache if any caller had
// adopted it. initPortfolioData (still active) sidesteps the trap by
// also requiring backendData.assets.length > 0 before trusting the
// remote, so the boot path is unaffected. isValidPortfolioData stays
// because initPortfolioData still uses it as a shape gate.

async function loadPortfolioFromBackend(userId) {
  if (!supabaseClient || !userId) return null;
  try {
    const { data, error } = await supabaseClient
      .from('user_portfolios')
      // RESET-2: include updated_at so _shouldDistrustRemote can
      // compare against the local reset tombstone.
      // AURIX-PERSISTENCE-REMOTE-HISTORY-WATCHLIST-1: also pull the
      // remote history + watchlist columns so Safari and the iOS PWA
      // (separate storage containers) converge to identical data.
      // AURIX-ACCOUNT-SOURCE-OF-TRUTH-1 Phase 1: select('*') is push-safe — a
      // not-yet-migrated ui_state column simply won't appear (an explicit list
      // would 400 the whole load). Every column is read defensively below.
      .select('*')
      .eq('user_id', userId)
      .single();
    if (error) {
      // SPEC MULTI-DEVICE STATE HARDENING — distinguish a genuine NO-ROW (new account: PGRST116 /
      // "no rows" from .single()) from a TRANSIENT failure. Only 'no-row' may create the first row;
      // a transient failure must BLOCK writes so a row we failed to read is never clobbered.
      try {
        const _noRow = !!(error && (error.code === 'PGRST116' || /0 rows|no rows|multiple \(or no\) rows/i.test(error.message || '')));
        _aurixRemoteLoadOutcome = _noRow ? 'no-row' : 'failed';
      } catch (_) { _aurixRemoteLoadOutcome = 'failed'; }
      try { _aurixNoteCanonicalOutcome(); } catch (_) {}   // SPEC P0 CHART RELIABILITY — latch/recupera la retención canónica
      _persistDebug('[persist-load-backend] ERROR', error.message);
      if (IS_DEV) console.warn('[DATA] Supabase load error:', error.message);
      try { if (typeof _aurixSyncState !== 'undefined') { _aurixSyncState.lastRemoteLoadStatus = 'error: ' + error.message; _aurixSyncState.lastError = error.message; } } catch (_) {}
      return null;
    }
    _persistDebug('[persist-load-backend]', {
      assetCount: (data && Array.isArray(data.assets)) ? data.assets.length : 0,
      symbols: (data && Array.isArray(data.assets)) ? data.assets.map(a => a && (a.symbol || a.ticker)) : [],
      updated_at: data && data.updated_at,
    });
    // SPEC MULTI-DEVICE STATE HARDENING — a successful read with a row ⇒ reconciled ('ok-row'); a null
    // payload without an error is treated as a failure (never assume an empty account on ambiguous data).
    try { _aurixRemoteLoadOutcome = data ? 'ok-row' : 'failed'; } catch (_) {}
    try { _aurixNoteCanonicalOutcome(); } catch (_) {}   // SPEC P0 CHART RELIABILITY — idem
    try { if (typeof _aurixSyncState !== 'undefined') _aurixSyncState.lastRemoteLoadStatus = data ? ('ok:' + ((data.assets || []).length) + ' assets') : 'null'; } catch (_) {}
    return data || null;
  } catch (err) {
    try { _aurixRemoteLoadOutcome = 'failed'; } catch (_) {}
    try { _aurixNoteCanonicalOutcome(); } catch (_) {}   // SPEC P0 CHART RELIABILITY — idem
    try { if (typeof _aurixSyncState !== 'undefined') { _aurixSyncState.lastRemoteLoadStatus = 'exception: ' + (err && err.message); _aurixSyncState.lastError = err && err.message; } } catch (_) {}
    if (IS_DEV) console.warn('[DATA] Supabase load exception:', err);
    return null;
  }
}

async function initPortfolioData(userId) {
  // P0-RELIABILITY-GATE — IDENTITY: the moment we know who is logged in, purge any cache that
  // belongs to a DIFFERENT user (shared-browser / no-logout case) and stamp the current owner, so
  // the local fallback below can only ever be THIS user's data. Remote stays scoped by user_id.
  _aurixEnforceCacheOwner(userId);
  // 1. Backend (fuente principal)
  const backendData = await loadPortfolioFromBackend(userId);
  // AURIX-PERSISTENCE-REMOTE-HISTORY-WATCHLIST-1: reconcile remote history +
  // watchlist into local memory/storage. Runs regardless of which source wins
  // for assets/holdings below; respects the reset epoch/tombstone internally.
  _mergeRemoteState(backendData);
  // SPEC CIERRE PRE-FREEZE — reconciliar TAMBIÉN el ledger económico en el arranque, no sólo en el
  // resync de primer plano. `_aurixCapitalFlowsIncomplete` arranca en TRUE (para una sesión
  // autenticada el ledger remoto es DESCONOCIDO hasta el primer pull con éxito), así que sin esta
  // llamada un arranque en frío dejaría la rentabilidad en «Calculando…» hasta que se disparara un
  // visibilitychange/focus/pageshow. Fire-and-forget y fail-soft, igual que en el resync: si falla,
  // el gate mantiene el estado de cálculo en vez de publicar una cifra que no puede probar.
  try { _aurixCapitalFlowsPull(); } catch (_) {}
  // P0-SYNC-INTEGRITY — version/timestamp + count-aware merge (NEVER loses assets), replacing the
  // naive "remote wins if it has any assets" (which could let a smaller remote clobber a larger
  // local). remote>local ⇒ remote · local>remote ⇒ keep local · equal ⇒ newer-by-updatedAt.
  const localData = getPortfolioData();
  let localModel;
  if (localData.source === 'new') localModel = { assets: localData.assets || [], holdings: localData.holdings || [] };
  else localModel = (localData.legacy && localData.legacy.length) ? convertToNewModel(localData.legacy) : { assets: [], holdings: [] };
  const decision = _aurixMergePortfolio(localModel, backendData);
  try { _aurixSyncState.lastMergeDecision = 'boot:' + decision.apply + ':' + decision.reason; _aurixBootMergeReason = decision.reason; } catch (_) {}
  try { console.log('[SYNC][MERGE]', { phase: 'boot', apply: decision.apply, reason: decision.reason }); } catch (_) {}
  if (decision.apply === 'remote' && isValidPortfolioData(backendData)) {
    // A remote RESET propagated from another device: purge the local cache so the empty state
    // sticks (the boot writer skips empty sets), then re-stamp owner + synced marker.
    if (decision.reason === 'remote-reset') {
      // MISMO usuario, reset propagado desde otro de sus dispositivos: sus lápidas SON el reset
      // y su ledger local puede tener un flujo que nunca llegó al servidor. Coincide con lo que
      // hace `performSafeReset` en el dispositivo de origen, que tampoco borra el ledger: los
      // flujos pre-reset los neutraliza el EPOCH, no un borrado.
      try { _clearLocalUserState(_AURIX_PURGE.SAME_USER); } catch (_) {}
      try { _aurixStampCacheOwner(); } catch (_) {}
    }
    _aurixMarkSynced(_aurixRemoteUpdatedMs(backendData));
    try { _aurixSyncState.lastAppliedSource = 'remote(' + decision.reason + ')'; } catch (_) {}
    _persistDebug('[persist-merge] remote wins', { reason: decision.reason, assetCount: backendData.assets.length });
    if (IS_DEV) console.log('[DATA] loaded from Supabase');
    return backendData;
  }
  try { _aurixSyncState.lastAppliedSource = 'local'; } catch (_) {}
  if (localModel.assets.length > 0) {
    _persistDebug('[persist-merge] local kept', { reason: decision.reason, assetCount: localModel.assets.length });
    if (IS_DEV) console.log('[DATA] loaded from localStorage');
    return localModel;
  }
  // 3. Usuario nuevo
  if (IS_DEV) console.log('[DATA] empty portfolio initialized');
  return { assets: [], holdings: [] };
}

// AUTH-HARDEN-1: password auth intentionally disabled. Invite-gated
// OTP (signInWithOtp + validate_invite_code RPC) is the only public
// auth flow — leaving signUp / signInWithPassword wrappers as window
// globals would let any DevTools console bypass the invite gate.
// signOut below is the only auth helper that survives; the UI logout
// button (app.js:22401) depends on it.

async function signOut() {
  _explicitSignOut = true;   // SPEC POST-LOGIN-BOUNCE.03 — mark so the listener force-redirects (no guard)
  await supabaseClient.auth.signOut();
}

// AUTH-ISOLATION-1: local-cache keys cleared on SIGNED_OUT and on
// performSafeReset. Single source of truth so a logged-out user A
// cannot leak portfolio/identity/onboarding state to user B on a
// shared browser when B's Supabase row is empty.
// Preserves intentionally: `aurix_data_version`, `portfolio_lang`,
// `portfolio_base_currency`, `aurix_plan` (user prefs, not state).
const PORTFOLIO_KEYS = [
  'portfolio_assets',          // legacy primary
  'portfolio_history',         // PORTFOLIO_HISTORY snapshots
  'category_history',          // CATEGORY_HISTORY snapshots
  'portfolio_card_order',      // dashboard card order
  'portfolio_cat_order',       // category drill-down order
  'aurix_plan_order',          // «Tus planes» order (kind:id refs)
  'aurix_watchlist',           // watchlist symbols
  'aurix_watchlist_seeded',    // one-shot seed guard
  'aurix_watchlist_updated_at',// watchlist last-write-wins timestamp (remote sync)
  'aurix_assets',              // new model catalog
  'aurix_holdings',            // new model holdings
  'aurix.workspace.v1',        // workspace cells
  'aurix_insights_memory',     // AI insights memory
  'aurix_user_profile',        // user profile (portfolio-derived)
  'aurix_behavior',            // behavioral signals (portfolio-derived)
  'aurix_decisions',           // user decisions log
  'aurix_data_backup',         // legacy pre-migration backup
  'aurix_identity',            // identity profile (portfolio-derived)
  'aurix_evolution',           // AI evolution level (portfolio-derived)
  'aurix_onboarding_completed',// activation flag
  'aurix_onboarding_step',     // current step in the activation flow
  'aurix_onboarding_preferences',
  'aurix_health_snapshot',
  'aurix_signal_state',
  'aurix_workspace_snapshot',
  'aurix_risk_snapshot',
  'aurix_portfolio_summary',
  'aurix_dashboard_chart_cache',
  'aurix_chart_cache',
  'aurix_portfolio_history',
  'aurix_category_history',
  // P0-RELIABILITY-GATE — these MUST be cleared on logout / user switch too, or the next user
  // inherits the previous user's sync state, event journal or cache-owner stamp (isolation leak).
  'aurix_portfolio_meta',      // sync meta (revision/updatedAt/syncedAt/deviceId)
  'aurix_portfolio_events',    // append-only journal (per-user)
  // `aurix_cache_owner` SALE de esta lista: el logout la purga entera y sin sello el cambio de
  // usuario deja de ser detectable. Vive ahora en `USER_SCOPED_LOCAL_KEYS`.
  // SPEC P0 CHART · AISLAMIENTO MULTI-CUENTA — `aurixLastGoodChartByRange` (_WSC_LASTGOOD_KEY) NO
  // estaba aquí, así que era la única caché de estado FINANCIERO ni namespaced por usuario ni purgada
  // al cambiar de cuenta: publica serie, rendimiento %, color y estado por rango, con lo que el
  // siguiente usuario en el mismo navegador podía ver la última curva buena del anterior. Purgarla en
  // el cambio de usuario es fail-safe: en el peor caso una cuenta pierde su caché de respaldo y
  // rehidrata desde la autoridad, que es precisamente lo que debe hacer.
  'aurixLastGoodChartByRange',
];

// ════════════════════════════════════════════════════════════════════════════
// M.06 · CICLO DE VIDA DEL ESTADO LOCAL — TRES EVENTOS, TRES CONTRATOS
// ════════════════════════════════════════════════════════════════════════════
// `_clearLocalUserState` servía al CAMBIO DE USUARIO y al CIERRE DE SESIÓN DEL MISMO
// USUARIO con una sola lista, y esos dos eventos piden lo contrario:
//   · CAMBIO DE USUARIO necesita purgar MÁS. Conservar la lápida de reset de A era peor
//     que la fuga: el flush escribía `portfolio_history: []` con el `user_id` de B.
//   · CIERRE DE SESIÓN necesita purgar MENOS. `_aurixCaptureFlow` empuja un flujo UNA
//     vez, sin cola ni reintento, y `_aurixBackfillCapitalFlows` no tiene llamadores: si
//     el push falló, el ledger LOCAL es el único testigo. Borrarlo al salir hacía que el
//     siguiente pull demostrara «completitud» contra un `count` que nunca vio la fila ⇒
//     un DEPÓSITO publicado como RENDIMIENTO, sin fallar cerrado.
// El RESET de cuenta es el tercero y sigue aparte, en `performSafeReset`: sus lápidas son
// justo lo que impide resucitar lo borrado, así que no se mezcla con ninguno de los dos.
const _AURIX_PURGE = { USER_SWITCH: 'user_switch', SAME_USER: 'same_user' };

// Estado del usuario recuperable del servidor va en `PORTFOLIO_KEYS` (se purga en los DOS
// modos). Aquí va lo que sólo puede irse en un CAMBIO DE USUARIO.
const USER_SCOPED_LOCAL_KEYS = [
  // EL SELLO DE PROPIETARIO. Estaba en `PORTFOLIO_KEYS`, así que el logout lo borraba; y
  // `_aurixCacheIsForeign` exige un sello NO nulo. Tras cerrar sesión, el siguiente usuario
  // entraba con `owner === null` ⇒ la rama de cambio de usuario NUNCA disparaba ⇒ cero
  // purga en la ruta MÁS COMÚN (A sale, B entra), y ahí `_aurixCapitalFlowsPull` subía los
  // flujos de A con el `user_id` de B. Sobreviviendo al logout, el cambio vuelve a ser
  // detectable — y de paso se cierra el «agujero de owner nulo».
  'aurix_cache_owner',
  // FINANCIERO · lápidas y epochs POR USUARIO: el epoch de A no puede filtrar la historia
  // de B ni hacer que su fila remota se declare indigna de confianza.
  'aurix_reset_at', 'aurix_portfolio_epoch',
  // PREFERENCIA CON RE-SELLO. No basta con purgar el sello LWW: con el idioma y la divisa
  // vivos, el guard legacy de `_mergeRemoteState` re-sella con `Date.now()` y A gana
  // SIEMPRE ⇒ B veía su patrimonio en la DIVISA BASE de A y el flush escribía las
  // preferencias de A en la fila de B. En el logout del MISMO usuario sobreviven, que es
  // el contrato certificado de M.03 (el idioma persiste al salir).
  'portfolio_lang', 'portfolio_base_currency',
  'aurix_prefs_updated_at', 'aurix_ui_state_updated_at', 'aurix_subscription_updated_at',
  // IDENTIDAD y rastro de navegación.
  'aurix_display_name', 'aurix.gs.recent.v1',
  'aurix_intv4_shown_v1', 'aurix_intcc_last_visit_v1',
  // Intelligence — contexto aprendido del usuario y memoria de observación. Van AQUÍ y no en
  // `PORTFOLIO_KEYS` porque no son estado recuperable del servidor: son locales, y lo
  // único inaceptable es que sobrevivan a un CAMBIO de usuario. Además cada registro
  // va sellado con su dueño y la lectura falla cerrada sin sello, así que el
  // aislamiento no depende sólo de que esta purga corra.
  'aurix_intel_ctx_v1', 'aurix_intel_mem_v1',
  // §6.2 — el comparador se guarda «solo sesión/local y separada por cuenta».
  // Va sellado con su dueño como los dos de arriba, y además se purga aquí.
  'aurix_cmp_state_v1',
  // I.3 — y sus RECIENTES, por la misma razón. El sello de dueño ya impide que
  // la cuenta B los lea, así que no había fuga; lo que había era una clave de A
  // quedándose huérfana en el dispositivo para siempre. La invariante de M.06
  // es que tras un cambio de usuario NO quede ninguna clave del anterior.
  'aurix_cmp_recent_v1',
  // SPEC ADVANCED INTELLIGENCE · A1 — linaje de clasificación. Es el mapa
  // activo→bucket de UNA cartera y su bitácora de cambios: con el de A vivo, una
  // afirmación de exposición histórica de B podría declararse «clasificación
  // estable» apoyándose en observaciones que nunca fueron de su cuenta.
  'aurix_asset_bucket_map_v1', 'aurix_asset_lineage_v1',
  // Nombres ANTERIORES de las dos claves (una hora en producción). Se purgan igual:
  // una clave huérfana que ya nadie lee sigue siendo estado del usuario A vivo en el
  // navegador, y el aislamiento no admite excepciones por obsolescencia.
  'aurix_auri_ctx_v1', 'aurix_auri_mem_v1',
  // FUERA de ambos modos, con causa: `aurix_investable_chart_epoch` está declarado POR
  // DISPOSITIVO y `Math.max` significa que conservarlo sólo puede SUBIR el suelo, nunca
  // readmitir los snapshots contaminados que mitiga. `aurix_plan` tampoco: es un rail
  // muerto (`_applyRemoteSubscription` es un `return;`) y la autoridad es el RPC.
];
// Nombre con sufijo variable: ninguna lista literal lo cubre. Duplicado verbatim de la
// cartera, CERO lectores, y ningún camino lo borraba.
const USER_SCOPED_LOCAL_PREFIXES = ['aurix_portfolio_backup_before_migration_'];

// ── LO QUE NO SE PUEDE BORRAR: SE APARCA Y SE DES-APARCA ────────────────────────────
// Local-only o de recuperación no garantizada. Dejarlo es fuga; borrarlo es pérdida
