function t(key) { return T[lang][key]; }

// Apply data-i18n attributes to static HTML
function applyI18n() {
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const v = T[lang][el.dataset.i18n];
    if (typeof v === 'string') el.textContent = v;
  });
  document.querySelectorAll('[data-i18n-ph]').forEach(el => {
    const v = T[lang][el.dataset.i18nPh];
    if (typeof v === 'string') el.placeholder = v;
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const v = T[lang][el.dataset.i18nTitle];
    if (typeof v === 'string') el.title = v;
  });
  document.querySelectorAll('[data-i18n-aria]').forEach(el => {
    const v = T[lang][el.dataset.i18nAria];
    if (typeof v === 'string') el.setAttribute('aria-label', v);
  });
  document.documentElement.lang = lang;
}

// Sync TYPE_META labels to current language (used by donut legend + suggestions)
function applyTypeMetaLabels() {
  const meta  = T[lang].typeMeta;
  const donut = T[lang].donutMeta || {};
  Object.keys(meta).forEach(k => {
    if (!TYPE_META[k]) return;
    TYPE_META[k].label = meta[k];
    if (donut[k]) TYPE_META[k].donutLabel = donut[k];
  });
}

function switchLang(newLang) {
  if (newLang === lang) return;
  lang = newLang;
  localStorage.setItem(LANG_KEY, lang);
  // AURIX-LAUNCH-P0-PERSISTENCE: stamp + flush so this explicit choice wins.
  try { _touchPrefs(); } catch (_) {}
  // SPEC GLOBAL-LANGUAGE — switchLang is the SINGLE owner. Propagate to the onboarding
  // engine's own language store so the two persisted representations (app preferences.lang
  // / LANG_KEY vs the engine's language / preferred_language) can never diverge and reassert
  // a stale language. One-way (app→engine); the engine never pushes language back into the app.
  try { if (window.AurixOnboarding && typeof window.AurixOnboarding.setLanguage === 'function') window.AurixOnboarding.setLanguage(lang); } catch (_) {}
  document.documentElement.lang = lang;
  document.querySelectorAll('[data-lang]').forEach(b => {
    b.classList.toggle('active', b.dataset.lang === lang);
  });
  applyI18n();
  applyTypeMetaLabels();
  // ── EL INDICADOR DE GUARDADO TAMBIÉN ES TEXTO ────────────────────────────
  // Su etiqueta se escribe UNA vez, cuando cambia el estado, así que `applyI18n`
  // no puede alcanzarla: cambiar de idioma con «Guardando…» en pantalla dejaba
  // esa palabra en español dentro de una app en inglés hasta el siguiente
  // guardado. Se re-emite el estado ACTUAL —no se inventa uno— por su owner.
  try {
    const _ss = document.getElementById('saveStatus');
    const _st = _ss && !_ss.hidden ? _ss.getAttribute('data-state') : null;
    if (_st && _st !== 'saved-faded') _setSaveStatus(_st);
  } catch (_) {}
  // ── Y LA ETIQUETA DE ESTADO DEL GRÁFICO ──────────────────────────────────
  // MEDIDO: con la app en inglés se leía «Historial insuficiente». El resolver
  // del gráfico traduce bien —devuelve «Insufficient history» cuando se le
  // pregunta—, pero esa etiqueta se ESCRIBE en el pintado y `applyI18n` no la
  // alcanza: la que ya estaba en pantalla se quedaba en el idioma anterior
  // hasta el siguiente repintado del gráfico.
  //
  // Lo que se hace aquí es un cambio de IDIOMA, no de estado: se sustituye el
  // texto por el equivalente de la MISMA clave en el nuevo idioma, y sólo si
  // coincide EXACTAMENTE con uno de los cinco textos de estado conocidos. No se
  // vuelve a ejecutar nada del motor, no se recalcula ninguna serie y no se
  // toca ningún criterio de suficiencia: si el texto no es uno de los cinco, no
  // se toca. Repintar el gráfico para traducir una palabra sería rehacer
  // trabajo financiero por un motivo tipográfico.
  try { _aurixRelabelChartStateTexts(); } catch (_) {}
  // SPEC GLOBAL-LANGUAGE — retranslate DERIVED Settings surfaces that applyI18n() cannot reach
  // (they are not [data-i18n]): the Investor-Profile summary values + the segmented button
  // active state. Idempotent no-ops when the Settings modal is closed. Fixes the "Investor
  // Profile / part of the UI stays in the old language" (mixed-language) symptom.
  try { if (typeof _settingsPaintProfile === 'function') _settingsPaintProfile(); } catch (_) {}
  try { if (typeof _aurixSyncLangCurrencyButtons === 'function') _aurixSyncLangCurrencyButtons(); } catch (_) {}
  // ACCOUNT-CENTER-I18N-1 — el Account Center también pinta texto DERIVADO del estado
  // (estado de sesión, email sin sesión, descripción del plan). applyI18n() ya alcanza
  // esos nodos porque _settingsPopulate deja escrita la clave correcta en `data-i18n`,
  // pero se re-deriva aquí para que la elección de clave se rehaga en el idioma nuevo
  // sin depender del orden de las pasadas. Es el MISMO owner de repintado que usa
  // openSettingsPanel — no hay un traductor propio del Account Center — y es idempotente
  // con la tarjeta cerrada, así que "cambiar idioma y reabrir" da el mismo resultado que
  // "cambiar idioma con la tarjeta abierta": ninguno exige recargar.
  try { if (typeof _settingsPopulate === 'function') _settingsPopulate(); } catch (_) {}
  if (currentTab === 'market') {
    renderMarket();
  } else if (currentTab === 'workspace') {
    if (typeof renderWorkspace === 'function') renderWorkspace();
  } else if ((currentTab === 'intelligence' || currentTab === 'insights') && typeof _applyTab === 'function') {
    // SPEC GLOBAL-LANGUAGE — Intelligence/Insights render into #tabPlaceholder, not <main>.
    // The old code fell through to render() (Dashboard) and left these tabs in the previous
    // language. Re-mount the active tab so its content re-renders in the new language (this
    // also re-applies the .tab-placeholder--intel scroll-owner hook).
    _applyTab(currentTab);
  } else {
    render();
    updateDonut();
    if (_lastUpdateState) setUpdateStatus(_lastUpdateState);
    const af = document.querySelector('.filter-btn.active')?.dataset.filter || 'all';
    searchInput.placeholder = T[lang].searchPH[af] || T[lang].searchPH.all;
  }
}

// ── State ──────────────────────────────────────────────────
const STORAGE_KEY    = 'portfolio_assets';

// ══════════════════════════════════════════════════════════════════════════════
// P0-DATA-INTEGRITY-LOCK — no save may REDUCE assets/holdings/transactions unless an
// explicit user-destructive action says so. This turns a read/migration/sync bug (which can
// produce a reduced in-memory set) from PERMANENT LOSS into a blocked no-op that preserves the
// last valid portfolio. Defined here (before the boot migration IIFEs that call save()) so the
// consts are initialised ahead of first use. Kill switch: _AURIX_BLOCK_DESTRUCTIVE_SAVES=false.
const _AURIX_BLOCK_DESTRUCTIVE_SAVES = true;
const _AURIX_DESTRUCTIVE_CONTEXTS = ['delete-asset','sell','reduce-position','reset','edit-transaction','migration-confirmed','remote-reset'];
// P0-HISTORY-PARITY-BLOCKER — diagnosis-only telemetry. Counts (does NOT change) the two rejection
// paths the founder is seeing, so aurixHistoryDebug() can prove whether they cause history divergence:
//  • snapshot-guard rejects (a snapshot point dropped before it enters portfolio/category history),
//  • destructive-save blocks (a catalog/holdings save refused by the integrity lock / event journal).
// Pure observation; the guards themselves are untouched.
const _aurixGuardTelemetry = {
  snapshotRejected: 0, lastRejectReason: null, lastRejectTs: null,
  snapshotQuarantined: 0, lastQuarantineReason: null, lastQuarantineTs: null,
  saveBlocked: 0, lastSaveBlockReason: null, lastSaveBlockAt: null,
};
// SPEC CHART-INTEGRITY.OBSERVABILITY — privacy-safe structured integrity events. Records reason codes and
// COUNTS only (never raw balances, tokens, or per-asset symbols/composition) into a bounded ring buffer so
// production behaviour (rejected snapshots, hydration, readiness blockers, health) is inspectable without
// leaking sensitive data. Callers must pass counts/reason codes, not values.
const _AURIX_INTEGRITY_EVENTS_MAX = 100;
function _aurixEmitIntegrityEvent(type, payload) {
  try {
    if (typeof window === 'undefined') return;
    if (!Array.isArray(window.__AURIX_INTEGRITY_EVENTS__)) window.__AURIX_INTEGRITY_EVENTS__ = [];
    const rec = { t: type, ts: Date.now() };
    const p = payload || {};
    // whitelist safe scalar fields only (numbers, short reason strings, booleans) — drop anything else.
    for (const k of Object.keys(p)) {
      const v = p[k];
      if (typeof v === 'number' || typeof v === 'boolean') rec[k] = v;
      else if (typeof v === 'string' && v.length <= 48) rec[k] = v;
    }
    window.__AURIX_INTEGRITY_EVENTS__.push(rec);
    if (window.__AURIX_INTEGRITY_EVENTS__.length > _AURIX_INTEGRITY_EVENTS_MAX) {
      window.__AURIX_INTEGRITY_EVENTS__ = window.__AURIX_INTEGRITY_EVENTS__.slice(-_AURIX_INTEGRITY_EVENTS_MAX);
    }
    if (typeof IS_DEV !== 'undefined' && IS_DEV) { try { console.debug('[AURIX-integrity]', type, rec); } catch (_) {} }
  } catch (_) {}
}
try { if (typeof window !== 'undefined') window._aurixEmitIntegrityEvent = _aurixEmitIntegrityEvent; } catch (_) {}
