function _wsCommercialTierClass(entry) {
  if (!entry) return '';
  if (entry.published !== true || entry.commercialTier === 'undecided') return 'preview';
  if (entry.commercialTier === 'premium' && entry.featureKey) return 'premium';
  return 'free';
}

function _wsAppIdentity(id) { return _WS_APP_IDENTITY[id] || { type: 'app', category: 'misc', visualTone: 'neutral', accentColor: 'blue', previewType: 'glyph', layoutType: 'tool', canPin: true, canSaveToSpace: true, isDailyUse: true, premiumTier: 'free' }; }

// MONETIZATION-V1 · M.01B — el chip de plan del catálogo de Herramientas. Lee el
// `premiumTier` que YA existía en el registro de identidad (era descriptivo y no
// gateaba nada) y lo convierte en la ÚNICA fuente de la frontera comercial
// visible: compound → free, loan → premium. Es PRESENTACIÓN, no seguridad: no
// bloquea la apertura, no reduce opacidad y no marca nada como deshabilitado.
// Cuando exista un entitlement real, se gatea leyendo este mismo campo (ver
// docs/AURIX-MONETIZATION-M01B.md) sin tocar el catálogo ni las tarjetas.
// Cualquier otro valor ('soon', 'core', ausente) NO pinta chip: no se afirma un
// plan que el producto no ha decidido.
// M.02 B4 — el chip pasa a leer `_WS_CATALOG`, la fuente única. `premiumTier` del
// registro de identidad queda como dato descriptivo heredado SIN autoridad: ya no
// decide ni la etiqueta ni el gate.
function _wsToolTier(id) { return _wsCommercialTierClass(_wsCatalogEntry(id)); }
// ── SIN LLAMADOR DESDE «WORKSPACE OPERATIVO», Y A PROPÓSITO ────────────────
// Sus dos consumidores eran las cabeceras de Préstamos y Portfolio inmobiliario,
// y §1 retira el chip de ahí: dentro de una capacidad abierta el usuario ya tiene
// el derecho, así que «Premium» no informaba de nada — sólo gastaba una línea.
// La función se conserva porque es el ÚNICO owner que sabe pintar un chip de plan
// leyendo el catálogo, y su contrato está anclado (M9): si mañana vuelve a hacer
// falta un chip en alguna superficie, el camino correcto ya existe y no se
// reinventa con un literal «Pro» como el que M3.9 vino a cerrar.
function _wsTierChip(id) {
  const entry = _wsCatalogEntry(id);
  const tier = _wsCommercialTierClass(entry);
  const label = _wsCommercialLabel(entry);
  if (!tier || !label) return '';
  return `<span class="wsh-tier is-${tier}">${String(label).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]))}</span>`;
}

// WS.12 (v2) — Mi Espacio personalisation: hide a saved app from the space
// (keeps its data) and pin apps to the top. Refs match _wshAllProjects/_wsPinned.
const _WSH_SPACE_HIDDEN_KEY = 'aurix_ws_space_hidden_v1';
const _WSH_SPACE_TOP_KEY    = 'aurix_ws_space_top_v1';
function _wsSpaceHidden() { return _wshReadStore(_WSH_SPACE_HIDDEN_KEY); }
function _wsSpaceIsHidden(ref) { return _wsSpaceHidden().indexOf(ref) >= 0; }
function _wsSpaceHide(ref) { const l = _wsSpaceHidden(); if (l.indexOf(ref) < 0) l.push(ref); _wshWriteStore(_WSH_SPACE_HIDDEN_KEY, l); }
function _wsSpaceTop() { return _wshReadStore(_WSH_SPACE_TOP_KEY); }
function _wsSpaceToggleTop(ref) { const l = _wsSpaceTop(); const i = l.indexOf(ref); if (i >= 0) l.splice(i, 1); else l.unshift(ref); _wshWriteStore(_WSH_SPACE_TOP_KEY, l); }
function _wsSpaceTopRank(ref) { const i = _wsSpaceTop().indexOf(ref); return i < 0 ? 9999 : i; }

// WS.6A — pinned quick-access items (tools/templates). Separate from saved
// projects: pinning never creates a project nor touches the project counters.
const _WSH_PINNED_KEY = 'aurix_ws_pinned_v1';
function _wsPinned() { return _wshReadStore(_WSH_PINNED_KEY); }
function _wsIsPinned(ref) { return _wsPinned().some(p => p && p.ref === ref); }
function _wsTogglePin(ref) {
  const list = _wsPinned();
  const i = list.findIndex(p => p && p.ref === ref);
  // EL GATE VA EN LA RAMA DE AÑADIR, NO ANTES. Esta función hace las DOS cosas, y
  // ponerlo arriba dejaba fijados huérfanos que nadie podía retirar: un usuario que
  // fijó algo cuando fijar no estaba gateado se quedaba con la estrella encendida y
  // cada clic le abría el paywall en vez de apagarla. Retirar lo propio nunca
  // requiere plan; añadir, sí.
  // ── SI NO SE PUDO GUARDAR, SE DICE ──────────────────────────────────────
  // `_wshWriteStore` ya devolvía `false` cuando el almacén rechaza la escritura
  // (cuota llena, modo privado), pero nadie miraba el valor: la estrella se
  // repintaba desde el almacén —así que no quedaba un estado falso, eso estaba
  // bien— y el usuario veía que su clic «no hacía nada», sin saber por qué.
  // Ahora se le dice. El repintado sigue saliendo del almacén: la verdad es lo
  // que se guardó, nunca lo que se pulsó.
  // El aviso va SIEMPRE entre guardas: avisar de un fallo no puede convertirse
  // en un fallo. Sin esto, un entorno donde el toast no exista rompía el propio
  // toggle — lo cazaron dos asserts de «quitar la estrella siempre funciona».
  const _warn = () => { try { if (typeof _wsPinFailed === 'function') _wsPinFailed(); } catch (_) {} };
  if (i >= 0) {
    list.splice(i, 1);                       // quitar es quitar de la lista
    if (!_wshWriteStore(_WSH_PINNED_KEY, list)) _warn();
    return;
  }
  if (!_wsCanPersist()) return _wsPersistUpsell('pin');
  list.push({ ref, ts: Date.now() });
  if (!_wshWriteStore(_WSH_PINNED_KEY, list)) _warn();
}
// Un aviso breve, por el canal que ya existe para los avisos de Workspace.
function _wsPinFailed() {
  try { _aurixBillingToast(t('wspin_failed'), 'error'); } catch (_) {}
}
// ── DSH.WORKSPACE.01 — usage recency (Aurix learns from real behaviour) ─────
// Every open records lastUsedAt for the item's canonical ref. Mi Espacio orders
// templates & tools by this DESC, so the user's last action is always first.
// The user organizes nothing — the space reorganizes itself from real use.
const _WSH_RECENT_KEY = 'aurix_ws_recent_v1';
function _wsRecentMap() { try { const raw = localStorage.getItem(_WSH_RECENT_KEY); const v = raw ? JSON.parse(raw) : {}; return (v && typeof v === 'object') ? v : {}; } catch (_) { return {}; } }
function _wsRecentTs(ref) { const v = _wsRecentMap()[ref]; return typeof v === 'number' ? v : 0; }
function _wsTouch(ref) { if (!ref) return; const m = _wsRecentMap(); m[ref] = Date.now(); _wshWriteStore(_WSH_RECENT_KEY, m); }
// Map an open (cta,arg) → the canonical ref used for pinning + recency.
function _wsCanonRef(cta, arg) {
  if (cta === 'tool') { const k = arg || 'compound'; return (k === 'compound' || k === 'loan') ? 'tool:' + k : 'tpl:' + (k === 'budget' ? 'mbudget' : k); }
  if (cta === 'workspace') return 'tpl:' + arg;
  if (cta === 'scenario') return 'tpl:scenario';
  if (cta === 'goals') return 'tpl:goals';
  if (cta === 'planning') return 'tpl:projection';
  return '';
}
// Relative "hace 2 horas" / "2h ago" for the card timestamp.
function _wsRelTime(ts) {
  if (!ts) return '';
  const d = Math.max(0, Date.now() - ts), es = (lang !== 'en');
  const min = Math.floor(d / 60000), h = Math.floor(d / 3600000), day = Math.floor(d / 86400000);
  if (min < 1) return es ? 'ahora mismo' : 'just now';
  if (h < 1) return es ? `hace ${min} min` : `${min} min ago`;
  if (day < 1) return es ? `hace ${h} h` : `${h}h ago`;
  if (day < 30) return es ? `hace ${day} d` : `${day}d ago`;
  const mo = Math.floor(day / 30); return es ? `hace ${mo} mes${mo > 1 ? 'es' : ''}` : `${mo}mo ago`;
}
// Display label + open dispatch for a pinned ref ('tool:<k>' | 'tpl:<type>').
function _wsPinLabel(ref) {
  const i = ref.indexOf(':'); const kind = ref.slice(0, i), key = ref.slice(i + 1);
  if (kind === 'tool') return t('wstool_' + key + '_n');
  if (key === 'goals') return t('wsg_title');
  if (key === 'scenario') return t('wsh_scenario_title');
  if (key === 'projection') return t('wsp_title');
  return t('wsh_ws_' + key);
}
function _wsPinOpen(ref) {
  _wsReturnTab = 'space';   // WS.14A — pinned items live in Mi Espacio
  const i = ref.indexOf(':'); const kind = ref.slice(0, i), key = ref.slice(i + 1);
  if (kind === 'tool') { _wsOpenTool(key); return; }
  if (_WS_VIEW_SURFACES.indexOf(key) !== -1) { _wsOpenSurface(key); return; }
  _ws4OpenOrCreate(key);
}
// WS.7A — per-tool last state (quick-access scratch). NOT a project: opening a
