// WS.10.1 — data-backed tool preview (shows the real result, not an abstract viz).
function _wsToolPreviewHtml(toolKey) {
  const esc = _intccEsc;
  try {
    if (toolKey === 'compound') {
      const inp = _wsToolStateGet('compound') || _wsToolDefaults();
      // UNA SOLA PROYECCIÓN POR DOCUMENTO. Esta vista previa llamaba directamente a
      // `calculateCompoundGrowth`, que tiene la convención NOMINAL12 CABLEADA,
      // mientras la herramienta pinta `_wsCompoundProjection` (efectiva para las
      // simulaciones nuevas). Resultado medido por la revisión financiera: la
      // pantalla decía 139.238,73 € y la tarjeta del catálogo 141.922 € para el
      // MISMO documento — 2.684 € de diferencia, y exactamente la reinterpretación
      // silenciosa que §A prohíbe. La convención es del DOCUMENTO, así que sólo
      // puede leerla el owner que la conoce.
      const pr = _wsCompoundProjection(inp);
      const r = { final: pr.final, series: pr.series.map(x => ({ total: x.value })) };
      const W = 120, H = 30, n = r.series.length, max = Math.max.apply(null, r.series.map(s => s.total).concat([1]));
      const pts = r.series.map((s, i) => `${((i / ((n - 1) || 1)) * W).toFixed(1)},${(H - (s.total / max) * (H - 4) - 2).toFixed(1)}`).join(' ');
      return `<div class="wspv wspv-compound"><div class="wspv-fig"><span class="wspv-num">${esc(_wsMoney(r.final))}</span><span class="wspv-lbl">${esc(t('wstool_res_final'))}</span></div><svg class="wspv-spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><polygon class="wspv-spark-area" points="0,${H} ${pts} ${W},${H}"/><polyline class="wspv-spark-line" points="${pts}"/></svg></div>`;
    }
    if (toolKey === 'budget') {
      // WS.F1 — premium donut: expenses + free arcs over income, free money centered.
      const inp = _wsToolStateGet('budget') || _wsBudgetDefaults();
      const r = calculateMonthlyBudget(inp);
      const free = Math.max(0, r.free);
      const total = Math.max(r.income, r.expenses + free, 1);
      const R = 33, C = 2 * Math.PI * R;
      const expLen = Math.min(C, (r.expenses / total) * C);
      const freeLen = Math.min(C - expLen, (free / total) * C);
      const seg = (len, off, cls) => `<circle class="wspv-dn-seg ${cls}" cx="44" cy="44" r="${R}" stroke-dasharray="${len.toFixed(1)} ${(C - len).toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}"/>`;
      return `<div class="wspv wspv-budget wspv-bud-donut">
        <div class="wspv-dn-wrap">
          <svg class="wspv-dn" viewBox="0 0 88 88" aria-hidden="true">
            <circle class="wspv-dn-track" cx="44" cy="44" r="${R}"/>
            ${seg(expLen, 0, 'is-exp')}
            ${seg(freeLen, -expLen, 'is-free')}
          </svg>
          <div class="wspv-dn-center"><b class="wspv-dn-v">${esc(_wsMoney(r.free))}</b><i class="wspv-dn-k">${esc(t('wstool_bud_free'))}</i></div>
        </div>
        <div class="wspv-dn-legend">
          <span class="wspv-dn-li"><i class="wspv-dn-dot is-inc"></i>${esc(t('wstool_budget_sec_income'))}<b>${esc(_wsMoney(r.income))}</b></span>
          <span class="wspv-dn-li"><i class="wspv-dn-dot is-exp"></i>${esc(t('wstool_budget_sec_expenses'))}<b>${esc(_wsMoney(r.expenses))}</b></span>
        </div>
      </div>`;
    }
    if (toolKey === 'journal') {
      const inp = _wsToolStateGet('journal') || _wsJournalDefaults();
      const r = calculateTradeJournal(inp.trades);
      const rows = r.list.filter(x => !x.open).slice(0, 3);
      const list = rows.map(x => `<span class="wspv-tk"><b class="wspv-tk-a">${esc(String(x.asset || '').slice(0, 5))}</b><b class="wspv-tk-r is-${x.pl >= 0 ? 'win' : 'loss'}">${esc(_wsJrnPct(x.ret))}</b></span>`).join('');
      return `<div class="wspv wspv-journal">${list}</div>`;
    }
  } catch (_) {}
  return '';
}

