    + '<svg class="wspl-spend" viewBox="0 0 100 6" preserveAspectRatio="none" role="img" aria-label="' + esc(lbl) + '">' + rects + '</svg>'
    + '<span class="wspl-share-t" aria-hidden="true">' + esc(t('wspl_spend')) + '</span>'
