// POR instancia, así que su cuerpo plegado eran sus propios campos. Una herramienta tiene UN
// editor y N documentos, así que el cuerpo no puede ser un editor — es el resumen GUARDADO del
// documento. Dos formas muy distintas sobre la misma primitiva, que es exactamente la prueba de
// si la abstracción era correcta o estaba moldeada al primer caso.
//
// LO QUE LA SEGUNDA INTEGRACIÓN OBLIGÓ A CAMBIAR (y se anota porque es el valor del ejercicio):
// el menú de una instancia necesitaba «Abrir». En Objetivos se omitía a propósito —la instancia
// ya está delante y su `<summary>` la despliega—, pero aquí abrir es LA acción: carga el
// documento en el editor. Así que `_wsSavedMenuOpen` pasa a recibir qué acciones aplican en vez
// de decidirlo por su cuenta.
//
// NO SE RECALCULA NADA. Las cifras del cuerpo son las que el documento GUARDÓ (`p.results`), no
// una re-ejecución del motor: enseñar un número recalculado bajo un nombre guardado afirmaría
// que el documento dice algo que no dice. Si un documento no tiene resultados guardados, no se
// publica ninguna cifra (§52).
function _wsToolDocSummary(p) {
  const r = (p && p.results) || null;
  if (!r) return [];
  const m = (k, v) => ({ k: t(k), v: v });
  // `Number(null)` es 0 y es finito: un resultado NO publicable (diario con divisas
  // mezcladas) salía como «0,00 €». Y la divisa es la que el documento GUARDÓ, si la
  // declara; la base sólo para los que no la declaran.
  const _ccy = _wsDocCurrencyOf(p);   // la del documento; sin ella, cifra sin símbolo
  const money = v => ((v != null && v !== '' && Number.isFinite(Number(v))) ? _wsMoneyIn(Number(v), _ccy) : null);
  const out = [];
  const push = (key, val) => { if (val != null && val !== '') out.push(m(key, val)); };
  try {
    if (p.type === 'compound_growth') {
      // CLAVES REALES, no inventadas. La primera versión usaba `wstool_r_final` y
      // `wsloan_r_monthly`, que no existen: `t()` devolvía `undefined` y la métrica salía SIN
      // etiqueta —una cifra sin decir de qué es—. Lo destapó la captura, no el assert.
      push('wspl_m_final', money(r.final));
      push('wstool_res_contrib', money(r.contributed));
    } else if (p.type === 'loan_simulation') {
      push('wsloan_kpi_monthly', money(r.monthlyPayment));
      push('wsloan_kpi_interest', money(r.totalInterest));
    } else if (p.type === 'monthly_budget') {
      push('wspl_m_income', money(r.income));
      push('wspl_m_expenses', money(r.expenses));
    } else if (p.type === 'receivables_app') {
      push('wspl_m_pending', money(r.totalPendiente));
      push('wspl_m_collected', money(r.totalCobrado));
    } else if (p.type === 'real_estate_portfolio') {
      push('wspl_m_units', Number.isFinite(Number(r.count)) ? String(r.count) : null);
      // El VALOR sólo si está declarado: un «0 €» diría que la cartera no vale nada.
      push('wsdoc_s_value', Number(r.valueTotal) > 0 ? money(r.valueTotal) : null);
    } else if (p.type === 'trade_journal') {
      // Con divisas mezcladas la rentabilidad media no es publicable: sólo el recuento.
      push('wspl_m_rows', Number.isFinite(Number(r.closedCount)) ? String(r.closedCount) : null);
      push('wsdoc_s_net', money(r.netProfit));
    } else if (p.type === 'asset_prices') {
      push('wspl_m_rows', Number.isFinite(Number(r.count)) ? String(r.count) : null);
      push('wsdoc_s_net', r.currencyMixed ? null : money(r.netProfitLoss));
    }
  } catch (_) { return []; }
  return out;
}
// La lista de documentos de la capacidad ABIERTA. Se pinta DEBAJO del trabajo (bloque 5 de la
// jerarquía del §6), así que no desplaza ni un píxel el primer control útil que v740 certificó.
// Sin documentos no se pinta: una tarjeta vacía que dice «no tienes nada» repite con otras
// palabras lo que la pantalla ya está diciendo.
function _wsToolSavedListHtml() {
  const esc = _intccEsc;
  const type = _wsToolStateType(_wsToolActive);
  let docs = [];
  try { docs = _wsSaveCandidates(type, null); } catch (_) { return ''; }
  if (!docs.length) return '';
  let raw = [];
  try { raw = _ws4Projects(); } catch (_) { raw = []; }
  const accent = _WS_TOOL_ACCENT[_wsToolActive] || 'blue';
  const rows = docs.map(d => {
    const p = raw.find(x => x && x.id === d.id) || {};
    const kpis = _wsToolDocSummary(p);
    const isOpen = _wsToolEditId === d.id;
    return _wsSavedItemHtml({
      ref: 'workspace:' + d.id,
      accent: accent,
      icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + _wsGlyph('log') + '</svg>',
      name: d.name,
      meta: isOpen ? t('wsdoc_open_now') : d.meta,
      kpis: kpis,
      cls: isOpen ? 'is-current' : '',
      body: '<div class="wssi-doc">'
        + (kpis.length ? '<div class="wssi-doc-kpis">' + kpis.map(x =>
            '<span class="wssi-doc-kpi"><i>' + esc(x.k) + '</i><b>' + esc(x.v) + '</b></span>').join('') + '</div>'
          : '<p class="wssi-doc-none">' + esc(t('wsdoc_s_none')) + '</p>')
        + (isOpen ? '' : '<button type="button" class="wsh-cta wssi-doc-open" data-wsdoc-open="' + esc(d.id) + '">'
            + esc(t('wstool_open_saved')) + '</button>')
        + '</div>',
    });
  }).join('');
  return `
      <section class="wsh-card wsdoc-card">
        <header class="wsh-head"><h3 class="wsh-title">${esc(t('wsdoc_title'))}</h3></header>
        <div class="wsg-stack">${rows}</div>
      </section>`;
}
// El acento de cada capacidad, en un solo sitio. Consume la API de `data-ws-accent`, así que
// aquí sólo vive el NOMBRE — el tono está en la hoja de estilos.
// §6/§36 — UN SOLO OWNER DEL ACENTO DE UNA CAPACIDAD, y ahora cubre las nueve publicadas.
// Faltaban `scenario` y `goals`, que se pintaban con otro mapa (`_WS_APP_IDENTITY`): dos fuentes
// para la misma idea, que es el modo de fallo que esta sesión lleva cerrando.
// CONVIENE DEJAR LAS DOS RAZONES ESCRITAS, porque aquí hay un choque. Una decisión anterior
// unificó los acentos AL AZUL con un argumento bueno: «tres iconos de tres familias cromáticas
// sólo comunican desorden». El cierre pide lo contrario —identidad por capacidad, más color— y
// gana por dos motivos: primero, porque es la instrucción vigente; y segundo, porque esa
// unificación ya la superó el propio producto: las vistas de herramienta llevan acento por
// capacidad desde que existe esta API, está desplegado y certificado. Lo que queda no es una
// paleta nueva, es extender la que ya manda. Cinco tonos para nueve capacidades, agrupando las
// parientes: eso es sistema, no desorden.
const _WS_TOOL_ACCENT = Object.freeze({
  compound: 'teal', loan: 'blue', budget: 'teal', receivables: 'green',
  journal: 'violet', realestate: 'violet', assets: 'blue', comparator: 'blue',
  scenario: 'plum', goals: 'plum',
});
function _wsToolOpenSaved() {
  const type = _wsToolStateType(_wsToolActive);
  const docs = _wsSaveCandidates(type, null);
  if (!docs.length) { try { _wsToolSaveError(t('wstool_open_none')); } catch (_) {} return; }
  _wsPickDocModal({
    title: t('wstool_open_title'), text: t('wstool_open_text'),
    docs: docs, okLabel: t('wstool_open_saved'),
    onPick: (d) => {
      if (!d || !d.id) return;
      // Por el owner de apertura de siempre: vuelve a preguntar el gate y carga
      // los inputs del documento, no los del borrador que hubiera en pantalla.
      _wsOpenTool(_wsToolActive, d.id);
    },
  });
}
// «Guardar como…» — el MISMO modal, y una copia con ID nuevo. Un nombre repetido
// no sobrescribe nada: la identidad es el ID.
function _wsToolSaveAs() {
  if (!_wsToolInputs) return;
  if (!_wsCanPersist()) return _wsPersistUpsell('tool:' + String(_wsToolActive || ''));
  const missing = _wsToolMissingRequired();
  if (missing.length) return _wsToolShowRequired(missing);
  let cur = '';
  try { const p = _ws4Projects().find(x => x && x.id === _wsToolEditId); cur = (p && p.customName) || ''; } catch (_) {}
  const sug = cur ? (cur + ' ' + t('wsg_copy_suffix')) : _wsToolSuggestName();
  _wsToolNamePrompt(t('wsname_saveas_title'), sug, name => _wsToolCommit(name, true));
}
// «Renombrar» — cambia SÓLO el nombre y conserva los datos (no vuelve a calcular
// ni a escribir `inputs`/`results`).
function _wsToolRename() {
  if (!_wsToolEditId) return;
  const p = _ws4Projects().find(x => x && x.id === _wsToolEditId);
  if (!p) return;
  _wsToolNamePrompt(t('wsmse_rename_title'), p.customName || _wsTypeLabel(p.type), name => {
    _wsRename('workspace:' + p.id, name);
    const c = document.getElementById('aurixWorkspace'); if (c) { c.innerHTML = _wsRenderTool(); _wshReveal(c); }
  });
}
// «Eliminar» — confirmación y tombstone, por el mecanismo existente.
function _wsToolDelete() {
  if (!_wsToolEditId) return;
  const id = _wsToolEditId;
  _wsModal2({ title: t('wsmse_del_title'), text: t('wsmse_del_text'), okLabel: t('wsmse_del_ok'), danger: true, onOk: () => {
    _ws4Tombstone(id);
    _wsToolEditId = null; _wsToolDirty = true;
    const c = document.getElementById('aurixWorkspace'); if (c) { c.innerHTML = _wsRenderTool(); _wshReveal(c); }
  } });
}
// El único llamador del modal de nombre desde las herramientas.
function _wsToolNamePrompt(title, suggested, onName) {
  _wsPrompt({
    title: title, current: suggested, placeholder: suggested,
    fieldLabel: t('wsname_field'), okLabel: t('wsname_ok'), required: true,
    onOk: v => { const name = String(v || '').trim(); if (!name) return; onName(name); },
  });
}
// `targetId` es el destino EXPLÍCITO de un reemplazo elegido por el usuario en
// el selector de §4. Sin él, el comportamiento es el de siempre: actualizar la
// instancia abierta o crear una nueva. Nunca se deduce un destino.
function _wsToolCommit(name, forceNew, targetId) {
  if (!_wsToolInputs) return;
  const now = Date.now();
  const list = _ws4Projects();
  const existing = targetId
    ? list.find(p => p && p.id === targetId && p.type === _wsToolStateType(_wsToolActive))
    : ((!forceNew && _wsToolEditId) ? list.find(p => p && p.id === _wsToolEditId) : null);
  // Un destino que ya no existe —borrado en otro dispositivo entre la elección y
  // la confirmación— no se convierte en «crea otro»: se dice y no se escribe.
  if (targetId && !existing) { try { _wsToolSaveError(t('wssave_target_gone')); } catch (_) {} return; }
  let type, results;
  if (_wsToolActive === 'assets') {
    const r = calculateAssetPrices(_wsToolInputs.rows);
    type = 'asset_prices';
    results = { count: r.count, netProfitLoss: r.netProfitLoss == null ? null : Math.round(r.netProfitLoss), currency: r.currency, currencyMixed: r.currencyMixed, averageReturnPct: r.averageReturnPct == null ? null : Math.round(r.averageReturnPct * 10) / 10, averageReturnBasis: r.averageReturnBasis, openCount: r.openCount, bestName: r.best ? r.best.assetName : '', bestPct: (r.best && r.best.returnPct != null) ? Math.round(r.best.returnPct) : null };
  } else if (_wsToolActive === 'loan') {
    const r = calculateLoan(_wsToolInputs);
    type = 'loan_simulation';
    results = { monthlyPayment: Math.round(r.monthlyPayment), totalInterest: Math.round(r.totalInterest), totalPaid: Math.round(r.totalPaid), principal: Math.round(r.principal), annual: r.annual, years: r.years };
  } else if (_wsToolActive === 'receivables') {
    const r = calculateReceivables(_wsToolInputs.items);
    type = 'receivables_app';
    results = { count: r.count, totalPendiente: Math.round(r.totalPendiente), totalCobrado: Math.round(r.totalCobrado), totalVencido: Math.round(r.totalVencido), numeroVencidos: r.numeroVencidos, porcentajeCobrado: r.porcentajeCobrado == null ? null : Math.round(r.porcentajeCobrado), periodBasis: r.periodBasis };
  } else if (_wsToolActive === 'realestate') {
    const r = calculateRealEstatePortfolio(_wsToolInputs.properties);
    type = 'real_estate_portfolio';
    // §E — el agregado guardado es el de IMPORTES, y `null` se conserva como null:
    // redondearlo daría un 0 % que el documento afirmaría para siempre.
    results = { count: r.count, valueTotal: Math.round(r.valueTotal), equityTotal: Math.round(r.equityTotal),
                cashflowMonthly: Math.round(r.cashflowMonthly),
                noiAnnualTotal: Math.round(r.noiAnnualTotal),
                debtServiceMonthlyTotal: Math.round(r.debtServiceMonthlyTotal),
                appreciationTotal: Math.round(r.appreciationTotal),
                avgYield: r.portfolioNetYield == null ? null : Math.round(r.portfolioNetYield * 10) / 10,
                yieldBasis: r.portfolioNetYield == null ? null : 'noi_over_cost_basis' };
  } else if (_wsToolActive === 'journal') {
    const r = calculateTradeJournal(_wsToolInputs.trades);
    type = 'trade_journal';
    results = { netProfit: r.netProfit == null ? null : Math.round(r.netProfit), currency: r.currency, avgReturn: r.avgReturn == null ? null : Math.round(r.avgReturn * 10) / 10, avgReturnBasis: r.avgReturnBasis, winRate: Math.round(r.winRate), closedCount: r.closedCount, count: r.list.length };
  } else if (_wsToolActive === 'budget') {
    const r = calculateMonthlyBudget(_wsToolInputs);
    type = 'monthly_budget';
    // §F — `Math.round(null)` es 0, así que el «no aplicable» de la pantalla se
    // PERSISTÍA como un 0 % y la tarjeta de Mi Espacio lo publicaba. El null viaja.
    results = { income: Math.round(r.income), expenses: Math.round(r.expenses), free: Math.round(r.free),
                saveRate: r.saveRate == null ? null : Math.round(r.saveRate),
                saveRateBasis: r.saveRateBasis, deficit: r.deficit };
  } else {
    // MISMO OWNER QUE LA PANTALLA, por la misma razón: guardar con una convención
    // distinta de la que se está mostrando publica dos cifras para un documento.
    const pr = _wsCompoundProjection(_wsToolInputs);
    type = 'compound_growth';
    results = {
      final: Math.round(pr.final),
      // §B — los cuatro componentes SEPARADOS también en lo guardado. `contributed`
      // conserva su clave y su significado histórico (inicial + aportaciones) para
      // los consumidores que ya la leían, y el inicial se añade aparte.
      initial: Math.round(pr.initial),
      contributed: Math.round(pr.initial + pr.contributed),
      contributedOnly: Math.round(pr.contributed),
      interest: Math.round(pr.growth),
      // Y la CONVENCIÓN con la que se calculó: sin ella, reabrir el documento otro
      // día lo recomputaría con la vigente y movería el resultado en silencio.
      convention: pr.assumptions.convention,
      annualRatePct: pr.assumptions.annualRatePct,
      currency: _wsDocCcy(),
    };
  }
  const proj = {
    // El ID es la identidad REAL y no deriva del nombre: dos documentos con el
    // mismo nombre son dos documentos distintos, y renombrar no crea uno nuevo.
    id: existing ? existing.id : ('ws4_' + now + '_' + Math.random().toString(36).slice(2, 7)),
    type,
    customName: name || (existing ? existing.customName : undefined),
    inputs: Object.assign({}, _wsToolInputs),
    results,
    // La divisa del documento, declarada: ya viajaba al remoto (`_wsDocRows`) pero
    // no quedaba en el cuerpo, así que reabrirlo en otra divisa base reinterpretaba
    // sus importes sin decirlo.
    currency: _wsDocCcy(),   // la del DOCUMENTO (null = sin confirmar), nunca la base del momento
    bodyVersion: 1,
    revision: existing ? (Number(existing.revision) || 1) : 0,
    createdAt: existing ? (existing.createdAt || now) : now,
    updatedAt: now,
  };
  // Si el almacén rechaza la escritura (cuota, modo privado), NO se finge: el
  // borrador sigue sucio en pantalla y el motivo se dice junto al botón.
  if (_ws4Persist(proj) === false) { try { _wsToolSaveError(t('wssave_failed')); } catch (_) {} return; }
  _wsToolEditId = proj.id; _wsToolDirty = false;
  const c = document.getElementById('aurixWorkspace'); if (c) { c.innerHTML = _wsRenderTool(); _wshReveal(c); }
  // §5 — el Dashboard es una VISTA del mismo guardado, así que se repinta aquí
  // mismo: el usuario no debería tener que recargar para ver su plan.
  try { updateDashboardPlans(); } catch (_) {}
}
// Un guardado que NO ocurrió se dice donde el usuario estaba mirando, junto al
// botón que acaba de pulsar. Nunca se cierra en silencio fingiendo éxito.
function _wsToolSaveError(msg) {
  const root = document.querySelector('.wsh-tool-view') || document.getElementById('aurixWorkspace');
  if (!root) return;
  const bar = root.querySelector('[data-wstool-savebar]');
  const host = (bar && bar.parentNode) || root;
  const prev = host.querySelector('.wsg-reqerr'); if (prev) prev.remove();
  const p = document.createElement('p');
  p.className = 'wsg-reqerr'; p.setAttribute('role', 'alert');
  p.textContent = String(msg || '');
  host.appendChild(p);
}

function _wsToolSaveBarHtml() {
  const esc = _intccEsc;
  const state = _wsToolEditId ? (_wsToolDirty ? 'dirty' : 'saved') : 'unsaved';
  const lbl = { unsaved: t('wsg_save_unsaved'), dirty: t('wsg_save_pending'), saved: t('wsg_save_done') }[state];
  const canSave = !_wsToolEditId || _wsToolDirty;
  const saveLabel = _wsToolActive === 'journal' ? t('wstool_save_journal') : _wsToolActive === 'realestate' ? t('wsre_save') : _wsToolActive === 'receivables' ? t('wsrecv_save') : _wsToolActive === 'loan' ? t('wsloan_save') : _wsToolActive === 'assets' ? t('wsap_save') : t('wstool_save');
  // ── SIN PLAN, EL BOTÓN LO DICE ANTES DE PULSARLO ────────────────────────────
  // «Nunca presenta Abrir para después denegar en silencio» vale igual para
  // Guardar. Una cuenta Free ve el mismo botón con su etiqueta Premium y su estado
  // honesto —el cálculo está hecho y vivo, lo que falta es conservarlo—, y al
  // pulsarlo llega la explicación, no un fallo.
  if (!_wsCanPersist()) {
    return `
    <span class="wsg-savestate is-local">${esc(t('wstool_save_session'))}</span>
    <button type="button" class="wsh-cta wsg-savebtn is-lock" data-wstool-save>${esc(saveLabel)}<span class="wsh-tier is-premium">${esc(t('wstier_premium'))}</span></button>`;
  }
  // ── EL CICLO DE VIDA DE LA INSTANCIA ABIERTA ──────────────────────────────
  // Con un documento abierto, `Guardar` ACTUALIZA. Las otras tres acciones existen
  // porque sin ellas no hay forma de tener dos instancias de la misma capacidad:
  // «Guardar como…» crea una copia con ID nuevo, «Renombrar» toca sólo el nombre y
  // «Eliminar» pide confirmación y deja tombstone.
  // ── §6 · UNA ACCIÓN PRIMARIA, Y EL RESTO EN UN MENÚ ─────────────────────
  // Los cuatro botones en fila se salían por la derecha en móvil —«Renombrar»
  // cortado, medido en la captura del fundador— y además mentían sobre la
  // jerarquía: Eliminar no compite con Guardar. Ahora Guardar es la única
  // acción primaria y el ciclo de vida vive en un menú secundario, que es un
  // `<details>` NATIVO: teclado y lector de pantalla sin un manejador nuevo.
  // ── «ABRIR GUARDADO» NO PUEDE DEPENDER DE TENER UNO ABIERTO ─────────────
  // El menú sólo existía con una instancia abierta, porque sólo ofrecía su ciclo
  // de vida. Pero volver a un cálculo guardado se hace precisamente cuando NO
  // tienes ninguno abierto, así que el menú aparece también cuando hay algo que
  // abrir. Es la puerta que sustituye a la que tenían en Mi espacio y en el
  // Resumen, y va PRIMERA porque es la que más se usa.
  let _savedCount = 0;
  // Sin excluir el abierto: la puerta existe si hay ALGO guardado. Excluirlo
  // hacía desaparecer «Abrir guardado» justo cuando sólo hay un documento, que
  // es cuando más natural es querer volver a la lista.
  try { _savedCount = _wsSaveCandidates(_wsToolStateType(_wsToolActive), null).length; } catch (_) { _savedCount = 0; }
  const _openItem = _savedCount > 0
    ? `<button type="button" class="wsg-menu-item" data-wstool-open>${esc(t('wstool_open_saved'))}</button>` : '';
  const _lifeItems = _wsToolEditId ? `
        <button type="button" class="wsg-menu-item" data-wstool-saveas>${esc(t('wstool_saveas'))}</button>
        <button type="button" class="wsg-menu-item" data-wstool-rename>${esc(t('wsg_act_rename'))}</button>
        <button type="button" class="wsg-menu-item is-danger" data-wstool-delete>${esc(t('wstool_delete'))}</button>` : '';
  const lifecycle = (_openItem || _lifeItems) ? `
    <details class="wsg-menu">
      <summary class="wsg-menu-sum" aria-label="${esc(t('wsg_more_aria'))}"><span aria-hidden="true">···</span></summary>
      <div class="wsg-menu-body" role="group" aria-label="${esc(t('wsg_more_aria'))}">
        ${_openItem}${_lifeItems}
      </div>
    </details>` : '';
  return `
    <span class="wsg-savestate is-${state}">${esc(lbl)}</span>
    <button type="button" class="wsh-cta is-primary wsg-savebtn" data-wstool-save${canSave ? '' : ' disabled'}>${esc(saveLabel)}</button>
    ${lifecycle}`;
}

function _wsToolMilestones(res) {
  const out = [];
  const TH = [50000, 100000, 250000, 500000, 1000000];
  for (const thr of TH) { const pt = res.series.find(s => s.total >= thr); if (pt && pt.year > 0) out.push(t('wstool_ms_cross')(_wsMoney(thr), pt.year)); }
  const cross = res.series.find(s => s.contributed > 0 && (s.total - s.contributed) > s.contributed);
  if (cross && cross.year > 0) out.push(t('wstool_ms_crossover')(cross.year));
  return out.slice(0, 5);
}

function _wsToolChartHtml(res, years) {
  const esc = _intccEsc;
  const W = 360, H = 170, pad = 24;
  const maxVal = Math.max.apply(null, res.series.map(s => s.total).concat([1]));
  const yrs = Math.max(1, years);
  const xF = y => pad + (y / yrs) * (W - 2 * pad);
  const yF = v => (H - pad) - (v / maxVal) * (H - 2 * pad);
  const totalPts = res.series.map(s => xF(s.year).toFixed(1) + ',' + yF(s.total).toFixed(1)).join(' ');
  const contribPts = res.series.map(s => xF(s.year).toFixed(1) + ',' + yF(s.contributed).toFixed(1)).join(' ');
  return `
    <svg class="wstool-chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(t('wstool_chart_title'))}">
      <line class="wsp-axis" x1="${pad}" y1="${H - pad}" x2="${W - pad}" y2="${H - pad}"/>
      <polygon class="wstool-area" points="${pad},${H - pad} ${totalPts} ${W - pad},${H - pad}"/>
      <polyline class="wstool-line is-total" points="${totalPts}"/>
      <polyline class="wstool-line is-contrib" points="${contribPts}"/>
      <text class="wsp-axis-x" x="${pad}" y="${H - 7}" text-anchor="start">${esc(t('wsp_axis_now'))}</text>
      <text class="wsp-axis-x" x="${W - pad}" y="${H - 7}" text-anchor="end">${esc(t('wsp_axis_year')(years))}</text>
    </svg>`;
}

// §B — LA PROYECCIÓN DE INTERÉS COMPUESTO PASA POR EL MOTOR COMPARTIDO.
// `inp.convention` viaja con la simulación GUARDADA: si la trae, se respeta; si no
// la trae, es de antes de este bloque y se computa con la convención con la que se
// calculó (nominal/12), porque reinterpretarla en silencio movería el resultado que
// el usuario guardó. Las simulaciones NUEVAS nacen con la efectiva (§A).
function _wsCompoundProjection(inp) {
  const i = inp || {};
  return _wsProject({
    initial: i.initial, monthly: i.monthly, years: i.years, annualRatePct: i.ret,
    convention: i.convention || _WS_PROJ_CONV.NOMINAL12,
    costPct: (i.costPct != null && String(i.costPct) !== '') ? i.costPct : null,
    inflationPct: (i.inflationPct != null && String(i.inflationPct) !== '') ? i.inflationPct : null,
  });
}
// ── LOS SUPUESTOS, ACCESIBLES Y SIN OPINIÓN (§A/§B) ─────────────────────────
// «No ocultar supuestos» y «supuestos accesibles». Se publica lo que ENTRÓ en el
// número: la tasa supuesta, su convención por su nombre, cuándo se aporta, y los
// costes y la inflación con su BASE cuando el usuario los ha activado. No hay
// ninguna recomendación de rentabilidad aquí: la tasa la pone el usuario y Aurix
// no opina sobre ella (§A lo prohíbe explícitamente).
//
// Y los campos que el usuario NO ha declarado se dicen: vacío no es cero, así que
// una proyección incompleta lo anuncia en vez de presentar un supuesto invisible.
function _wsAssumptionsHtml(p) {
  if (!p || !p.assumptions) return '';
  const esc = _intccEsc;
  const a = p.assumptions;
  const num = (v, d) => (typeof _intv4Num === 'function') ? _intv4Num(v, d == null ? 2 : d) : String(v);
  const rows = [];
  rows.push(String(t('wstool_asm_rate') || '').replace('{r}', num(a.annualRatePct, 2)));
  rows.push(String(t(a.convention === _WS_PROJ_CONV.NOMINAL12 ? 'wstool_asm_conv_nominal' : 'wstool_asm_conv_effective') || ''));
  rows.push(String(t(a.contributionTiming === _WS_PROJ_TIMING.BEGIN ? 'wstool_asm_timing_begin' : 'wstool_asm_timing_end') || ''));
  if (a.costPct > 0) rows.push(String(t('wstool_asm_cost') || '').replace('{c}', num(a.costPct, 2)).replace('{n}', num(a.netAnnualRatePct, 2)));
  if (a.inflationPct != null) rows.push(String(t('wstool_asm_infl') || '').replace('{i}', num(a.inflationPct, 2)));
  const unknown = (p.unknowns || []).filter(u => u !== 'cost' && u !== 'inflation');
  return `
      <details class="wstool-asm">
        <summary class="wstool-asm-sum">${esc(t('wstool_asm_title'))}</summary>
        <ul class="wstool-asm-list">${rows.filter(Boolean).map(r => `<li>${esc(r)}</li>`).join('')}</ul>
        ${unknown.length ? `<p class="wstool-asm-gap">${esc(t('wstool_asm_missing'))}</p>` : ''}
        ${p.realFinal != null ? `<p class="wstool-asm-real">${esc(String(t('wstool_asm_real') || '').replace('{v}', _wsMoney(p.realFinal)))}</p>` : ''}
      </details>`;
}
function _wsToolOutHtml(inp) {
  const esc = _intccEsc;
  const p = _wsCompoundProjection(inp);
  // El gráfico y los hitos siguen consumiendo la forma que ya conocían, DERIVADA
  // del motor: no se recalcula nada por segunda vez (§B «gráfico y hitos derivados
  // del cálculo»).
  const res = { final: p.final, contributed: p.initial + p.contributed, interest: p.growth,
                series: p.series.map(x => ({ year: x.year, total: x.value, contributed: x.initial + x.contributed })),
                multiple: (p.initial + p.contributed) > 0 ? p.final / (p.initial + p.contributed) : 1,
                gainPct: (p.initial + p.contributed) > 0 ? p.growth / (p.initial + p.contributed) * 100 : 0 };
  const ms = _wsToolMilestones(res);
  // §B — LOS CUATRO COMPONENTES, SEPARADOS. La versión anterior metía el capital
  // INICIAL dentro de «aportado», así que el usuario no podía saber cuánto había
  // puesto de golpe y cuánto mes a mes: dos hechos distintos en una sola cifra.
  return `
    <div class="wstool-result">
      <div class="wstool-res-main">
        <span class="wstool-res-label">${esc(t('wstool_res_final'))}</span>
        <span class="wstool-res-final">${esc(_wsMoney(p.final))}</span>
        <span class="wstool-res-orient">${esc(t('wstool_orient'))}</span>
      </div>
      ${/* §25 — LAS TRES COMPONENTES SE DISTINGUEN SIN LEER. Ya estaban separadas como cifras
            (lo hizo §B en su día) pero eran tres celdas idénticas: había que leer el rótulo para
            saber cuál era el dinero que pusiste, cuál el que fuiste poniendo y cuál el que
            generó. Cada una declara su acento por la API compartida — lo que ENTRA de golpe
            (info), lo que entra a plazos (in) y lo que produce el interés (green) — y el signo
            del crecimiento sigue siendo el que manda su color cuando es negativo. */''}
      <div class="wstool-res-split is-quad">
        <div class="wstool-res-cell" data-ws-accent="info"><span class="wstool-res-v">${esc(_wsMoney(p.initial))}</span><span class="wstool-res-k">${esc(t('wstool_res_initial'))}</span></div>
        <div class="wstool-res-cell" data-ws-accent="in"><span class="wstool-res-v">${esc(_wsMoney(p.contributed))}</span><span class="wstool-res-k">${esc(t('wstool_res_contrib'))}</span></div>
        <div class="wstool-res-cell${p.growth < 0 ? ' is-loss' : ' is-gain'}" data-ws-accent="${p.growth < 0 ? 'out' : 'up'}"><span class="wstool-res-v">${p.growth < 0 ? '−' : '+'}${esc(_wsMoney(Math.abs(p.growth)))}</span><span class="wstool-res-k">${esc(t('wstool_res_interest'))}</span></div>
      </div>
    </div>
    ${/* §25 — LA CURVA VA JUSTO DESPUÉS DE LAS CIFRAS. Los supuestos estaban DENTRO del bloque de
          resultado, así que se colaban entre el capital final y la curva: había que cruzar un
          desplegable para llegar al gráfico. `order` no los movía porque su padre era el bloque
          de resultado, no el contenedor — el arreglo es de MARCADO, no de CSS. Bajan a
          información secundaria, que es lo que son. */''}
    <div class="wstool-chart">
      ${_wsToolChartHtml(res, Math.max(1, Math.round(inp.years || 0)))}
      <div class="wsp-legend">
        <span class="wsp-leg is-base">${esc(t('wstool_legend_total'))}</span>
        <span class="wsp-leg is-cons">${esc(t('wstool_legend_contrib'))}</span>
      </div>
    </div>
    ${_wsAssumptionsHtml(p)}
    ${ms.length ? `<div class="wstool-ms"><span class="wstool-ms-title">${esc(t('wstool_ms_title'))}</span><ul class="wstool-ms-list">${ms.map(m => `<li>${esc(m)}</li>`).join('')}</ul></div>` : ''}`;
}

function _renderCompoundTool() {
  const esc = _intccEsc;
  if (!_wsToolInputs) _wsToolInputs = _wsToolDefaults();
  const inp = _wsToolInputs;
  const field = (k, label, unit) => `
    <label class="ws4-field">
      <span class="ws4-field-name">${esc(label)}</span>
      <span class="ws4-field-input">
        <input class="ws4-num" type="text" inputmode="decimal" autocomplete="off" data-wstool-input="${k}" value="${esc(_wsFormatInputNumber(inp[k]))}">
        ${_wsFieldUnitHtml(unit)}
      </span>
    </label>`;
  return `
    <div class="aurix-wsh wsh-tool-view is-revealed" data-wsh-view="tool" data-ws-accent="teal">
      ${_wsSurfaceHeadHtml({ title: t('wstool_compound_n'), doc: _wsToolDocName(), help: [t('wstool_compound_d')] })}
      ${_wsToolCcyRowHtml()}
      ${/* «DATOS DE ENTRADA» debajo de «Interés compuesto» no informaba de nada:
            los campos ya son visiblemente los datos de entrada. Se retira el
            título de sección, no los campos. */''}
      ${/* §25 — SOBRE EL ARMAZÓN COMPARTIDO. Mismo reparto que el Presupuesto: en escritorio la
            edición a la izquierda y la respuesta a la derecha (pegajosa), en móvil la edición
            primero y la curva después. No es una pantalla nueva: es la MISMA decisión de caja,
            que es justo lo que `.ws2col` existe para no volver a tomar. */''}
      <div class="ws2col">
        <div class="ws2col-edit">
          <section class="wsh-card wstool-inputs-card">
            <div class="wstool-fields">
              ${field('initial', t('wstool_in_initial'), _wsToolCcy())}
              ${field('monthly', t('wstool_in_monthly'), _wsToolCcy())}
              ${field('ret',     t('wstool_in_return'),  '%')}
              ${field('years',   t('wstool_in_years'),   t('wstool_unit_years'))}
            </div>
          </section>
        </div>
        <div class="ws2col-view">
          <section class="wsh-card wstool-out-card wscmp-out-card">
            <div class="wstool-out" data-wstool-out>${_wsToolOutHtml(inp)}</div>
          </section>
        </div>
      </div>
      ${/* §22 — los documentos de esta capacidad, DEBAJO del trabajo (bloque 5 del §6), así que
            el primer control útil que v740 certificó no se mueve. La misma primitiva plegada que
            usa Objetivos: un patrón, dos formas muy distintas de cuerpo. */''}
      ${_wsToolSavedListHtml()}
      <section class="wsh-card wsg-foot-card">
        <div class="wsg-savebar" data-wstool-savebar>${_wsToolSaveBarHtml()}</div>
      </section>
      <p class="wsb-disclaimer">${esc(t('wsb_disclaimer'))}</p>
    </div>`;
}

// ── WS.7 — Monthly Budget tool ───────────────────────────────────────────────
// "How much money do I actually have left each month?" Deterministic, pure, no
// APIs, no AI, no wealthEngine. Income − expenses → free money + savings rate.
const _WSBUD_INCOME = [
  { k: 'salary',   label: 'wstool_bud_salary' },
  { k: 'extra',    label: 'wstool_bud_extra' },
  { k: 'otherinc', label: 'wstool_bud_otherinc' },
];
const _WSBUD_EXPENSES = [
  { k: 'housing',   label: 'wstool_bud_housing',   color: '#4D8DFF' },
  { k: 'food',      label: 'wstool_bud_food',      color: '#37c7b8' },
  { k: 'transport', label: 'wstool_bud_transport', color: '#8a7dff' },
  { k: 'utilities', label: 'wstool_bud_utilities', color: '#e0b15c' },
  { k: 'leisure',   label: 'wstool_bud_leisure',   color: '#e07a9f' },
  { k: 'education', label: 'wstool_bud_education', color: '#6fcf97' },
  { k: 'otherexp',  label: 'wstool_bud_other',     color: '#7c89a3' },
];

// ════════════════════════════════════════════════════════════════════════════
// LAS CATEGORÍAS SON DEL USUARIO: FILAS CON IDENTIDAD, NO CLAVES FIJAS
// ════════════════════════════════════════════════════════════════════════════
// Hasta aquí el documento guardaba diez claves planas (`salary`, `housing`…) y
// el nombre de cada una salía de i18n: no había forma de llamar «Baile» a
// «Formación» ni de tener un segundo ingreso. Ahora `inputs.rows` es la fuente
// de verdad —`{ id, type, labelKey, label, amount, color, order }`— y vive en el
// MISMO documento, así que guarda, abre, duplica y sincroniza por los caminos que
// ya existían (el cuerpo viaja entero en `_wsDocRows`).
//   · IDENTIDAD = `id`. El texto visible no identifica nada: dos gastos llamados
//     igual son dos gastos, y el donut enlaza por `id`.
//   · `label` es el nombre que escribió el usuario; `null` significa «el nombre
//     sugerido», que se lee de `labelKey` en el idioma activo. Así una categoría
//     sin tocar sigue diciendo «Housing» en inglés.
//   · COLOR estable por identidad: se fija al crear la fila y se guarda.
// COMPATIBILIDAD: un documento sin `rows` se LEE como las diez filas de siempre,
// con sus importes exactos y los ids iguales a las claves antiguas. No se migra
// nada en el almacén: la forma nueva se escribe sólo cuando el usuario guarda. Y
// las claves planas se siguen escribiendo como ESPEJO de las filas que conservan
// su id, para que un cliente con el bundle anterior no lea importes inventados.
const _WSBUD_PALETTE = Object.freeze(['#4D8DFF', '#37c7b8', '#8a7dff', '#e0b15c', '#e07a9f', '#6fcf97', '#7c89a3',
  '#5cc8ff', '#f2956b', '#b58cff', '#a3d65c', '#ff7fb5', '#46b0a0', '#d9a441']);
// Límite TÉCNICO, no de producto: ningún presupuesto razonable llega a 40 partidas
// por bloque, y sin tope un documento podría crecer sin medida en cada sync.
const _WSBUD_ROW_MAX = 40;
const _WSBUD_LABEL_MAX = 60;
const _WSBUD_LEGACY_KEYS = Object.freeze(_WSBUD_INCOME.concat(_WSBUD_EXPENSES).map(f => f.k));
function _wsBudgetColorFor(id) {
  let h = 0; const s = String(id || '');
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return _WSBUD_PALETTE[h % _WSBUD_PALETTE.length];
}
function _wsBudgetLegacyRows(inp) {
  const src = inp || {};
  let order = 0;
  const mk = (f, type) => ({ id: f.k, type: type, labelKey: f.label, label: null,
    amount: src[f.k] != null ? src[f.k] : 0, color: type === 'expense' ? (f.color || _wsBudgetColorFor(f.k)) : null, order: order++ });
  return _WSBUD_INCOME.map(f => mk(f, 'income')).concat(_WSBUD_EXPENSES.map(f => mk(f, 'expense')));
}
// Lee las filas de cualquier documento, nuevo o antiguo, y devuelve COPIAS: quien
// las modifique no puede tocar el objeto del que salieron.
function _wsBudgetRows(inp) {
  if (!inp || !Array.isArray(inp.rows)) return _wsBudgetLegacyRows(inp);
  const seen = new Set(), out = [];
  inp.rows.forEach((r, i) => {
    if (!r || typeof r !== 'object') return;
    const id = (typeof r.id === 'string' && r.id) ? r.id : null;
    if (!id || seen.has(id) || (r.type !== 'income' && r.type !== 'expense')) return;
    seen.add(id);
    out.push({ id: id, type: r.type,
      labelKey: typeof r.labelKey === 'string' ? r.labelKey : null,
      label: typeof r.label === 'string' ? r.label : null,
      amount: r.amount == null ? 0 : r.amount,
      color: r.type === 'expense' ? ((typeof r.color === 'string' && /^#[0-9a-fA-F]{6}$/.test(r.color)) ? r.color : _wsBudgetColorFor(id)) : null,
      order: Number.isFinite(Number(r.order)) ? Number(r.order) : i });
  });
  return out.map((r, i) => [r, i]).sort((a, b) => (a[0].order - b[0].order) || (a[1] - b[1])).map(x => x[0]);
}
// El nombre que se ENSEÑA: el del usuario si lo escribió, si no el sugerido.
// Nunca devuelve vacío mientras exista una sugerencia.
function _wsBudgetRowName(r) {
  if (r && typeof r.label === 'string' && r.label.trim()) return r.label.trim();
  const d = (r && r.labelKey) ? t(r.labelKey) : '';
  return (typeof d === 'string' && d) ? d : (r && r.type === 'income' ? t('wsbud_new_income') : t('wsbud_new_expense'));
}

function calculateMonthlyBudget(inp) {
  inp = inp || {};
  const num = v => Math.max(0, _wsNum(v));  // WS.15A tolerant parse
  // MISMA ARITMÉTICA sobre las filas: Σ ingresos − Σ gastos. Un documento antiguo
  // se lee como sus diez filas de siempre y da exactamente el mismo resultado.
  const rows = _wsBudgetRows(inp);
  const income = rows.filter(r => r.type === 'income').reduce((s, r) => s + num(r.amount), 0);
  const items = rows.filter(r => r.type === 'expense').map(r => ({ k: r.id, id: r.id, label: r.labelKey,
    name: _wsBudgetRowName(r), color: r.color, value: num(r.amount) }));
  const expenses = items.reduce((s, it) => s + it.value, 0);
  const free = income - expenses;
  // ── §F · CON INGRESOS CERO LA TASA DE AHORRO NO EXISTE ────────────────────
  // Devolvía 0, y la superficie pintaba «0 %»: eso afirma que no ahorras nada,
  // cuando lo cierto es que la razón NO SE PUEDE CALCULAR —su denominador es cero—.
  // §F lo dice por su nombre: «Ingresos cero: no aplicable». `null` no es 0, y así
  // la superficie puede escribir «no aplicable» en vez de un cero falso.
  const saveRate = income > 0 ? (free / income) * 100 : null;
  return {
    income, expenses, free, saveRate, items,
    // El DENOMINADOR, declarado: la tasa es sobre INGRESOS, no sobre gastos ni
    // sobre patrimonio, y §F exige explicarlo.
    saveRateBasis: income > 0 ? 'share_of_income' : null,
    applicable: income > 0,
    deficit: free < 0,
  };
}

function _wsBudgetDefaults() {
  return { salary: 2500, extra: 0, otherinc: 0, housing: 700, food: 350, transport: 120, utilities: 110, leisure: 150, education: 50, otherexp: 100 };
}

// ── §26/§11 · EL REPARTO, EN DONUT ────────────────────────────────────────────────────────────
// SVG puro con `stroke-dasharray`: ninguna librería, ningún canvas, y el color de cada categoría
// es el que YA declara `_WSBUD_EXPENSES` — no se inventa una paleta nueva para este gráfico.
// Sin gastos NO se dibuja: un donut de una sola porción gris no informa de nada y un anillo
// vacío parece un cero medido (§44). El centro publica el DISPONIBLE, que es la cifra por la que
// el usuario abre esta plantilla.
// Accesible: el anillo es `role="img"` con la reparto en palabras, porque un gráfico sin texto no
// es un dato para quien usa lector de pantalla (§38).
const _WSBUD_DONUT_R = 52, _WSBUD_DONUT_C = 2 * Math.PI * _WSBUD_DONUT_R;
// ── EL ANILLO ES INTERACTIVO, Y LA SELECCIÓN NO TOCA NINGUNA CIFRA ─────────────
// `sel` es el `id` de una categoría (o nada). Seleccionar sólo cambia QUÉ se lee:
// el segmento se resalta, el resto se atenúa sin volverse ilegible y el centro
// dice nombre, importe y porcentaje de esa categoría. El reparto es el mismo.
var _wsBudSel = null;
function _wsBudgetDonutHtml(res, sel) {
  const esc = _intccEsc;
  const items = res.items.filter(it => it.value > 0);
  if (!(res.expenses > 0) || !items.length) return '';
  const pick = sel ? items.find(it => it.id === sel) : null;
  let off = 0;
  const arcs = items.map(it => {
    const frac = it.value / res.expenses;
    const len = frac * _WSBUD_DONUT_C;
    const st = pick ? (it === pick ? ' is-sel' : ' is-dim') : '';
    const seg = '<circle class="wsbud-arc' + st + '" data-wsbud-seg="' + esc(it.id) + '" cx="60" cy="60" r="' + _WSBUD_DONUT_R + '" fill="none"'
      + ' stroke="' + esc(it.color) + '" stroke-width="14" stroke-linecap="butt"'
      + ' stroke-dasharray="' + len.toFixed(3) + ' ' + (_WSBUD_DONUT_C - len).toFixed(3) + '"'
      + ' stroke-dashoffset="' + (-off).toFixed(3) + '"></circle>';
    off += len;
    return seg;
  }).join('');
  const words = items.map(it => Math.round(it.value / res.expenses * 100) + '% ' + it.name).join(' · ');
  // EL CENTRO NO REPITE UN KPI. «Disponible» ya está en el resumen de arriba, y decirlo otra vez
  // aquí es el MISMO defecto de duplicación que este bloque cerró en su día con la tasa de ahorro.
  // Lo que el anillo no puede decir con precisión es CUÁL manda y cuánto: eso va al centro.
  const top = items.slice().sort((a, b) => b.value - a.value)[0];
  const topPct = Math.round(top.value / res.expenses * 100);
  const centre = pick
    ? '<i style="color:' + esc(pick.color) + '">' + esc(pick.name) + '</i>'
      + '<b>' + Math.round(pick.value / res.expenses * 100) + '%</b>'
      + '<em>' + esc(_wsMoney(pick.value)) + '</em>'
    : '<i style="color:' + esc(top.color) + '">' + esc(top.name) + '</i>'
      + '<b>' + topPct + '%</b>'
      + '<em>' + esc(t('wsbud_dn_top')) + '</em>';
  return '<div class="wsbud-donut' + (pick ? ' has-sel' : '') + '">'
    + '<svg viewBox="0 0 120 120" role="img" aria-label="' + esc(t('wstool_bud_chart_title') + ': ' + words) + '">'
    + '<circle cx="60" cy="60" r="' + _WSBUD_DONUT_R + '" fill="none" stroke="rgba(120,160,255,0.14)" stroke-width="14"></circle>'
    + '<g transform="rotate(-90 60 60)">' + arcs + '</g>'
    + '</svg>'
    + '<span class="wsbud-donut-c" aria-live="polite">' + centre + '</span>'
    + '</div>';
}
// LEYENDA = el control accesible del anillo. Cada categoría es un botón con
// `aria-pressed`: ratón, toque y teclado pasan por el MISMO sitio. Ordenada por
// PESO, que es cómo se lee un reparto; el orden del formulario no cambia.
function _wsBudgetChartHtml(res, sel) {
  const esc = _intccEsc;
  const items = res.items.filter(it => it.value > 0).slice().sort((a, b) => b.value - a.value);
  const pct = v => (res.expenses > 0 ? Math.round(v / res.expenses * 100) : 0) + '%';
  const legend = items.map(it => {
    const on = sel === it.id;
    return `<li><button type="button" class="wsbud-leg${on ? ' is-sel' : ''}" data-wsbud-sel="${esc(it.id)}" aria-pressed="${on ? 'true' : 'false'}">`
      + `<i style="background:${esc(it.color)}"></i><span class="wsbud-leg-n">${esc(it.name)}</span>`
      + `<b>${esc(_wsMoney(it.value))}</b><em>${pct(it.value)}</em></button></li>`;
  }).join('');
  // «DINERO LIBRE» NO ES UNA PORCIÓN DEL ANILLO. Estaba en la misma lista que las
  // categorías, con su punto de color y sin porcentaje, y el anillo (que reparte sólo
  // el GASTO) no tiene ningún segmento suyo: se leía como una categoría más. Sale de
  // la lista y se dice qué es: lo no asignado, su proporción sobre INGRESOS y que no
  // entra en el reparto. No se interpreta como «ahorro»: el usuario puede tener sus
  // propias categorías de ahorro dentro de los gastos.
  const freeLeg = res.free > 0 ? `<p class="wsbud-free-note"><b>${esc(t('wstool_bud_free'))}</b> ${esc(String(t(res.saveRate == null ? 'wsbud_free_note_nr' : 'wsbud_free_note')).replace('{a}', _wsMoney(res.free)).replace('{r}', String(Math.round(res.saveRate || 0))))}</p>` : '';
  return `
    <div class="wsbud-chart-wrap">
      ${/* §18 — LA BARRA DE REPARTO SE RETIRA, y se auditó antes de decidirlo. Contaba lo MISMO
            que el anillo (el reparto del gasto) más una cosa: el dinero libre como parte del
            ingreso. Pero eso YA lo dicen el «Disponible» del resumen y su tasa de ahorro, que es
            literalmente esa proporción. Dos visualizaciones de lo mismo no son el doble de
            información: son el doble de altura. La LEYENDA se queda —lleva el importe por
            categoría, que el anillo no sabe decir— y con ella «Dinero libre». */''}
      ${legend ? `<p class="wsbud-leg-basis">${esc(t('wsbud_leg_basis'))}</p>` : ''}
      <ul class="wsbud-legend" aria-label="${esc(t('wsbud_legend_label') + ' · ' + t('wsbud_leg_basis'))}">${legend}</ul>
      ${freeLeg}
    </div>`;
}
// Sin gastos no hay reparto que dibujar, y un anillo de un color sería un reparto
// inventado. Se dice qué falta y se lleva al sitio donde se arregla.
function _wsBudgetEmptyHtml() {
  const esc = _intccEsc;
  return '<div class="wsbud-empty">'
    + '<svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="' + _WSBUD_DONUT_R + '" fill="none" stroke="rgba(120,160,255,0.14)" stroke-width="14"></circle></svg>'
    + '<p class="wsbud-empty-t">' + esc(t('wsbud_empty')) + '</p>'
    + '<button type="button" class="wsbud-empty-cta" data-wsbud-goto="expense">' + esc(t('wsbud_empty_cta')) + '</button>'
    + '</div>';
}

// ════════════════════════════════════════════════════════════════════════════
// §10 · EL PERIODO DEL PRESUPUESTO — OPCIONAL, EXPLÍCITO Y NUNCA INFERIDO
// ════════════════════════════════════════════════════════════════════════════
// `periodKey` es «YYYY-MM» y vive en el payload del documento, así que viaja con
// la sincronización sin tocar el esquema. Es OPCIONAL por compatibilidad: un
// documento anterior no lo tiene y se lee «Sin periodo» hasta que el usuario
// elija uno. NO se deduce de `createdAt` ni de la fecha de hoy — inferirlo sería
// afirmar que un presupuesto guardado en marzo ES el de marzo, que es justo lo
// que nadie ha declarado.
//
// Y el selector EDITA EL BORRADOR. No guarda, no duplica, no mueve el documento
// y no abre otro: cambiar el mes no puede ser una operación de archivo.
function _wsBudgetCurrentPeriod() {
  const d = new Date();
  return String(d.getFullYear()) + '-' + String(d.getMonth() + 1).padStart(2, '0');
}
function _wsPeriodLabel(key) {
  const m = /^(\d{4})-(\d{2})$/.exec(String(key || ''));
  if (!m) return t('wsbud_period_none');
  const y = Number(m[1]), mo = Number(m[2]);
  if (!(mo >= 1 && mo <= 12)) return t('wsbud_period_none');
  try {
    return new Intl.DateTimeFormat((typeof lang !== 'undefined' && lang === 'en') ? 'en-GB' : 'es-ES',
      { month: 'long', year: 'numeric' }).format(new Date(y, mo - 1, 1));
  } catch (_) { return m[1] + '-' + m[2]; }
}
// §11 — LA FORMA CORTA, para el chip de la cabecera. «septiembre de 2026» mide 164 px y a 360
// hacía SALTAR DE LÍNEA la barra entera: 128 px de cabecera en vez de 78. «sept 2026» cabe al
// lado del título, que es justo el formato que el §11 pone como ejemplo. La forma larga se
// conserva para el desplegable abierto, donde sí hay sitio y desambigua mejor.
function _wsPeriodLabelShort(key) {
  const m = /^(\d{4})-(\d{2})$/.exec(String(key || ''));
  if (!m) return t('wsbud_period_none');
  const y = Number(m[1]), mo = Number(m[2]);
  if (!(mo >= 1 && mo <= 12)) return t('wsbud_period_none');
  try {
    return new Intl.DateTimeFormat((typeof lang !== 'undefined' && lang === 'en') ? 'en-GB' : 'es-ES',
      { month: 'short', year: 'numeric' }).format(new Date(y, mo - 1, 1)).replace(/\./g, '');
  } catch (_) { return m[1] + '-' + m[2]; }
}
// Las opciones: «Sin periodo», los doce meses anteriores, el actual, el
// siguiente, y —si el documento trae uno fuera de ese rango— el suyo. Un
// documento de 2019 no puede quedarse sin su propia opción en la lista.
function _wsPeriodOptions(current) {
  const out = [];
  const now = new Date();
  for (let i = 12; i >= -1; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    out.push(String(d.getFullYear()) + '-' + String(d.getMonth() + 1).padStart(2, '0'));
  }
  const cur = String(current || '');
  if (/^\d{4}-\d{2}$/.test(cur) && out.indexOf(cur) === -1) out.unshift(cur);
  return out;
}
// El RESUMEN y el PERIODO, arriba del todo. Antes el usuario tenía que cruzar
// diez campos para ver cuánto le queda, que es la única cifra por la que abre
// esta plantilla.
// §11 — EL PERIODO, COMPACTO Y EN LA CABECERA. No se elimina porque tiene función demostrada: no
// entra en `calculateMonthlyBudget` (cero referencias) pero vive en `inputs`, así que viaja en el
// payload del documento con la sincronización, y `_wsSaveCandidates` lo usa para DISTINGUIR un
// documento de otro en el selector. Un control con función no se retira; un control secundario
// tampoco se queda con una franja entera del móvil.
function _wsBudgetPeriodHtml(inp) {
  const esc = _intccEsc;
  const cur = (inp && inp.periodKey) ? String(inp.periodKey) : '';
  const opts = _wsPeriodOptions(cur);
  return '<label class="wsbud-perchip">'
    + '<span class="wsbud-perchip-lbl">' + esc(t('wsbud_period')) + '</span>'
    + '<select class="wsbud-perchip-sel" data-wsbud-period aria-label="' + esc(t('wsbud_period')) + '">'
    +   '<option value=""' + (cur ? '' : ' selected') + '>' + esc(t('wsbud_period_none')) + '</option>'
    +   opts.map(k => '<option value="' + esc(k) + '"' + (k === cur ? ' selected' : '') + '>'
          + esc(k === cur ? _wsPeriodLabelShort(k) : _wsPeriodLabel(k)) + '</option>').join('')
    + '</select></label>';
}
function _wsBudgetTopHtml(inp) {
  const esc = _intccEsc;
  const res = calculateMonthlyBudget(inp);
  return `
    <div class="wsbud-top">
      ${/* §27 — LAS CUATRO MAGNITUDES SE DISTINGUEN SIN LEER. Ingresos, gastos y disponible
            llevan acento propio (entra, sale, queda) y no dependen sólo del rótulo: hasta ahora
            ingresos y gastos eran dos celdas idénticas y había que leerlas para saber cuál era
            cuál. El acento es un TONO en el filete y la cifra, no un relleno de color. */''}
      <div class="wsbud-kpis">
        <span class="wsbud-kpi" data-ws-accent="in"><i>${esc(t('wstool_bud_income_t'))}</i><b>${esc(_wsMoney(res.income))}</b></span>
        <span class="wsbud-kpi" data-ws-accent="out"><i>${esc(t('wstool_bud_expenses_t'))}</i><b>${esc(_wsMoney(res.expenses))}</b></span>
        ${/* §15 — LA TASA DE AHORRO ACOMPAÑA, NO REINA. Tenía una tarjeta propia de 123 px de alto
              para una cifra secundaria. Aquí va pegada al disponible, que es su denominador
              natural, y se dice sobre qué se calcula. Cuando no hay ingresos no se publica un
              0 %: el motor devuelve `null` y aquí no se pinta el sufijo. */''}
        <span class="wsbud-kpi is-main" data-ws-accent="info"><i>${esc(t('wstool_bud_avail'))}</i><b class="${res.free < 0 ? 'is-neg' : 'is-pos'}">${esc(_wsMoney(res.free))}</b>${
          (res.saveRate == null || res.saveRate < 0) ? '' : `<em class="wsbud-kpi-sub">${esc(Math.round(res.saveRate) + '% ' + t('wsbud_kpi_save'))}</em>`}</span>
        ${/* §11 — EL PERIODO, CUARTA CELDA DEL RESUMEN. Estuvo en la línea del título y la CAPTURA
              lo tumbó: a 360 el chip dejaba «Presupuesto mensual» en una columna de 30 px —una
              letra por línea, 254 px de cabecera— y encima el mes salía truncado («sept …»), que
              es peor que no ponerlo: un periodo ilegible no identifica nada. Aquí comparte fila
              con las cifras que CALIFICA, así que no cuesta un píxel de altura, se lee entero y la
              cabecera vuelve a ser la de v740. */''}
        ${_wsBudgetPeriodHtml(inp)}
      </div>
      ${/* UNA SOLA LECTURA. Aquí se repetía el déficit que la lectura junto al gráfico ya dice
            con las mismas palabras; se queda allí, que es donde se entiende. */''}
    </div>`;
}
// ── UNA SOLA LECTURA FINANCIERA ────────────────────────────────────────────────
// El déficit va PRIMERO porque es un hecho aritmético aunque no haya ingresos
// (gastar 100 sin ingresar nada es superar los ingresos en 100). Disponible cero
// tiene su propia frase, exacta y neutra. Sin ingresos ni gastos, la frase dice
// lo único cierto: que la proporción no se puede calcular. Nada de consejos.
function _wsBudgetReading(res) {
  if (res.deficit) return String(t('wstool_bud_read_deficit') || '').replace('{d}', _wsMoney(Math.abs(res.free)));
  if (!res.applicable) return t('wstool_bud_read_noincome');
  if (res.free === 0) return t('wsbud_read_zero');
  return String(t('wstool_bud_read_neutral') || '').replace('{r}', String(Math.round(res.saveRate)));
}
function _wsBudgetOutHtml(inp) {
  const esc = _intccEsc;
  const res = calculateMonthlyBudget(inp);
  // La selección sólo sobrevive si su categoría sigue en el reparto.
  if (_wsBudSel && !res.items.some(it => it.id === _wsBudSel && it.value > 0)) _wsBudSel = null;
  const reading = _wsBudgetReading(res);
  const donut = _wsBudgetDonutHtml(res, _wsBudSel);
  return `
    <div class="wstool-chart wsbud-chartbox">
      <span class="wsbud-chart-title">${esc(t('wstool_bud_chart_title'))}</span>
      <div class="wsbud-viz">${donut ? donut + _wsBudgetChartHtml(res, _wsBudSel) : _wsBudgetEmptyHtml()}</div>
    </div>
    ${reading ? `<p class="wsbud-reading">${esc(reading)}</p>` : ''}`;
}
// §F — el DENOMINADOR de la tasa y la naturaleza de la cifra, dichos. Plegado:
// ayuda, no protagonista. Tiene su propio contenedor de repintado porque cita la
// tasa, que cambia con cada tecla.
function _wsBudgetHelpHtml(inp) {
  const esc = _intccEsc;
  const res = calculateMonthlyBudget(inp);
  const rateTxt = res.saveRate == null ? t('wstool_bud_na') : Math.round(res.saveRate) + '%';
  return `
    <details class="wstool-asm wsbud-basis">
      <summary class="wstool-asm-sum">${esc(t('wstool_bud_basis_title'))}</summary>
      <ul class="wstool-asm-list">
        <li>${esc(t('wstool_bud_basis_plan'))}</li>
        <li>${esc(t('wstool_bud_basis_denom'))}</li>
        <li>${esc(t('wstool_bud_saverate') + ': ' + rateTxt + ' — ' + t('wstool_bud_rate_basis'))}</li>
        <li>${esc(t('wstool_bud_basis_notcat'))}</li>
      </ul>
    </details>`;
}

// ── EL EDITOR: NOMBRE ENCIMA, IMPORTE DEBAJO ───────────────────────────────────
// El nombre se lee como TEXTO (un botón sin caja) y al pulsarlo pasa a campo con el
// contenido seleccionado. Así no hay veinte cajas pesadas en pantalla y un nombre
// largo se parte por palabras en vez de recortarse dentro de un `<input>`.
function _wsBudgetRowHtml(r) {
  const esc = _intccEsc;
  const name = _wsBudgetRowName(r);
  return `
    <div class="wsbud-row${_wsBudSel === r.id ? ' is-sel' : ''}" data-wsbud-row="${esc(r.id)}">
      <div class="wsbud-row-head">
        <button type="button" class="wsbud-name" data-wsbud-rename="${esc(r.id)}" aria-label="${esc(String(t('wsbud_name_aria')).replace('{n}', name))}">${esc(name)}</button>
        <button type="button" class="wsbud-del" data-wsbud-del="${esc(r.id)}" aria-label="${esc(String(t('wsbud_del_aria')).replace('{n}', name))}"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M4.5 4.5l7 7M11.5 4.5l-7 7"/></svg></button>
      </div>
      <span class="ws4-field-input">
        <input class="ws4-num" type="text" inputmode="decimal" autocomplete="off" data-wsbud-amt="${esc(r.id)}" aria-label="${esc(String(t('wsbud_amt_aria')).replace('{n}', name))}" value="${esc(_wsFormatInputNumber(r.amount != null ? r.amount : 0))}">
        ${_wsFieldUnitHtml('€')}
      </span>
    </div>`;
}
function _wsBudgetListHtml(inp, type) {
  const esc = _intccEsc;
  const rows = _wsBudgetRows(inp).filter(r => r.type === type);
  const full = rows.length >= _WSBUD_ROW_MAX;
  return `<div class="wsbud-rows">${rows.map(_wsBudgetRowHtml).join('')}</div>
    <button type="button" class="wsbud-add" data-wsbud-add="${type}"${full ? ' disabled aria-describedby="wsbudLim-' + type + '"' : ''}>
      <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 3.5v9M3.5 8h9"/></svg>${esc(t(type === 'income' ? 'wsbud_add_income' : 'wsbud_add_expense'))}</button>
    ${full ? `<p class="wsbud-limit" id="wsbudLim-${type}">${esc(String(t('wsbud_limit')).replace('{m}', String(_WSBUD_ROW_MAX)))}</p>` : ''}`;
}
// Un borrador sin filas (documento antiguo o recién creado) las ADOPTA al pintarse,
// con los mismos importes: no cambia ninguna cifra, así que no se marca como sucio.
function _wsBudgetAdopt(inp) {
  if (inp && !Array.isArray(inp.rows)) inp.rows = _wsBudgetRows(inp);
  return inp;
}
// Todo cambio de filas pasa por aquí: filas NUEVAS (nunca se muta el array de
// origen), orden reescrito, espejo de las claves antiguas, borrador sucio y estado
// de acceso rápido al día.
function _wsBudgetSetRows(rows, quiet) {
  const inp = _wsToolInputs; if (!inp) return;
  inp.rows = rows.map((r, i) => Object.assign({}, r, { order: i }));
  _WSBUD_LEGACY_KEYS.forEach(k => { const r = inp.rows.find(x => x.id === k); inp[k] = r ? r.amount : 0; });
  if (!quiet) _wsToolDirty = true;
  try { _wsToolStateSet(_wsToolActive, inp); } catch (_) {}
}
function _wsBudgetRoot() { try { return document.querySelector('.wsh-tool-view[data-wsbud-view]'); } catch (_) { return null; } }
// Repinta las LECTURAS (resumen, gráfico, ayuda, barra), nunca el campo enfocado.
function _wsBudgetRepaint() {
  const root = _wsBudgetRoot(); if (!root || !_wsToolInputs) return;
  const set = (sel, html) => { const el = root.querySelector(sel); if (el) el.innerHTML = html; };
  const focusSel = (document.activeElement && document.activeElement.getAttribute) ? document.activeElement.getAttribute('data-wsbud-sel') : null;
  set('[data-wsbud-top]', _wsBudgetTopHtml(_wsToolInputs));
  set('[data-wstool-out]', _wsBudgetOutHtml(_wsToolInputs));
  const help = root.querySelector('[data-wsbud-help]');
  if (help) { const open = !!(help.querySelector('details') || {}).open; help.innerHTML = _wsBudgetHelpHtml(_wsToolInputs); if (open) { const d = help.querySelector('details'); if (d) d.open = true; } }
  { const bar = root.querySelector('[data-wstool-savebar]');
    if (typeof _wsToolSaveBarSync === 'function') _wsToolSaveBarSync(bar); else if (bar) bar.innerHTML = _wsToolSaveBarHtml(); }
  root.querySelectorAll('.wsbud-row').forEach(el => el.classList.toggle('is-sel', el.getAttribute('data-wsbud-row') === _wsBudSel));
  if (focusSel) { const b = root.querySelector('[data-wsbud-sel="' + focusSel + '"]'); if (b) b.focus(); }
}
function _wsBudgetRepaintList(type) {
  const root = _wsBudgetRoot(); if (!root) return;
  const host = root.querySelector('[data-wsbud-list="' + type + '"]');
  if (host) host.innerHTML = _wsBudgetListHtml(_wsToolInputs, type);
}
function _wsBudgetOnAmount(el) {
  const id = el.getAttribute('data-wsbud-amt');
  const rows = _wsBudgetRows(_wsToolInputs);
  const i = rows.findIndex(r => r.id === id); if (i < 0) return;
  const prev = rows[i].amount, next = el.value;
  // EL MISMO NÚMERO NO ES UNA EDICIÓN. Al salir del campo el formateador reemite su forma
  // canónica («1.400» → «1400»): se guarda esa forma, pero sin ensuciar el borrador y sin
  // repintar. Repintar ahí sustituía el anillo BAJO EL DEDO (el primer toque sobre un segmento
  // con un campo enfocado no llegaba) y, al guardar con un campo enfocado, el documento recién
  // guardado volvía a figurar como pendiente.
  const same = String(prev) === String(next)
    || (String(prev).trim() !== '' && String(next).trim() !== '' && _wsNum(prev) === _wsNum(next));
  rows[i] = Object.assign({}, rows[i], { amount: next });   // WS.15A: crudo durante la edición
  _wsBudgetSetRows(rows, same);
  if (!same) _wsBudgetRepaint();
}
function _wsBudgetSelect(id) {
  _wsBudSel = (id && _wsBudSel !== id) ? id : null;
  _wsBudgetRepaint();
}
function _wsBudgetAdd(type) {
  const rows = _wsBudgetRows(_wsToolInputs);
  if (rows.filter(r => r.type === type).length >= _WSBUD_ROW_MAX) return;
  const used = new Set(rows.filter(r => r.type === 'expense').map(r => String(r.color).toLowerCase()));
  const free = _WSBUD_PALETTE.find(c => !used.has(c.toLowerCase()));
  const id = 'r' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  const row = { id: id, type: type, labelKey: type === 'income' ? 'wsbud_new_income' : 'wsbud_new_expense', label: null, amount: '',
    color: type === 'expense' ? (free || _wsBudgetColorFor(id)) : null };
  // La fila nueva va al FINAL de su bloque, sin mover las del otro.
  let at = -1; rows.forEach((r, k) => { if (r.type === type) at = k; });
  rows.splice(at + 1, 0, row);
  _wsBudgetSetRows(rows);
  _wsBudgetRepaintList(type);
  _wsBudgetRepaint();
  _wsBudgetRenameStart(id);
}
function _wsBudgetDelete(id) {
  const rows = _wsBudgetRows(_wsToolInputs);
  const r = rows.find(x => x.id === id); if (!r) return;
  const go = () => {
    const next = _wsBudgetRows(_wsToolInputs).filter(x => x.id !== id);
    if (_wsBudSel === id) _wsBudSel = null;
    _wsBudgetSetRows(next);
    _wsBudgetRepaintList(r.type);
    _wsBudgetRepaint();
    const root = _wsBudgetRoot(); const add = root && root.querySelector('[data-wsbud-add="' + r.type + '"]');
    if (add) add.focus();
  };
  // Sólo se pregunta cuando se pierde un dato: una fila vacía o a cero se va sin más.
  if (_wsNum(r.amount) === 0) { go(); return; }
  _wsModal2({ title: t('wsbud_del_title'),
    text: String(t('wsbud_del_text')).replace('{n}', _wsBudgetRowName(r)).replace('{a}', _wsMoney(_wsNum(r.amount))),
    okLabel: t('wsmodal_delete'), danger: true, onOk: go });
}
// ── RENOMBRAR ──────────────────────────────────────────────────────────────────
// Enter o tocar fuera confirman; Escape restaura; vacío restaura el último nombre
// válido. La edición en vivo mueve leyenda y centro sin esperar a confirmar.
var _wsBudRename = null;   // { id, prev } — `prev` es el `label` guardado al empezar
function _wsBudgetRenameStart(id) {
  const root = _wsBudgetRoot(); if (!root) return;
  const btn = root.querySelector('[data-wsbud-rename="' + id + '"]'); if (!btn) return;
  const r = _wsBudgetRows(_wsToolInputs).find(x => x.id === id); if (!r) return;
  _wsBudRename = { id: id, prev: r.label };
  const inp = document.createElement('input');
  inp.type = 'text'; inp.className = 'wsbud-name-in'; inp.setAttribute('data-wsbud-name-in', id);
  inp.setAttribute('maxlength', String(_WSBUD_LABEL_MAX)); inp.setAttribute('autocomplete', 'off');
  inp.setAttribute('enterkeyhint', 'done'); inp.setAttribute('spellcheck', 'false');
  inp.setAttribute('aria-label', t('wsbud_name_field'));
  inp.value = _wsBudgetRowName(r);
  btn.replaceWith(inp);
  inp.focus(); try { inp.select(); } catch (_) {}
}
function _wsBudgetOnNameInput(el) {
  const id = el.getAttribute('data-wsbud-name-in');
  const v = String(el.value || '');
  if (!v.trim()) return;                         // vacío: se espera, no se guarda un nombre vacío
  const rows = _wsBudgetRows(_wsToolInputs);
  const i = rows.findIndex(r => r.id === id); if (i < 0) return;
  rows[i] = Object.assign({}, rows[i], { label: v.slice(0, _WSBUD_LABEL_MAX) });
  _wsBudgetSetRows(rows);
  _wsBudgetRepaint();
}
var _wsBudRenameBusy = false;
function _wsBudgetRenameEnd(el, mode) {
  // Sustituir el campo enfocado dispara su `focusout` DENTRO de esta misma llamada: sin el
  // cerrojo, esa segunda pasada rehacía la cabecera y el foco se perdía.
  if (!el || !el.isConnected || _wsBudRenameBusy) return;
  _wsBudRenameBusy = true;
  try { _wsBudgetRenameEndInner(el, mode); } finally { _wsBudRenameBusy = false; }
}
function _wsBudgetRenameEndInner(el, mode) {
  const id = el.getAttribute('data-wsbud-name-in');
  const st = _wsBudRename && _wsBudRename.id === id ? _wsBudRename : null;
  _wsBudRename = null;
  const rows = _wsBudgetRows(_wsToolInputs);
  const i = rows.findIndex(r => r.id === id);
  if (i >= 0 && st && (mode === 'cancel' || !String(el.value || '').trim()) && rows[i].label !== st.prev) {
    rows[i] = Object.assign({}, rows[i], { label: st.prev });
    _wsBudgetSetRows(rows);
  }
  const row = i >= 0 ? _wsBudgetRows(_wsToolInputs).find(r => r.id === id) : null;
  if (row) {
    const tmp = document.createElement('div'); tmp.innerHTML = _wsBudgetRowHtml(row);
    const head = el.closest('.wsbud-row');
    const fresh = tmp.firstElementChild;
    if (head && fresh) {
      head.querySelector('.wsbud-row-head').replaceWith(fresh.querySelector('.wsbud-row-head'));
      const amt = head.querySelector('[data-wsbud-amt]'); if (amt) amt.setAttribute('aria-label', String(t('wsbud_amt_aria')).replace('{n}', _wsBudgetRowName(row)));
    }
  }
  _wsBudgetRepaint();
  if (mode !== 'blur') {
    const root = _wsBudgetRoot(); const b = root && root.querySelector('[data-wsbud-rename="' + id + '"]');
    if (b) b.focus();
  }
}
var _wsBudWired = false;
function _wsBudgetWire() {
  if (_wsBudWired || typeof document === 'undefined' || !document.addEventListener) return;
  _wsBudWired = true;
  document.addEventListener('input', e => {
    const el = e.target; if (!el || !el.getAttribute || !_wsBudgetRoot()) return;
    if (el.hasAttribute('data-wsbud-amt')) _wsBudgetOnAmount(el);
    else if (el.hasAttribute('data-wsbud-name-in')) _wsBudgetOnNameInput(el);
  });
  document.addEventListener('click', e => {
    const root = _wsBudgetRoot(); if (!root || !e.target || !e.target.closest) return;
    const q = s => e.target.closest(s);
    let b;
    if ((b = q('[data-wsbud-sel]'))) { _wsBudgetSelect(b.getAttribute('data-wsbud-sel')); return; }
    if ((b = q('[data-wsbud-seg]'))) { _wsBudgetSelect(b.getAttribute('data-wsbud-seg')); return; }
    if ((b = q('[data-wsbud-rename]'))) { _wsBudgetRenameStart(b.getAttribute('data-wsbud-rename')); return; }
    if ((b = q('[data-wsbud-del]'))) { _wsBudgetDelete(b.getAttribute('data-wsbud-del')); return; }
    if ((b = q('[data-wsbud-add]'))) { _wsBudgetAdd(b.getAttribute('data-wsbud-add')); return; }
    if ((b = q('[data-wsbud-goto]'))) {
      const f = root.querySelector('[data-wsbud-list="expense"] [data-wsbud-amt]') || root.querySelector('[data-wsbud-add="expense"]');
      if (f) { try { f.scrollIntoView({ block: 'center' }); } catch (_) {} f.focus(); }
      return;
    }
    // Pulsar FUERA del gráfico devuelve el estado general.
    if (_wsBudSel && !q('.wsbud-donut') && !q('.wsbud-legend')) _wsBudgetSelect(null);
  });
  document.addEventListener('keydown', e => {
    const el = e.target;
    if (el && el.hasAttribute && el.hasAttribute('data-wsbud-name-in')) {
      if (e.key === 'Enter') { e.preventDefault(); _wsBudgetRenameEnd(el, 'enter'); }
      else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); _wsBudgetRenameEnd(el, 'cancel'); }
      return;
    }
    if (e.key === 'Escape' && _wsBudSel && _wsBudgetRoot() && !document.getElementById('wsConfirmModal')) _wsBudgetSelect(null);
  });
  document.addEventListener('focusout', e => {
    const el = e.target;
    if (el && el.hasAttribute && el.hasAttribute('data-wsbud-name-in')) _wsBudgetRenameEnd(el, 'blur');
  });
}

