// ── WS.14 — Loan Simulator Pro (Préstamos Pro) ───────────────────────────────
// French amortization (constant payment). Deterministic, pure, no APIs/banks.
function calculateLoan(o) {
  o = o || {};
  // ── EL PARSEO TOLERANTE LLEGA TAMBIÉN AQUÍ (SPEC WORKSPACE · §4) ───────────
  // Esta función recibe el ESTADO DE EDICIÓN, que es TEXTO: los handlers guardan
  // `el.value` crudo desde WS.15A, precisamente para que se pueda borrar un campo.
  // Pero aquí se leía con `Number()`, que no entiende el formato español, y el
  // resultado era un defecto financiero en una herramienta PREMIUM PUBLICADA:
  //   · tipo «3,5» ⇒ `Number('3,5')` es NaN ⇒ 0 ⇒ la rama SIN INTERÉS (`P/n`).
  //     250.000 a 30 años salían 694,44 al mes en vez de 1.122,61 — un 38 % menos,
  //     presentado al usuario como su cuota.
  //   · principal «250.000» ⇒ `Number` lo lee como 250 ⇒ cuota de 1,12.
  // `_wsNum` es el parser que WS.15A creó para esto y que esta función nunca
  // recibió. Los importes y los años SÍ lo tenían en compound; la TASA no lo tenía
  // en ninguno de los tres motores. Es el mismo olvido y se cierra en los tres.
  const P = Math.max(0, _wsNum(o.principal));
  const annual = Math.max(0, _wsNum(o.rate != null ? o.rate : o.interestRate));
  const years = Math.max(0, _wsNum(o.years));
  const fees = Math.max(0, _wsNum(o.fees));
  const ins = Math.max(0, _wsNum(o.insurance != null ? o.insurance : o.insuranceMonthly));
  const n = Math.round(years * 12);
  const r = annual / 12 / 100;
  let base = 0;
  if (n > 0) base = (r > 0) ? (P * r / (1 - Math.pow(1 + r, -n))) : (P / n);
  const totalBase = base * n;
  const totalInterest = Math.max(0, totalBase - P);
  const totalInsurance = ins * n;
  const monthlyPayment = base + ins;
  const totalPaid = P + totalInterest + totalInsurance + fees;
  const denom = P + totalInterest;
  const table = [];
  let bal = P;
  for (let m = 1; m <= n; m++) {
    const interest = bal * r;
    let principalPart = base - interest;
    if (m === n) principalPart = bal;
    bal = Math.max(0, bal - principalPart);
    table.push({ month: m, payment: base, principal: principalPart, interest, balance: bal });
  }
  return { base, monthlyPayment, totalInterest, totalInsurance, totalPaid, fees, principal: P, years, annual, n, principalShare: denom > 0 ? P / denom * 100 : 0, interestShare: denom > 0 ? totalInterest / denom * 100 : 0, table };
}
function _wsLoanDefaults() { return { principal: 180000, rate: 3.25, years: 30, fees: 0, insurance: 0, cmpOpen: false, bPrincipal: 180000, bRate: 3.25, bYears: 20 }; }
function _wsLoanPct(v) { const s = (Math.round(v * 100) / 100).toString(); return s.replace('.', (typeof lang !== 'undefined' && lang === 'en') ? '.' : ','); }

function _wsLoanDonutHtml(res) {
  const esc = _intccEsc;
  const C = 2 * Math.PI * 52;
  const capLen = (res.principalShare / 100) * C;
  return `<svg class="wsloan-donut" viewBox="0 0 140 140" role="img" aria-label="${esc(t('wsloan_donut_aria'))}">
    <circle class="wsloan-donut-track" cx="70" cy="70" r="52"></circle>
    <circle class="wsloan-donut-int" cx="70" cy="70" r="52" transform="rotate(-90 70 70)"></circle>
    <circle class="wsloan-donut-cap" cx="70" cy="70" r="52" transform="rotate(-90 70 70)" stroke-dasharray="${capLen.toFixed(1)} ${(C - capLen).toFixed(1)}"></circle>
    <text class="wsloan-donut-c" x="70" y="66" text-anchor="middle">${Math.round(res.interestShare)}%</text>
    <text class="wsloan-donut-l" x="70" y="84" text-anchor="middle">${esc(t('wsloan_dn_lbl'))}</text>
  </svg>`;
}
function _wsLoanInsights(res) {
  const out = [];
  const costInterestPct = res.totalPaid > 0 ? Math.round(res.totalInterest / (res.principal + res.totalInterest) * 100) : 0;
  if (costInterestPct >= 30) out.push(t('wsloan_ins_interest')(costInterestPct));
  if (res.years > 5) { const less = calculateLoan({ principal: res.principal, rate: res.annual, years: res.years - 5 }); const saved = res.totalInterest - less.totalInterest; if (saved > 0) out.push(t('wsloan_ins_term')(5, _wsMoney(saved))); }
  const up = calculateLoan({ principal: res.principal, rate: res.annual + 1, years: res.years }); const diff = up.base - res.base; if (diff > 0) out.push(t('wsloan_ins_rate')(_wsMoney(diff)));
  return out.slice(0, 3);
}
// ── EL CONTRATO QUE SE ESTÁ SIMULANDO, DECLARADO (§G) ───────────────────────
// «Contrato explícito: cuota constante, tipo fijo, tasa nominal anual, pagos
// mensuales.» Sin esto el usuario no puede saber QUÉ préstamo es el que está
// viendo, y dos préstamos con la misma cuota pueden ser productos distintos.
//
// Y los COSTES EXCLUIDOS se nombran. No se financian por defecto: los gastos
// iniciales se suman al desembolso total pero NO al principal —si se añadieran al
// capital, la cuota subiría y el usuario no lo habría pedido—, y eso es
// exactamente lo que hay que decir en vez de dejarlo a la interpretación.
