    let miIdx = 0, maIdx = 0;
    for (let i = 1; i < n; i++) { if (pts[i].value < pts[miIdx].value) miIdx = i; if (pts[i].value > pts[maIdx].value) maIdx = i; }
    const drop = new Array(n).fill(false);
