const _AURIX_24H_SPIKE_MIN_PROM_PX = 4.5;
const _AURIX_24H_SPIKE_ASPECT = 0.55;
const _AURIX_24H_SPIKE_MAX_PASSES = 3;
const _AURIX_VOLATILITY_POLISH_ENABLED = true;
