  const intent = ctx && ctx.fields && ctx.fields.concentration_intent;
  if (intent && intent.value === 'deliberate'
      && (out.state === 'weight_in_few' || out.state === 'single_position')) {
    out.contextNote = 'concentration_declared_deliberate';
  }
