// Per-tab active-category state. One stateful pointer per asset class.
// MC-11C.2: every tab opens on its mobile-friendly "Top / Popular /
// Major" category so the most-watched assets appear above the fold.
let _fundsActiveCategoryId       = 'popular';
let _stocksActiveCategoryId      = 'top';
let _cryptoActiveCategoryId      = 'top';
let _indicesActiveCategoryId     = 'major';
let _commoditiesActiveCategoryId = 'popular';

// MC-11B: discovery catalog registry — maps market tab id → { catalog
// reference, state getter, state setter, i18n key prefix }. 'etfs' and
// 'funds' point to the same funds state for back-compat with MC-9A.1.
const _DISCOVERY_CATALOGS = {
  etfs:        { catalog: _FUNDS_CATALOG,       labelPrefix: 'fundCat_',                get: () => _fundsActiveCategoryId,       set: id => { _fundsActiveCategoryId       = id; } },
  funds:       { catalog: _FUNDS_CATALOG,       labelPrefix: 'fundCat_',                get: () => _fundsActiveCategoryId,       set: id => { _fundsActiveCategoryId       = id; } },
  stocks:      { catalog: _STOCKS_CATALOG,      labelPrefix: 'discCat_stocks_',         get: () => _stocksActiveCategoryId,      set: id => { _stocksActiveCategoryId      = id; } },
  crypto:      { catalog: _CRYPTO_CATALOG,      labelPrefix: 'discCat_crypto_',         get: () => _cryptoActiveCategoryId,      set: id => { _cryptoActiveCategoryId      = id; } },
  indices:     { catalog: _INDICES_CATALOG,     labelPrefix: 'discCat_indices_',        get: () => _indicesActiveCategoryId,     set: id => { _indicesActiveCategoryId     = id; } },
  commodities: { catalog: _COMMODITIES_CATALOG, labelPrefix: 'discCat_commodities_',    get: () => _commoditiesActiveCategoryId, set: id => { _commoditiesActiveCategoryId = id; } },
};

function _escFunds(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

// MC-10: build the inline metadata badges. Order: kind, UCITS, share,
// currency. Every badge is optional — never invents data we don't have.
// MC-11B: extended kind set to include STOCK / CRYPTO / INDEX / COMM /
// METAL so the same pill row reads consistently across asset classes.
function _fundCardBadges(it) {
  const out = [];
  const kind = (it.type || '').toUpperCase();
  const KIND_LABELS = { ETF:'ETF', FUND:'FUND', STOCK:'STOCK', CRYPTO:'CRYPTO', INDEX:'INDEX', COMMODITY:'COMM', METAL:'METAL' };
  const kindLabel = KIND_LABELS[kind];
  if (kindLabel) {
    out.push(`<span class="funds-card-pill is-kind is-${kind.toLowerCase()}">${_escFunds(kindLabel)}</span>`);
  }
  if (it.ucits) {
    out.push(`<span class="funds-card-pill is-ucits">UCITS</span>`);
  }
  if (it.share === 'Acc' || it.share === 'Dist') {
    out.push(`<span class="funds-card-pill is-share">${_escFunds(it.share)}</span>`);
  }
  if (typeof it.currency === 'string' && /^[A-Z]{3}$/.test(it.currency)) {
    out.push(`<span class="funds-card-pill is-curr">${_escFunds(it.currency)}</span>`);
  }
  return out.join('');
}

// MC-11B: generic discovery renderer used by every asset-class tab.
// Reads the catalog + active state from _DISCOVERY_CATALOGS so each tab
// shares the same DOM/styling and the same click delegation. data-disc-
// attributes carry the tab key so the delegation can route correctly.
function _renderDiscoveryCatalog(tabKey, data) {
  const reg = _DISCOVERY_CATALOGS[tabKey];
  if (!reg || !Array.isArray(reg.catalog) || reg.catalog.length === 0) return '';
  // MARKET-FOUNDATION-V1 · BLOQUE A — sólo se pinta el chip que filtra de verdad.
  // `rows` son las filas YA cargadas de esta pestaña: la misma fuente que la lista.
  const rows = _aurixMktRowsForTab(tabKey, data);
  // Cold start: sin filas todavía no se puede juzgar cobertura (la lista muestra
  // skeleton). Se pintan todos los chips para no provocar un parpadeo en la fila de
  // chips; en cuanto llegan los datos, el siguiente render aplica la cobertura real.
  const canJudge = rows.length > 0;
  // Un subfiltro sólo es real si produce un subconjunto ESTRICTO: ni vacío (no
  // cambiaría nada y antes caía al fallback silencioso) ni completo (devolvería
  // exactamente la misma lista que "todo", que es el defecto descrito por el SPEC
  // con otra cara). Caso real detectado: en Índices, "EE.UU." cubría los 3 únicos
  // índices monitorizados → seleccionarlo dejaba la lista idéntica.
  const visible = canJudge
    ? reg.catalog.filter((c, i) => {
        if (i === 0) return true;                                   // la categoría por defecto siempre está
        // MARKET-INSTITUTIONAL-V1 · §5 — un chip con consulta de discovery SÍ puede
        // recuperar resultados reales aunque la tabla cargada no los tenga: la
        // cobertura ya no se mide sólo contra las 5/3/3 filas monitorizadas. Por eso
        // vuelven "Oro", "Emergentes" o "Bonos", ahora respaldados por el buscador.
        if (_aurixMktChipQuery(tabKey, c.id)) return true;
        const cov = _aurixMktChipCoverage(c, rows, false);
        return cov > 0 && cov < rows.length;
      })
    : reg.catalog.slice();
  // SPEC §3 — si el subfiltro activo deja de ser válido (su chip ya no se muestra),
  // se resetea a la categoría por defecto ANTES de pintar. Esto va OBLIGATORIAMENTE
  // antes de cualquier salida temprana: si saliéramos sin resetear, el estado activo
  // seguiría filtrando la lista mientras su chip ya no existe — exactamente la
  // incoherencia "selección visual ≠ contenido" que este SPEC viene a eliminar.
  let activeId = reg.get();
  if (!visible.some(c => c.id === activeId)) {
    activeId = reg.catalog[0].id;
    try { reg.set(activeId); } catch (_) {}
  }
  // Si sólo sobrevive la categoría por defecto no hay filtro secundario que ofrecer:
  // una fila con un único chip que no filtra nada es, otra vez, un control decorativo.
  if (visible.length <= 1) return '';
  const cat = visible.find(c => c.id === activeId) || visible[0];
  const chips = visible.map(c => {
    const label = t(reg.labelPrefix + c.id) || c.id;
    const active = c.id === cat.id ? ' active' : '';
    return `<button class="funds-cat${active}" type="button" role="tab" aria-selected="${c.id === cat.id ? 'true' : 'false'}" data-disc-cat="${_escFunds(c.id)}" data-disc-tab="${_escFunds(tabKey)}">${_escFunds(label)}</button>`;
  }).join('');
  const cards = cat.items.map(it => `
    <button class="funds-card" data-disc-pick="${_escFunds(it.ticker)}" data-disc-tab="${_escFunds(tabKey)}" type="button">
      <div class="funds-card-head">
        <span class="funds-card-ticker">${_escFunds(it.ticker)}</span>
        ${it.manager ? `<span class="funds-card-mgr">${_escFunds(it.manager)}</span>` : ''}
      </div>
      <div class="funds-card-name">${_escFunds(it.name)}</div>
      <div class="funds-card-badges">${_fundCardBadges(it)}</div>
      <div class="funds-card-foot">
        <span class="funds-card-cta">${_escFunds(t('discovery_add_cta'))}</span>
      </div>
    </button>
  `).join('');
  // MC-11C.3: cap visible cards at 2 on mobile (down from 3) so the
  // live monitoring table reaches the user sooner. CSS hides
  // .funds-card:nth-child(n+3) and reveals the "View more" button only
  // on narrow viewports. Desktop ignores the rule and shows every card.
  // The button is emitted only when the category actually has more than
  // 2 cards, otherwise no affordance.
  const showMoreLabel = t('view_more_discovery') || 'Ver más';
  const showMoreHtml  = cat.items.length > 2
    ? `<button class="funds-show-more" type="button" data-disc-expand="${_escFunds(tabKey)}">${_escFunds(showMoreLabel)}</button>`
    : '';
  return `
    <div class="funds-discover is-collapsed">
      <div class="funds-cats" role="tablist">${chips}</div>
      <div class="funds-grid">${cards}</div>
      ${showMoreHtml}
    </div>
  `;
}

// Back-compat alias — MC-9A.1 still calls this name in one spot.
function _renderFundsCatalog() { return _renderDiscoveryCatalog('etfs'); }

// MC-11B: single delegation handler covers every discovery tab. Both
// the chips and the cards carry data-disc-tab so the handler picks the
// right catalog + state slot without per-tab listeners.
function _initFundsCatalogDelegation() {
  document.addEventListener('click', (e) => {
    if (typeof currentMarketTab !== 'string') return;
    if (!_DISCOVERY_CATALOGS[currentMarketTab]) return;
    // MC-11C.1: mobile "View more" expander. CSS hides cards 4+ when
    // .funds-discover.is-collapsed; clicking the button removes the
    // class on that container so the rest of the cards reveal. The
    // button itself hides via the same CSS rule once expanded. No
    // re-render needed — we mutate the existing DOM directly.
    const expander = e.target.closest && e.target.closest('[data-disc-expand]');
    if (expander) {
      const container = expander.closest('.funds-discover');
      if (container) container.classList.remove('is-collapsed');
      return;
    }
    const chip = e.target.closest && e.target.closest('[data-disc-cat]');
    if (chip) {
      const tabKey = chip.dataset.discTab;
      const reg = _DISCOVERY_CATALOGS[tabKey];
      if (!reg) return;
      const next = chip.dataset.discCat;
      if (next && next !== reg.get()) {
        reg.set(next);
        const el = document.getElementById('marketList');
        if (el) el._lastKey = null;
        // §5 — si el chip tiene consulta, sus filas las recupera el pipeline canónico.
        const cq = _aurixMktChipQuery(tabKey, next);
        if (cq) { _aurixMktDiscover(cq); return; }
        renderCurrentMarketView();
      }
      return;
    }
    const card = e.target.closest && e.target.closest('[data-disc-pick]');
    if (card) {
      const tabKey = card.dataset.discTab;
      const ticker = card.dataset.discPick;
      const reg = _DISCOVERY_CATALOGS[tabKey];
      if (!reg) return;
      const cat = reg.catalog.find(c => c.id === reg.get()) || reg.catalog[0];
      const item = cat.items.find(i => i.ticker === ticker);
      if (!item) return;
      // MARKET-1C: split body click vs CTA. Clicking the "+ Añadir"
      // CTA keeps the existing add-to-portfolio behaviour; clicking
      // elsewhere on the card opens the market preview chart. The
      // preview itself has its own "Añadir a cartera" CTA — same
      // end state via a more premium discovery flow.
      const onCta = !!(e.target.closest && e.target.closest('.funds-card-cta'));
      if (onCta) {
        _openAddAssetWithFund(item);
      } else if (typeof _aurixMktOpenSymbol === 'function' &&
                 typeof _aurixMktFlag === 'function' && _aurixMktFlag()) {
        // The preview helper looks the asset up in MARKET_DATA so the
        // live price / 24h change are accurate; the catalog ticker is
        // the join key.
        if (!_aurixMktOpenSymbol(ticker)) {
          // Fallback: if the preview can't open (no MARKET_DATA hit,
          // engine not ready, etc.), preserve legacy behaviour.
          _openAddAssetWithFund(item);
        }
      } else {
        _openAddAssetWithFund(item);
      }
    }
  });
}
_initFundsCatalogDelegation();

// Open the existing Add Asset modal and call selectAsset() with the
// catalog entry. selectAsset already handles price resolution via the
// same /api/prices/snapshot path the rest of the app uses; no new
// pricing code added here.
// ADD-V2.1: discovery picks already know the asset type, so skip the
// Step-1 type picker and land directly on the form.
// ADD-V2.2: pin asset mode so search/quick-picks chrome stays usable.
// ══════════════════════════════════════════════════════════════════════════
// HOTFIX MARKET-ASSET-FLOW — de Asset Detail al formulario, sin buscador
// ══════════════════════════════════════════════════════════════════════════
// CAUSA RAÍZ del "se abre el buscador general": las filas de MARKET_DATA las
// construye normalizeMarketData, que devuelve { symbol, name, price, change,
// change24h, type, fallback } — SIN `ticker`. selectAsset() empieza por
// `entry.ticker.slice(0, 4)`, así que lanzaba TypeError; el try/catch de
// _openAddAssetWithFund se lo tragaba y el modal se quedaba en su fase inicial
// con buscador y populares. No era un problema de flujo, era una incompatibilidad
// de forma entre la fila de Market y lo que espera el formulario.
//
// Aquí se traduce la fila a la MISMA forma que ya consume selectAsset. No se
// duplica modal, formulario ni persistencia: se reutiliza la segunda fase tal cual.

// Tipos que el alta admite de verdad (T[lang].typeLabel): crypto, stock, etf,
// metal, fund. Índices y materias primas genéricas NO son posiciones que se puedan
// tener en cartera, así que se declaran no añadibles en vez de fingir que lo son.
function _aurixMktAddableType(item) {
  if (!item) return null;
  const t0 = String(item.type || '').toLowerCase().trim();
  const sym = normalizeSymbol(item.ticker || item.symbol || '');
  if (t0 === 'crypto') return 'crypto';
  if (t0 === 'stock' || t0 === 'stocks') return 'stock';
  if (t0 === 'etf' || t0 === 'etfs') return 'etf';
  if (t0 === 'fund' || t0 === 'funds') return 'fund';
  if (t0 === 'metal') return 'metal';
  // Materias primas: sólo los metales preciosos tienen alta real (XAU/XAG).
  if (t0 === 'commodity' || t0 === 'commodities') return (sym === 'XAUUSD' || sym === 'XAU' || sym === 'XAGUSD' || sym === 'XAG') ? 'metal' : null;
  return null;   // index / indices / desconocido → no añadible
}

// Fila de Market → entrada canónica de selectAsset. Sólo copia lo que existe:
// no inventa ticker, gestora ni moneda.
function _aurixMktToSelection(item) {
  const type = _aurixMktAddableType(item);
  if (!type) return null;
  const ticker = String(item.ticker || item.symbol || '').toUpperCase().trim();
  if (!ticker) return null;
  // Mismo criterio de nombre que la fila de Market (renderMarketItem): el nombre del
  // feed si es real, y si no el curado. Así el chip del formulario dice "SPDR S&P 500
  // ETF" y no "SPY", que es el ticker repetido.
  const _dataName = (item.name && item.name !== item.symbol) ? item.name : null;
  let _disp = item.displayName || _dataName;
  if (!_disp) { try { _disp = _MKT_DISPLAY_NAMES[normalizeSymbol(ticker)] || null; } catch (_) { _disp = null; } }
  const sel = {
    ticker,
    name: _disp || ticker,
    type,
    marketSymbol: item.marketSymbol || item.symbol || ticker,
  };
  if (item.coinId) sel.coinId = item.coinId;
  if (item.isin) sel.isin = item.isin;
  if (item.manager || item.issuer) sel.manager = item.manager || item.issuer;
  if (item.assetCurrency || item.currency) sel.assetCurrency = item.assetCurrency || item.currency;
  const p = item.current_price ?? item.price;
  if (Number.isFinite(p)) sel.price = p;
  return sel;
}

function _openAddAssetWithFund(item) {
  if (!item) return;
  try { openModal({ skipPicker: true }); } catch (_) {}
  if (typeof _addV2SetMode === 'function') _addV2SetMode('asset');
  setTimeout(() => {
    try { selectAsset(item); } catch (e) { console.warn('[funds-pick]', e?.message); }
  }, 60);
}

// MARKET-MOBILE-1 / MK.F1: the subcategory chips (Top / Layer 1 / DeFi…) act as
// real list filters. MK.F1 extends this to web/desktop too (was mobile-only) so the
// pills stay meaningful once the big discovery cards are hidden on desktop — the
// premium "terminal" behaviour. Returns a Set of normalized tickers for the ACTIVE
// NON-DEFAULT category of the current tab, or null when no filter should apply
// (default category, or no catalog). The caller falls back to the full list when the
// set yields nothing, so the list can never end up empty. No data is fetched, created
// or mutated — this only narrows which already-loaded rows are shown.
function _aurixMktMobileCategoryFilter() {
  try {
    const reg = _DISCOVERY_CATALOGS[currentMarketTab];
    if (!reg || !Array.isArray(reg.catalog) || !reg.catalog.length) return null;
    const activeId  = reg.get();
    const defaultId = reg.catalog[0].id;          // 'top' / 'popular' / 'major' → full list
    if (!activeId || activeId === defaultId) return null;
    const cat = reg.catalog.find(c => c.id === activeId);
    if (!cat || !Array.isArray(cat.items) || !cat.items.length) return null;
    const set = new Set();
    cat.items.forEach(it => {
      const s = normalizeSymbol(it.ticker || it.marketSymbol || '');
      if (s) set.add(s);
    });
    return set.size ? set : null;
  } catch (_) { return null; }
}

// ── MARKET-FOUNDATION-V1 · BLOQUE A — coherencia chip ↔ lista ────────────────
// CAUSA RAÍZ de "el chip cambia pero la lista no": los chips secundarios se
// pintan desde el catálogo de descubrimiento (_DISCOVERY_CATALOGS), que es una
// lista curada de tickers, mientras que la lista viva sólo monitorizaba universos
// muy pequeños (entonces 5 ETF, 3 índices y 3 materias primas; MARKET-EXCELLENCE-B4
// los llevó a 23 y 10). Cuando un chip no comparte NI UN símbolo con esas filas, el filtro
// resultante quedaba vacío y renderFromCache hacía `if (sub.length) items = sub`
// — es decir, se caía EN SILENCIO a la lista completa. El chip se marcaba activo
// y la lista no cambiaba. Ese es exactamente el caso "Oro" reportado: sus tickers
// (SGLN.L / PHAU.L / GLD / IAU / 4GLD.DE) no intersecan con SPY/QQQ/VOO/VTI/URTH.
//
// La corrección NO inventa activos ni clasificaciones (prohibido por el SPEC): mide
// la cobertura real contra las filas ya cargadas y sólo deja visible el chip que de
// verdad filtra. Es auto-mantenido: si mañana crece el universo monitorizado, el
// chip reaparece solo, sin tocar código.
//
// ══════════════════════════════════════════════════════════════════════════
// MARKET-INSTITUTIONAL-V1 · §2 — DISCOVERY UNIFICADO
// ══════════════════════════════════════════════════════════════════════════
// Market dejaba de encontrar lo que Add Asset sí encuentra porque su buscador
// filtraba localmente MARKET_DATA (universos de 5/3/3 símbolos). Add Asset, en
// cambio, ya tiene el pipeline canónico completo:
//     searchYahooFinance + searchCoinGeckoAPI + searchMetalsLocal
//   → _aurixSearchFundsLocal (catálogo curado)
//   → dedupe ISIN-first (SPEC 70)
//   → _aurixRankSearchResults
// Aquí NO se crea un segundo buscador ni un ranking paralelo: se llama a
// searchAllAssets() —el mismo owner que usa Add Asset— y se traduce su salida a
// filas de Market con _searchResultToMarketItem(), que ya existía para esto.
// Consecuencia medida contra la API real: "MSCI World" pasa de 1 fila (URTH) a
// los 7 productos que el proveedor devuelve de verdad (iShares ×3, Amundi, HSBC,
// Xtrackers). No se fabrica ninguno: si el buscador no lo devuelve, no aparece.
let _mktDiscQuery   = '';        // consulta a la que pertenecen los resultados
let _mktDiscResults = [];        // filas de Market ya normalizadas
let _mktDiscState   = 'idle';    // idle | loading | ready | error
let _mktDiscAbort   = null;      // AbortController de la petición en vuelo
let _mktDiscTimer    = null;     // debounce
const _mktDiscCache = new Map(); // consulta → filas (evita repetir peticiones)
const _MKT_DISC_DEBOUNCE = 260;
const _MKT_DISC_CACHE_MAX = 40;

// Precio/variación para las filas que el buscador devuelve sin cotizar. Reutiliza
// el MISMO endpoint de snapshot que ya usa toda la app (PRICES_PROXY): ni proveedor
// nuevo ni contrato nuevo. Falla en silencio → la fila se pinta sin precio ("—"),
// que es el estado honesto previsto en §10.
async function _aurixMktHydrateQuotes(items, signal) {
  if (!Array.isArray(items) || !items.length) return items;
  if (typeof PRICES_PROXY === 'undefined' || typeof fetch !== 'function') return items;
  const _blockedBySymbolAmbiguity = new Set();
  let need = items.filter(it => it && !(Number.isFinite(it.current_price) && it.current_price > 0));
  // SPEC ASSET-DISCOVERY-IDENTITY.V1 · §7 — este hidratador cotiza por SÍMBOLO. Ahora que dos tokens
  // distintos pueden compartir ticker en la MISMA lista, pedir el precio del símbolo para los dos
  // pintaría el precio del grande sobre el pequeño: un precio inventado para ese activo. Se cotiza
  // sólo al dueño demostrable del símbolo (único con ese ticker, o el de mejor market rank real del
  // proveedor); el resto se queda en "—", que es el estado honesto. Un resultado por CONTRATO nunca
  // se cotiza por símbolo: ya trae el precio de su propia identidad, o no lo trae.
  if (typeof _AURIX_DISCOVERY_IDENTITY_V1 !== 'undefined' && _AURIX_DISCOVERY_IDENTITY_V1) {
    const groups = new Map();
    items.forEach(it => {
      if (!it || String(it.type || '').toLowerCase() !== 'crypto') return;
      const tk = String(it.symbol || it.ticker || '').toUpperCase();
      if (!tk) return;
      if (!groups.has(tk)) groups.set(tk, []);
      groups.get(tk).push(it);
    });
    groups.forEach(group => {
      if (group.length < 2) return;
      const ranked = group.filter(g => Number.isFinite(g.marketCapRank));
      let owner = null;
      if (ranked.length) {
        const best = Math.min.apply(null, ranked.map(g => g.marketCapRank));
        const tied = ranked.filter(g => g.marketCapRank === best);
        if (tied.length === 1) owner = tied[0];
      }
      group.forEach(g => { if (g !== owner) _blockedBySymbolAmbiguity.add(g); });
    });
    items.forEach(it => { if (it && (it.matchedBy === 'contract' || it.priceable === false)) _blockedBySymbolAmbiguity.add(it); });
    need = need.filter(it => !_blockedBySymbolAmbiguity.has(it));
  }
  if (!need.length) return items;
  const syms = Array.from(new Set(need.map(it => it.marketSymbol || it.symbol).filter(Boolean))).slice(0, 40);
  if (!syms.length) return items;
  try {
    const url = `${PRICES_PROXY}/snapshot?symbols=${encodeURIComponent(syms.join(','))}`;
    const res = await fetch(url, { signal });
    if (!res.ok) return items;
    const json = await res.json();
    const by = new Map();
    for (const s of (json && Array.isArray(json.snapshot) ? json.snapshot : [])) {
      if (s && s.symbol) by.set(normalizeSymbol(s.symbol), s);
    }
    items.forEach(it => {
      if (_blockedBySymbolAmbiguity.has(it)) return;   // §7: nunca el precio de OTRO activo con el mismo símbolo
      const hit = by.get(normalizeSymbol(it.marketSymbol || it.symbol));
      if (!hit) return;
      const p = Number(hit.price);
      if (Number.isFinite(p) && p > 0) { it.current_price = p; it.price = p; }
      if (Number.isFinite(hit.change24h)) { it.change24h = hit.change24h; it.price_change_percentage_24h = hit.change24h; }
      if (hit.currency) it.currency = hit.currency;
    });
  } catch (_) { /* sin precio: la fila se pinta con "—" */ }
  return items;
}

// Ejecuta el pipeline canónico para una consulta y deja el resultado listo para
// pintar. Una sola petición en vuelo: la anterior se aborta (reutiliza el patrón
// de cancelación que ya emplea Add Asset).
async function _aurixMktDiscover(query, opts) {
  const q = String(query || '').trim();
  const tag = q.toLowerCase();
  if (!q) { _mktDiscQuery = ''; _mktDiscResults = []; _mktDiscState = 'idle'; return []; }
  if (_mktDiscCache.has(tag)) {
    _mktDiscQuery = tag; _mktDiscResults = _mktDiscCache.get(tag); _mktDiscState = 'ready';
    if (!(opts && opts.silent)) renderCurrentMarketView();
    return _mktDiscResults;
  }
  try { if (_mktDiscAbort) _mktDiscAbort.abort(); } catch (_) {}
  const ctrl = (typeof AbortController === 'function') ? new AbortController() : null;
  _mktDiscAbort = ctrl;
  _mktDiscQuery = tag; _mktDiscState = 'loading';
  if (!(opts && opts.silent)) renderCurrentMarketView();
  let rows = [];
  try {
    const found = await searchAllAssets(q, ctrl ? ctrl.signal : undefined);
    if (ctrl && ctrl.signal.aborted) return _mktDiscResults;
    rows = (Array.isArray(found) ? found : [])
      .map(r => {
        const row = _searchResultToMarketItem(r);
        if (!row) return null;
        // Identidad extendida SÓLO con lo que el resultado ya trae (§3/§9): nada
        // se deduce ni se rellena. Si no hay gestora, no se muestra gestora.
        row.issuer   = r.manager || r.issuer || null;
        row.exchange = r.exchange || null;
        row.isin     = r.isin || null;
        row.displayName = (typeof getDisplayName === 'function') ? getDisplayName(r) : (r.name || row.symbol);
        return row;
      })
      .filter(Boolean);
    await _aurixMktHydrateQuotes(rows, ctrl ? ctrl.signal : undefined);
    if (ctrl && ctrl.signal.aborted) return _mktDiscResults;
    _mktDiscResults = rows; _mktDiscState = 'ready';
    _mktDiscCache.set(tag, rows);
    if (_mktDiscCache.size > _MKT_DISC_CACHE_MAX) {
      try { _mktDiscCache.delete(_mktDiscCache.keys().next().value); } catch (_) {}
    }
  } catch (e) {
    if (!(e && e.name === 'AbortError')) { _mktDiscResults = []; _mktDiscState = 'error'; }
  }
  // El repintado final NO es opcional: `silent` sólo evita el repintado de "cargando"
  // cuando la llamada nace desde dentro del propio render (evita recursión). Si se
  // omitiera también el final, la lista se quedaría en skeleton para siempre.
  if (_mktDiscQuery === tag) renderCurrentMarketView();
  return _mktDiscResults;
}

// ── SPEC ASSET-DISCOVERY-IDENTITY.V1 · §6 — abrir una fila de discovery POR IDENTIDAD ─────────
// Una fila que viene del buscador (no de la tabla monitorizada) se abría por SÍMBOLO: el handler
// llamaba a _aurixMktOpenSymbol(row.dataset.symbol) sin item, y `_findMktItem` la buscaba en
// MARKET_DATA. Dos defectos: (1) si el activo no está en la tabla no ocurría NADA — un resultado
// visible que no se puede abrir; (2) si su símbolo coincidía con uno de la tabla se abría el activo
// EQUIVOCADO. Ahora la fila lleva su identidad canónica y se resuelve por ella; si el activo existe
// en discovery pero no en la tabla, se continúa hacia Add Asset con el activo YA identificado
// (id de proveedor, red y contrato incluidos). Las filas de la tabla mantienen su ruta intacta.
function _aurixMktDiscRowItem(row) {
  if (!row || !row.dataset || !row.dataset.canon) return null;
  if (typeof _AURIX_DISCOVERY_IDENTITY_V1 === 'undefined' || !_AURIX_DISCOVERY_IDENTITY_V1) return null;
  const canon = row.dataset.canon;
  try { return (_mktDiscResults || []).find(r => r && r.canonicalKey === canon) || null; } catch (_) { return null; }
}
function _aurixMktActivateRow(row) {
  if (!row || !row.dataset) return;
  const disc = _aurixMktDiscRowItem(row);
  let opened = false;
  try {
    if (typeof _aurixMktOpenSymbol === 'function') opened = _aurixMktOpenSymbol(row.dataset.symbol, disc || undefined);
  } catch (_) {}
  if (opened || !disc) return;
  // Sólo cuando la ficha está activa pero no ha podido abrirse: nunca se cambia el comportamiento
  // con el flag de Market apagado.
  try {
    if (typeof _aurixMktFlag === 'function' && _aurixMktFlag() && typeof _openAddAssetWithFund === 'function') _openAddAssetWithFund(disc);
  } catch (_) {}
}

// ── MARKET-INSTITUTIONAL-V1 · §5 — filtros respaldados por discovery ─────────
// En MARKET-FOUNDATION-V1 la cobertura de un chip se medía SÓLO contra la tabla
// cargada (5/3/3 símbolos), por eso "Oro" o "MSCI World" quedaban ocultos: no
// tenían nada que filtrar. Ahora un chip puede recuperar sus propios productos por
// el pipeline canónico, así que la pregunta correcta no es "¿hay filas cargadas?"
// sino "¿puede este filtro recuperar resultados reales?".
//
// Cada consulta es un ALIAS de búsqueda, no una lista de activos: el resultado lo
// decide el buscador. Si un día el proveedor deja de devolver productos para un
// alias, el chip se queda vacío y se oculta solo — nunca inventa contenido.
const _MKT_CHIP_QUERIES = {
  etfs: {
    sp_500: 'S&P 500', nasdaq_100: 'Nasdaq 100', msci_world: 'MSCI World',
    all_world: 'All World', emerging_markets: 'Emerging Markets',
    dividend: 'Dividend ETF', bonds: 'Bond ETF', europe: 'Europe ETF', gold: 'Gold ETF',
  },
  commodities: { precious_metals: 'Gold', energy_commodities: 'Crude Oil', industrial_metals: 'Copper' },
  indices:     { us: 'S&P 500 index', europe: 'Euro Stoxx', asia: 'Nikkei', global: 'MSCI World index' },
};
function _aurixMktChipQuery(tabKey, chipId) {
  const tab = _MKT_CHIP_QUERIES[tabKey === 'funds' ? 'etfs' : tabKey];
  return (tab && tab[chipId]) ? tab[chipId] : null;
}
// Consulta del subfiltro activo (null = ninguno / categoría por defecto). Es estado
// derivado del chip activo, NO un segundo owner: siempre se recalcula desde reg.get().
function _aurixMktActiveChipQuery() {
  try {
    const reg = _DISCOVERY_CATALOGS[currentMarketTab];
    if (!reg || !Array.isArray(reg.catalog) || !reg.catalog.length) return null;
    const activeId = reg.get();
    if (!activeId || activeId === reg.catalog[0].id) return null;   // por defecto → sin filtro
    return _aurixMktChipQuery(currentMarketTab, activeId);
  } catch (_) { return null; }
}

// Devuelve el Set de símbolos normalizados de una categoría del catálogo.
function _aurixMktCatalogSymbols(cat) {
  const set = new Set();
  if (!cat || !Array.isArray(cat.items)) return set;
  cat.items.forEach(it => {
    const s = normalizeSymbol(it.ticker || it.marketSymbol || '');
    if (s) set.add(s);
  });
  return set;
}

// ¿Cuántas filas REALES (de las ya cargadas para esta pestaña) produciría el chip?
// La categoría por defecto no filtra: su "cobertura" son todas las filas.
function _aurixMktChipCoverage(cat, rows, isDefault) {
  if (isDefault) return Array.isArray(rows) ? rows.length : 0;
  const set = _aurixMktCatalogSymbols(cat);
  if (!set.size || !Array.isArray(rows)) return 0;
  return rows.filter(r => set.has(normalizeSymbol(r && r.symbol))).length;
}

// Filas ya cargadas que alimentan la lista de una pestaña concreta. Es la MISMA
// fuente que usa renderFromCache, para que el chip y la lista no puedan discrepar.
function _aurixMktRowsForTab(tabKey, data) {
  const type = _TAB_TO_TYPE[tabKey] || (tabKey === 'funds' ? 'etfs' : null);
  if (!type || !Array.isArray(data)) return [];
  const lc = String(type).toLowerCase().trim();
  return data.filter(d => String(d && d.type).toLowerCase().trim() === lc);
}

// MARKET-INSTITUTIONAL-V1 · §10 — owner ÚNICO del skeleton. Antes vivía inline en
// renderFromCache; ahora lo comparten la carga inicial y la búsqueda, de modo que
// ambos estados tienen exactamente la geometría de la fila real (6 celdas) y no
// aparece un salto de layout al sustituir el skeleton por los datos.
// ── MARKET-INSTITUTIONAL-V1 · ruido tokenizado fuera de las exposiciones clásicas ──
// Al abrir Market al pipeline canónico entraron también los envoltorios cripto que
// CoinGecko publica sobre índices tradicionales: "SPDR S&P 500 ETF (Ondo Tokenized
// ETF)", "Backed CSPX", "DeFi S&P 500", "iShares TIPS Bond ETF (Ondo…)". Son activos
// REALES —no se inventan ni se borran del sistema— pero no son el instrumento que
// busca quien filtra por "S&P 500" o "Bonos" en una pestaña de fondos.
//
// Alcance deliberadamente ESTRECHO (no es Search V2.2): sólo se aplica a las pestañas
// de exposición tradicional (fondos/ETF, índices, materias primas). La pestaña Cripto
// y el buscador global no se tocan: allí un token envuelto es exactamente lo buscado.
const _MKT_TRADITIONAL_TABS = { etfs: true, funds: true, indices: true, commodities: true };
const _MKT_RX_TOKENIZED = /\b(tokeni[sz]ed|wrapped|synthetic|staked|on-?chain)\b|\bdefi\b|\bondo\b|\bbacked\b|\bx?stock\b/i;
function _aurixMktIsTraditionalAsset(row) {
  if (!row) return false;
  const type = String(row.type || '').toLowerCase();
  // Un activo de tipo cripto nunca es la exposición tradicional que pide el filtro.
  if (type === 'crypto') return false;
  const name = String(row.name || row.displayName || '');
  return !_MKT_RX_TOKENIZED.test(name);
}
// Aplica el filtro SÓLO si la pestaña activa es de exposición tradicional. Si el
// resultado quedara vacío se devuelve la lista sin filtrar: nunca se prefiere una
// lista vacía a mostrar lo que el proveedor sí encontró.
function _aurixMktFilterTraditional(rows) {
  if (!Array.isArray(rows) || !rows.length) return rows;
  if (!_MKT_TRADITIONAL_TABS[currentMarketTab]) return rows;
  const kept = rows.filter(_aurixMktIsTraditionalAsset);
  return kept.length ? kept : rows;
}

// MARKET-INSTITUTIONAL-V1 · §5 — la lista de una pestaña con subfiltro activo sale
// del discovery cuando ese chip tiene consulta; si no, de la tabla ya cargada. Un solo
// punto de decisión, para que chip y filas no puedan discrepar.
function _aurixMktChipListHtml(type, data) {
  const cq = _aurixMktActiveChipQuery();
  if (!cq) return renderFromCache(type, data);
  const tag = String(cq).toLowerCase();
  // Si ya hay una recuperación en vuelo para ESTA consulta, no se relanza: hacerlo
  // abortaba la anterior (el controlador es único) y la vista se quedaba en skeleton.
  if (_mktDiscQuery !== tag) { _aurixMktDiscover(cq, { silent: true }); return _aurixMktSkeletonHtml(6); }
  if (_mktDiscState === 'loading') return _aurixMktSkeletonHtml(6);
  if (_mktDiscState === 'error') return `<div class="market-empty">${t('market_no_results')}</div>`;
  const rows = _aurixMktExpSortItems(_aurixMktFilterTraditional(_mktDiscResults));
  if (!rows.length) return `<div class="market-empty">${t('market_no_results')}</div>`;
  return _aurixMktTableHeaderHtml() + rows.map(renderMarketItem).join('');
}

function _aurixMktSkeletonHtml(n) {
  const rows = Array.from({ length: Math.max(1, n | 0) }).map(() => `
      <div class="market-row skeleton" aria-hidden="true">
        <div class="col col-asset"><div class="skeleton-circle"></div><div class="skeleton-text"></div></div>
        <div class="col col-price"><div class="skeleton-price"></div></div>
        <div class="col col-change"><div class="skeleton-change"></div></div>
        <div class="col col-chart"><div class="skeleton-spark"></div></div>
        <div class="col col-action"></div>
      </div>`).join('');
  return `<div class="market-skeleton">${rows}</div>`;
}

function renderFromCache(type, data) {
  const normalizedType = String(type).toLowerCase().trim();
  let items = data.filter(d => String(d.type).toLowerCase().trim() === normalizedType);
  // MARKET-MOBILE-1 + MARKET-FOUNDATION-V1 · BLOQUE A: se aplica el subfiltro activo.
  // Ya NO existe el fallback silencioso a la lista completa (`if (sub.length)`): era
  // la causa directa de "el chip se marca activo y la lista no cambia". Ahora sólo se
  // pintan chips con cobertura real (_renderDiscoveryCatalog), así que un chip visible
  // siempre produce filas; y si por carrera de datos no las produjera, se respeta el
  // resultado vacío y cae en el skeleton de abajo — nunca se muestra otra categoría.
  const _catSet = _aurixMktMobileCategoryFilter();
  if (_catSet) items = items.filter(it => _catSet.has(normalizeSymbol(it.symbol)));
  if (!items.length) return _aurixMktSkeletonHtml(8);
  // MARKET-2: honour the explorer sort. No-op when flag is off.
  items = _aurixMktExpSortItems(items);
  const label = _TYPE_LABEL[normalizedType]?.() ?? normalizedType;
  // MARKET-2: header's performance-column label tracks the active
  // timeframe (24H / 7D / 1M / 1Y / ALL). The actual cells render
  // honest "—" when timeframe data is unavailable.
  const tableHeader = _aurixMktTableHeaderHtml();
  return `<div class="market-section-header">${label}</div>${tableHeader}${items.map(renderMarketItem).join('')}`;
}

function ensureMarketData() {
  if (currentMarketTab === 'watchlist' || currentMarketTab === 'all') {
    renderCurrentMarketView();
    return;
  }
  if (MARKET_CACHE[currentMarketTab]) {
    MARKET_DATA = MARKET_CACHE[currentMarketTab];
    renderCurrentMarketView();
    return;
  }
  hydrateMarket(currentMarketTab);
}

// Instant render from cache/MARKET_DATA/fallback, then background refresh
function hydrateMarket(tab) {
  if (!document.getElementById('marketList')) return;
  if (tab === 'watchlist') { renderCurrentMarketView(); return; }
  if (tab === 'all')       { renderCurrentMarketView(); return; }
  const type = _TAB_TO_TYPE[tab];
  if (!type) return;

  // Use cached or already-loaded data for instant render
  const cached   = MARKET_CACHE[tab]; // simple array or undefined
  const inMemory = MARKET_DATA.filter(d => d.type?.toLowerCase() === type.toLowerCase());

  if (cached?.length) {
    MARKET_DATA = cached;
  } else if (inMemory.length) {
    // already in MARKET_DATA — nothing to set
  } else {
    // first ever load — use local fallback so UI is never blank
    const fb = _buildFallbackItems(tab);
    if (fb.length) _applyTypeItems(tab, fb);
  }

  renderCurrentMarketView();
  refreshMarketInBackground(tab);
}

// Apply normalized item array to MARKET_DATA for a given tab type
function _applyTypeItems(tab, items) {
  const type = _TAB_TO_TYPE[tab];
  if (!type) return;
  if (tab === 'crypto') {
    // crypto items arrive in CoinGecko raw format — use _setCryptoData
    _setCryptoData(items);
    return;
  }
  commitMarketData(type, items);
}

// Build local fallback items for any tab (synchronous, no network)
function _buildFallbackItems(tab) {
  if (tab === 'crypto')      return CRYPTO_FALLBACK; // CoinGecko raw format — _setCryptoData handles it
  if (tab === 'stocks') {
    // MARKET-ROW-PRICE-TRUTH — la fila de arranque nace con IDENTIDAD y sin precio. Antes
    // tomaba el número del mapa estático (`getFallbackData`) y lo pintaba igual que una
    // cotización viva; el precio real llega enseguida por el snapshot y lo sustituye.
    const assetStocks = ASSET_DB.filter(a => a.type === 'stock');
    return assetStocks.map(a => {
      const sym = normalizeSymbol(a.marketSymbol || a.ticker);
      return normalizeMarketData(
        { name: a.name, price: null, percent_change_24h: null, fallback: true, priceProvenance: 'none' },
        'stock', sym
      );
    });
  }
  if (tab === 'etfs')        return MARKET_ETFS.map(s => _buildItem(s, null, FALLBACK_PRICES, 'etfs'));
  if (tab === 'indices')     return MARKET_INDICES.map(s => _buildItem(s, null, INDEX_FALLBACKS, 'indices'));
  if (tab === 'commodities') return MARKET_COMMODITIES.map(s => _buildItem(s, null, COMMODITY_FALLBACKS, 'commodities'));
  return [];
}

const MARKET_CACHE_TTL = 60 * 1000; // 1 minute

// Background refresh per type — respects TTL, prevents concurrent calls
async function refreshMarketInBackground(tab) {
  if (_LOADING[tab]) return;
  const failAge = Date.now() - (MARKET_FAILURE_TS[tab] || 0);
  if (failAge < MARKET_FAILURE_BACKOFF) {
    if (typeof AURIX_TELEMETRY !== 'undefined') AURIX_TELEMETRY.market.backoffActivations++;
    return;
  }
  const age = Date.now() - (MARKET_CACHE_TS[tab] || 0);
  if (MARKET_CACHE[tab]?.length && age < MARKET_CACHE_TTL) return;
  if (typeof AURIX_TELEMETRY !== 'undefined') AURIX_TELEMETRY.market.refreshAttempts++;

  _LOADING[tab] = true;
  try {
    switch (tab) {
      case 'crypto':      await _refreshCrypto();      break;
      case 'stocks':      await _refreshStocks();      break;
      case 'etfs':        await _refreshGeneric(tab, MARKET_ETFS,        FALLBACK_PRICES,      'ETFs');       break;
      case 'indices':     await _refreshGeneric(tab, MARKET_INDICES,     INDEX_FALLBACKS,      'Índices');    break;
      case 'commodities': await _refreshGeneric(tab, MARKET_COMMODITIES, COMMODITY_FALLBACKS,  'Materias');   break;
    }
    MARKET_CACHE_TS[tab] = Date.now();
  } finally {
    _LOADING[tab] = false;
  }
}

