    + '.intprev-fact-dot{width:6px;height:6px;border-radius:50%;background:rgba(120,170,255,0.95);box-shadow:0 0 8px rgba(90,140,255,0.7);flex:0 0 auto;margin-top:7px;}'
    + '.intprev-fact-body{min-width:0;}'
