    const _wowKey = (discoveryHtml.match(/data-wow="([^"]+)"/) || [, ''])[1];
    if (_wowKey) shown.push(_wowKey);
    // Las preguntas de Explora mostradas se anotan con prefijo `x:`, que es lo que
