// Mismo contrato de coincidencia que _aurixSearchFundsLocal (nombre / gestora /
// ticker / ISIN / aliases), para que Market y Add Asset se comporten igual.
function _aurixSearchEtfsLocal(query) {
  const q = String(query || '').toLowerCase().trim();
  if (q.length < 2) return [];
  const isIsinQ = (typeof _aurixIsIsin === 'function') ? _aurixIsIsin(q) : false;
  const out = [];
  for (const e of _AURIX_ETF_DB) {
    const name = e.name.toLowerCase(), mgr = (e.manager || '').toLowerCase();
    const hit = (isIsinQ && e.isin && e.isin.toLowerCase() === q)
      || name.indexOf(q) >= 0
      || mgr.indexOf(q) >= 0
      || e.ticker.toLowerCase().indexOf(q) >= 0
      || (Array.isArray(e.aliases) && e.aliases.some(a => a.indexOf(q) >= 0 || q.indexOf(a) >= 0));
    if (!hit) continue;
    out.push({ ticker: e.ticker, name: e.name, type: 'etf', marketSymbol: e.marketSymbol,
               isin: e.isin || null, manager: e.manager || null, exchange: e.exchange || null,
               assetCurrency: e.currency || null, currency: e.currency || null });
  }
  return out;
}

function _aurixSearchFundsLocal(query) {
  if (!(typeof _AURIX_FUND_DISCOVERY !== 'undefined' && _AURIX_FUND_DISCOVERY)) return [];
  const q = String(query || '').toLowerCase().trim();
  if (q.length < 2) return [];
  const isIsinQ = _aurixIsIsin(q);
  const out = [];
  for (const f of _AURIX_FUND_DB) {
    const name = f.name.toLowerCase(), mgr = (f.manager || '').toLowerCase();
    const hit = (isIsinQ && f.isin && f.isin.toLowerCase() === q)
      || name.indexOf(q) >= 0
      || mgr.indexOf(q) >= 0
      || f.ticker.toLowerCase().indexOf(q) >= 0
      || (Array.isArray(f.aliases) && f.aliases.some(a => a.indexOf(q) >= 0 || q.indexOf(a) >= 0));
    if (hit) out.push({ ticker: f.ticker, name: f.name, type: 'fund', marketSymbol: null, isin: f.isin || null, manager: f.manager || null, assetCurrency: f.currency || null, shareClass: f.shareClass || null });
  }
  return out;
}
// ════════════════════════════════════════════════════════════════════════════
// SEARCH-V2.1 — THE single ranking authority for every Aurix search surface.
// ════════════════════════════════════════════════════════════════════════════
// Replaces the previous 4-tier rank (exact → startsWith → includes → rest), which ordered
// only by how the string matched and therefore let an index outrank the ETF that tracks it
// ("S&P 500" → ^GSPC first) and let a look-alike token outrank BTC. Scoring is now a match
// tier PLUS additive signals, so ordering reflects what a user actually means.
//
// Signals, and the honest state of their data:
//   1 exact match (ticker / ISIN / name)      — full data
//   2 name match (prefix > word start > any)  — full data
//   3 alias match                             — reuses the EXISTING curated `aliases` on
//        _AURIX_FUND_DB (SPEC 48). No new alias system — that is Search V2.2.
//   4 popularity  ┐ collapsed into ONE normalised term, because the only real popularity
//   5 market cap  ├ data our providers expose on a SEARCH endpoint is CoinGecko's
//   6 volume      ┘ `market_cap_rank` (crypto) and Yahoo's own `score` (equities/ETFs).
//        Yahoo does NOT return cap or volume on /v1/finance/search, so for stocks/ETFs
//        those two are genuinely unavailable and are left neutral rather than invented.
//   7 provider quality — curated catalog entry > live provider hit > local fallback.
//   8 asset type — an index is demoted: "S&P 500" should offer the investable ETFs first,
//        not ^GSPC, which the user cannot buy.
