// Marca los choques de símbolo DEL CONJUNTO VISIBLE para que el subtítulo desambigüe sólo cuando
// hace falta (progressive disclosure): si el nombre ya distingue, no se muestra red ni contrato.
function _aurixMarkCryptoAmbiguity(items) {
  if (!Array.isArray(items)) return items;
  const counts = new Map();
  for (const it of items) {
    if (!it || String(it.type || '').toLowerCase() !== 'crypto') continue;
    const tk = String(it.ticker || it.symbol || '').toUpperCase();
    if (tk) counts.set(tk, (counts.get(tk) || 0) + 1);
  }
  for (const it of items) {
    if (!it || String(it.type || '').toLowerCase() !== 'crypto') continue;
    const tk = String(it.ticker || it.symbol || '').toUpperCase();
    if ((counts.get(tk) || 0) > 1) it.symbolCollision = true;
  }
  return items;
}
try { if (typeof window !== 'undefined') {
  window._aurixCanonicalAssetKey = _aurixCanonicalAssetKey;
  window._aurixLooksLikeContract = _aurixLooksLikeContract;
  window.aurixContractLookupState = _aurixContractLookupState;
} } catch (_) {}

// ── SPEC SEARCH-V2.2 — UN SOLO MOTOR PARA MARKET Y ADD ASSET ────────────────────────────────
// Market y la búsqueda global ya entraban por aquí; Add Asset sólo lo hacía con el filtro 'all'.
// Con cualquier otro filtro tomaba las ramas por-tipo de `searchByFilter`, que iban directas al
// proveedor y por tanto SIN catálogo curado, SIN dedupe por ISIN/ticker y SIN ranking — de ahí que
// el mismo activo pudiera salir con otro orden, con otro nombre o duplicado según desde dónde se
// buscara. El filtro pasa a ser una PROYECCIÓN por tipo DENTRO del pipeline, aplicada antes del
// corte, no un motor distinto. Sin `filter` el comportamiento es idéntico al anterior.
function _aurixSearchProject(items, filter) {
  const f = String(filter || '').toLowerCase();
  if (!f || f === 'all') return items;
  return items.filter(a => a && String(a.type || '').toLowerCase() === f);
}
async function searchAllAssets(query, signal, filter) {
  // SPEC ASSET-DISCOVERY-IDENTITY.V1 — CONTRACT SEARCH. Si el input tiene forma de dirección de una
  // familia soportada, la búsqueda CAMBIA de modo: se resuelve contrato → red/token → identidad
  // canónica → metadata/logo → precio si existe. El match exacto de contrato tiene prioridad
  // ABSOLUTA, así que no compite en el ranker: es el único resultado de esa consulta.
  // Tampoco se lanzan las peticiones de texto (Yahoo/CoinGecko search): una dirección no es texto y
  // gastarlas sería presupuesto de red tirado. Si el contrato NO se resuelve, se devuelve vacío con
  // el estado del lookup registrado — la UI avisa, NUNCA degrada en silencio a búsqueda textual.
  if (typeof _AURIX_DISCOVERY_IDENTITY_V1 !== 'undefined' && _AURIX_DISCOVERY_IDENTITY_V1
      && typeof _aurixLooksLikeContract === 'function' && _aurixLooksLikeContract(query)) {
    const payload = await _aurixSearchByContract(query, signal);
    if (signal?.aborted) return null;
    const item = (payload && payload.found) ? _aurixContractResultToItem(payload.result) : null;
    return _aurixSearchProject(item ? [item] : [], filter).slice(0, 10);
  }

  const metals = searchMetalsLocal(query);

  const [yahooRes, cryptoRes] = await Promise.allSettled([
    searchYahooFinance(query, signal),
    searchCoinGeckoAPI(query, signal),
  ]);

  if (signal?.aborted) return null;

  const q = query.toLowerCase();
  const yahooItems = (yahooRes.status === 'fulfilled' && yahooRes.value)
    ? yahooRes.value
    : ASSET_DB.filter(a =>
        (a.type === 'stock' || a.type === 'etf') &&
        (a.ticker.toLowerCase().startsWith(q) || a.name.toLowerCase().includes(q))
      ).slice(0, 5);

  const cryptoItems = (cryptoRes.status === 'fulfilled' && cryptoRes.value)
    ? cryptoRes.value
    : [];

  // SPEC 48 — flag OFF ⇒ EXACT prior behaviour (metals → yahoo → crypto, dedupe by ticker, cap 10).
  if (!(typeof _AURIX_FUND_DISCOVERY !== 'undefined' && _AURIX_FUND_DISCOVERY)) {
    const seen = new Set();
    const merged = [];
    for (const item of [...metals, ...yahooItems, ...cryptoItems]) {
      const key = item.ticker.toUpperCase();
      if (!seen.has(key)) { seen.add(key); merged.push(item); }
    }
    return _aurixSearchProject(merged, filter).slice(0, 10);   // SEARCH-V2.2: proyección antes del corte
  }
  // SPEC 48 — flag ON: (1) label Yahoo MUTUALFUND items with parsed manager/currency;
  // (2) inject curated fund matches; (3) dedupe (funds by isin/ticker, others by ticker);
  // (4) relevance rank (exact first). Stocks/ETFs/indices/crypto items are untouched.
  const yEnriched = yahooItems.map(it => {
    if (it && it.type === 'fund') { const meta = _aurixParseFundMeta(it.name); return Object.assign({}, it, { manager: it.manager || meta.manager, assetCurrency: it.assetCurrency || meta.currency }); }
    return it;
  });
  const funds = _aurixSearchFundsLocal(query);
  // MARKET-INSTITUTIONAL-V1 · §3 — el catálogo curado de ETF entra por el MISMO
  // punto que el de fondos, así que Add Asset y Market comparten candidatos,
  // dedupe e identidad sin que exista un segundo pipeline. Va delante en el merge
  // para que, ante ISIN repetido, gane la entrada curada (identidad completa:
  // gestora, bolsa, moneda) frente al eco del proveedor — misma regla que SPEC 70.
  const curatedEtfs = _aurixSearchEtfsLocal(query);
  const seen = new Set();
  const merged = [];
  for (const item of [...curatedEtfs, ...funds, ...metals, ...yEnriched, ...cryptoItems]) {
    if (!item || !item.ticker) continue;
    // SPEC ASSET-DISCOVERY-IDENTITY.V1 — la cripto se deduplica por IDENTIDAD CANÓNICA, no por
    // ticker. La clave `TK:` de abajo fusionaba dos tokens distintos que comparten símbolo (USD Coin
    // y un USDC puenteado, o cualquier token cuyo ticker choca con uno mayor): se fusionaba por
    // coincidencia de símbolo, que §7 prohíbe expresamente. Ahora sólo se fusiona lo que tiene la
    // MISMA identidad demostrable (mismo id de proveedor, o misma red+contrato). El resto de tipos
    // conserva su dedupe ISIN-first + ticker exacto tal cual.
    if (typeof _AURIX_DISCOVERY_IDENTITY_V1 !== 'undefined' && _AURIX_DISCOVERY_IDENTITY_V1
        && typeof _aurixCanonicalAssetKey === 'function' && String(item.type || '').toLowerCase() === 'crypto') {
      const ck = 'CANON:' + (_aurixCanonicalAssetKey(item) || ('TK:' + String(item.ticker).toUpperCase()));
      if (seen.has(ck)) continue;
      seen.add(ck); merged.push(item); continue;
    }
    // SPEC 70 — ISIN-first dedupe. THE same share class arriving from more than one source (the curated
    // catalog entry + its Yahoo twin) shares an ISIN → collapse to ONE unambiguous result. The curated
    // entry leads the merge, so it wins and keeps full identity (type/manager/currency/shareClass). This
    // kills the "three visually-identical options" for an exact-ISIN query WITHOUT deduping genuinely
    // different share classes (different ISINs stay distinct). Non-ISIN items keep the prior keys.
    const isin = item.isin ? String(item.isin).toUpperCase().trim() : '';
    const key = isin
      ? ('ISIN:' + isin)
      : (item.type === 'fund')
        ? 'FUND:' + String(item.ticker || item.name).toUpperCase()
        : String(item.ticker).toUpperCase();
    // MARKET-INSTITUTIONAL-V1 · §9 — segunda clave por TICKER EXACTO. La dedupe por
    // ISIN sola no basta desde que el catálogo curado aporta candidatos: la entrada
    // curada trae ISIN y su gemela del proveedor no, así que generaban dos claves
    // distintas y el MISMO producto salía dos veces (visto en "MSCI World": IWDA.AS y
    // URTH duplicados). Se compara el ticker EXACTO, sin normalizar el sufijo de
    // mercado, para no fusionar cotizaciones distintas del mismo fondo (IWDA.AS ≠
    // SWDA.L) ni clases de participación diferentes, que §9 prohíbe expresamente.
    const tkey = 'TK:' + String(item.ticker || '').toUpperCase().trim();
    if (seen.has(key) || seen.has(tkey)) continue;
    seen.add(key); seen.add(tkey); merged.push(item);
  }
  // El ranking sigue siendo el de SEARCH-V2.1: aquí sólo se mejora el conjunto de candidatos
  // (retrieval) y, tras el corte, se marca qué resultados necesitan desambiguación visual.
  const ranked = _aurixRankSearchResults(_aurixSearchProject(merged, filter), query).slice(0, 10);
  return (typeof _AURIX_DISCOVERY_IDENTITY_V1 !== 'undefined' && _AURIX_DISCOVERY_IDENTITY_V1
          && typeof _aurixMarkCryptoAmbiguity === 'function') ? _aurixMarkCryptoAmbiguity(ranked) : ranked;
}

// ── SPEC SEARCH-V2.2 — `searchByFilter` deja de ser un motor y pasa a ser una VISTA ──────────
// Antes tenía una rama por filtro: 'metal' local, 'crypto' directo a CoinGecko, 'stock'/'etf'
// directos a Yahoo y 'fund' con su propio merge, su propia clave de dedupe y su propio corte.
// Ninguna de ellas veía el catálogo curado, la dedupe por ISIN + ticker exacto ni el ranking, así
// que Add Asset con filtro y Market podían devolver distinto orden, distinto nombre o duplicados
// para el MISMO instrumento. Ahora hay un único pipeline y el filtro es una proyección dentro de
// él: mismos candidatos, misma normalización, mismos alias, mismo ranking y misma presentación.
async function searchByFilter(query, filter, signal) {
  return searchAllAssets(query, signal, filter);
}

// ── GLOBAL-SEARCH-1: Global asset search overlay ──────────────────────────
// A separate, dedicated surface for "find any asset and inspect it". Does
// not host the Add Asset / Liquidity flow — that stays in #modalOverlay
// and is reachable from a per-row "Add" button which opens the existing
// modal pre-populated with the selected asset (same flow used by the
// discovery cards in Market).
const _GLOBAL_SEARCH = {
  el:        null,
  input:     null,
  results:   null,
  hint:      null,
  empty:     null,
  loading:   null,
  chips:     null,
  inflight:  null,           // current AbortController
  lastQuery: '',
  debounce:  null,
};

// GLOBAL-SEARCH-3: only "Popular" quick-tap chips surface in the empty
// state. Each entry is just a search query piped into the existing
// searchAllAssets pipeline — every chip represents a real asset. No
// Category chips: a category chip should land on a real category page,
// and we don't have those yet, so showing one would be incoherent.
const _GS_TRENDING = [
  { label:'BTC',      q:'BTC'      },
  { label:'ETH',      q:'ETH'      },
  { label:'TSLA',     q:'TSLA'     },
  { label:'NVDA',     q:'NVDA'     },
  { label:'SPY',      q:'SPY'      },
  { label:'QQQ',      q:'QQQ'      },
  { label:'IWDA',     q:'IWDA'     },
  { label:'VWCE',     q:'VWCE'     },
  { label:'Gold',     q:'Gold'     },
  { label:'AAPL',     q:'AAPL'     },
];

// Recent searches — capped at 5, query string only (no portfolio data
// and no metadata about the user's holdings).
const _GS_RECENT_KEY    = 'aurix.gs.recent.v1';
const _GS_RECENT_MAX    = 5;
const _GS_RECENT_MAX_LEN= 32;

// SPEC CATEGORY-CONTEXT — recents are now typed objects { q, t } so the add-asset
// flow can show only recents of the active category. Backward-compatible: legacy
// plain-string entries load as { q, t: null } (untyped → only shown in the All view).
// The `t` is the SELECTED asset's classification at save time (reusing existing type),
// never hardcoded. Global search still reads only `.q`.
function _gsLoadRecent() {
  try {
    const raw = localStorage.getItem(_GS_RECENT_KEY);
    if (!raw) return [];
    const arr = JSON.parse(raw);
    if (!Array.isArray(arr)) return [];
    // MOBILE PASS 1A: drop fragments (< 3 chars = partial keystroke, not a selection).
    return arr
      .map(e => {
        if (typeof e === 'string') { const q = e.trim(); return q.length >= 3 ? { q, t: null } : null; }
        if (e && typeof e.q === 'string') { const q = e.q.trim(); return q.length >= 3 ? { q, t: (typeof e.t === 'string' ? e.t : null) } : null; }
        return null;
      })
      .filter(Boolean)
      .slice(0, _GS_RECENT_MAX);
  } catch (_) { return []; }
}
function _gsSaveRecent(q, type) {
  const v = String(q || '').trim();
  // MOBILE PASS 1A: enforce a 3-char minimum so partial keystrokes never enter the store.
  if (!v || v.length < 3 || v.length > _GS_RECENT_MAX_LEN) return;
  const t = (typeof type === 'string' && type) ? type : null;
  try {
    const cur = _gsLoadRecent();
    const next = [{ q: v, t }, ...cur.filter(x => x.q.toLowerCase() !== v.toLowerCase())].slice(0, _GS_RECENT_MAX);
    localStorage.setItem(_GS_RECENT_KEY, JSON.stringify(next));
  } catch (_) {}
}

function _gsInit() {
  if (_GLOBAL_SEARCH.el) return _GLOBAL_SEARCH.el;
  const el = document.getElementById('globalSearchOverlay');
  if (!el) return null;
  _GLOBAL_SEARCH.el         = el;
  _GLOBAL_SEARCH.input      = document.getElementById('globalSearchInput');
  _GLOBAL_SEARCH.results    = document.getElementById('globalSearchResults');
  _GLOBAL_SEARCH.hint       = document.getElementById('globalSearchHint');
  _GLOBAL_SEARCH.empty      = document.getElementById('globalSearchEmpty');
  _GLOBAL_SEARCH.loading    = document.getElementById('globalSearchLoading');
  _GLOBAL_SEARCH.trending      = document.getElementById('globalSearchTrending');
  _GLOBAL_SEARCH.recentSection = document.getElementById('globalSearchRecentSection');
  _GLOBAL_SEARCH.recentChips   = document.getElementById('globalSearchRecentChips');

  // Trending chips — static at init, never re-rendered.
  if (_GLOBAL_SEARCH.trending) {
    _GLOBAL_SEARCH.trending.innerHTML = _GS_TRENDING.map(c =>
      `<button type="button" class="gs-chip" data-gs-chip="${_gsEscape(c.q)}">${_gsEscape(c.label)}</button>`
    ).join('');
  }

  // Single delegated handler for every chip container — trending,
  // categories and recents share the same data-gs-chip contract.
  el.addEventListener('click', e => {
    const chip = e.target.closest('[data-gs-chip]');
    if (!chip || !_GLOBAL_SEARCH.input) return;
    _GLOBAL_SEARCH.input.value = chip.dataset.gsChip;
    _GLOBAL_SEARCH.input.focus();
    _gsRunSearch();
  });

  // Input → debounced search via the existing searchAllAssets pipeline.
  _GLOBAL_SEARCH.input?.addEventListener('input', () => {
    clearTimeout(_GLOBAL_SEARCH.debounce);
    _GLOBAL_SEARCH.debounce = setTimeout(_gsRunSearch, 220);
  });

  // Close affordances: button, backdrop, Escape key.
  document.getElementById('globalSearchClose')?.addEventListener('click', closeGlobalSearch);
  el.addEventListener('click', e => { if (e.target === el) closeGlobalSearch(); });
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && !el.hidden) closeGlobalSearch();
  });

  // Delegated row clicks: two actions — "Chart" opens the Market
  // Preview chart (SEARCH-1, reuses _aurixMktOpenSymbol with an item
  // override). "Add" routes through the existing Add Asset flow.
  _GLOBAL_SEARCH.results?.addEventListener('click', e => {
    const btn = e.target.closest('[data-gs-action]');
    if (!btn) return;
    const row  = btn.closest('[data-gs-ticker]');
    if (!row) return;
    const idx  = Number(row.dataset.gsIndex);
    const item = _GLOBAL_SEARCH._lastItems?.[idx];
    if (!item) return;
    const action = btn.dataset.gsAction;
    // Save chosen asset's label as "recent" before either action so
    // both surfaces (chart / add) feed the same recent-search history.
    const label = (item.name && item.name.trim()) || (item.ticker || '').trim();
    if (label) _gsSaveRecent(label, item.type);   // SPEC CATEGORY-CONTEXT — tag with the asset's own classification

    if (action === 'chart') {
      const mItem = _searchResultToMarketItem(item);
      if (!mItem) return;
      // Close search first so the preview overlay is the topmost layer
      // and the user's focus isn't trapped between two stacked sheets.
      closeGlobalSearch();
      const opened = (typeof _aurixMktOpenSymbol === 'function')
        ? _aurixMktOpenSymbol(mItem.symbol, mItem)
        : false;
      if (!opened) {
        // Graceful degradation: if the preview can't open (missing
        // adapter ids on the catalog item), fall through to Add Asset.
        _openAddAssetWithFund(item);
      }
      return;
    }
    if (action === 'add') {
      closeGlobalSearch();
      _openAddAssetWithFund(item);
      return;
    }
  });

  return el;
}

// Render the Recent chip row (or hide the section if empty). Called
// every time the overlay opens so newly stored searches surface.
function _gsRenderRecent() {
  if (!_GLOBAL_SEARCH.recentSection || !_GLOBAL_SEARCH.recentChips) return;
  const recent = _gsLoadRecent();
  if (!recent.length) {
    _GLOBAL_SEARCH.recentSection.hidden = true;
    return;
  }
  // Global search is category-agnostic — render every recent query (ignore the type tag).
  _GLOBAL_SEARCH.recentChips.innerHTML = recent.map(r =>
    `<button type="button" class="gs-chip is-recent" data-gs-chip="${_gsEscape(r.q)}">${_gsEscape(r.q)}</button>`
  ).join('');
  _GLOBAL_SEARCH.recentSection.hidden = false;
}

// GLOBAL-SEARCH-2: explicit state machine — empty / loading / results /
// noresults — toggles visibility of the four body blocks. Single
// source of truth so transitions never leave two blocks visible at
// once.
function _gsSetState(state) {
  const map = {
    empty:    [_GLOBAL_SEARCH.empty],
    loading:  [_GLOBAL_SEARCH.loading],
    results:  [_GLOBAL_SEARCH.results],
    noresults:[_GLOBAL_SEARCH.hint],
  };
  for (const k of Object.keys(map)) {
    for (const node of map[k]) {
      if (!node) continue;
      node.hidden = (k !== state);
    }
  }
  // Results UL is hidden via .hidden — also clear it in non-results
  // states so a stale render doesn't flash on the next open.
  if (state !== 'results' && _GLOBAL_SEARCH.results) {
    _GLOBAL_SEARCH.results.innerHTML = '';
  }
  if (state === 'noresults' && _GLOBAL_SEARCH.hint) {
    _GLOBAL_SEARCH.hint.textContent = t('globalSearchNoResultsHint') || t('globalSearchNoResults') || 'No results';
  }
}

function openGlobalSearch() {
  const el = _gsInit();
  if (!el) return;
  el.hidden = false;
  document.body.classList.add('gs-open');
  // Reset state — fresh focus, no stale results, empty state visible.
  if (_GLOBAL_SEARCH.input) {
    _GLOBAL_SEARCH.input.value = '';
    setTimeout(() => _GLOBAL_SEARCH.input.focus(), 30);
  }
  _GLOBAL_SEARCH.lastQuery = '';
  _GLOBAL_SEARCH._lastItems = [];
  _gsRenderRecent();
  _gsSetState('empty');
}

function closeGlobalSearch() {
  const el = _GLOBAL_SEARCH.el || document.getElementById('globalSearchOverlay');
  if (!el) return;
  el.hidden = true;
  document.body.classList.remove('gs-open');
  if (_GLOBAL_SEARCH.inflight) { try { _GLOBAL_SEARCH.inflight.abort(); } catch (_) {} _GLOBAL_SEARCH.inflight = null; }
}

async function _gsRunSearch() {
  const input = _GLOBAL_SEARCH.input;
  if (!input) return;
  const q = String(input.value || '').trim();
  if (q === _GLOBAL_SEARCH.lastQuery) return;
  _GLOBAL_SEARCH.lastQuery = q;

  if (!q) {
    _GLOBAL_SEARCH._lastItems = [];
    _gsSetState('empty');
    return;
  }

  if (_GLOBAL_SEARCH.inflight) { try { _GLOBAL_SEARCH.inflight.abort(); } catch (_) {} }
  const ctrl = new AbortController();
  _GLOBAL_SEARCH.inflight = ctrl;
  _gsSetState('loading');

  let items = [];
  try {
    items = await searchAllAssets(q, ctrl.signal) || [];
  } catch (err) {
    if (err?.name !== 'AbortError') console.warn('[global-search] error:', err?.message);
    return;
  }
  if (ctrl.signal.aborted) return;
  _GLOBAL_SEARCH._lastItems = items;
  if (!items.length) {
    _gsSetState('noresults');
    return;
  }
  // MOBILE PASS 1A: do NOT persist the raw query here — that captured
  // every keystroke that returned ≥1 result (Or, Mstr, Go, etc.). We
  // now save only when the user explicitly clicks a result row, via
  // the delegated click handler below. The saved value is the picked
  // asset's ticker or name — a meaningful, completed selection.
  _gsSetState('results');
  _gsRenderResults(items);

  // Hydrate prices for the visible rows in parallel via the canonical
  // resolveSymbolQuote path — no new provider, no pricing logic added.
  items.forEach((item, i) => {
    const sym = item.marketSymbol || item.ticker;
    if (!sym) return;
    resolveSymbolQuote(sym).then(q => {
      if (ctrl.signal.aborted) return;
      const row = _GLOBAL_SEARCH.results?.querySelector(`[data-gs-index="${i}"] .gs-row-meta`);
      if (!row) return;
      if (q && typeof q.price === 'number' && !Number.isNaN(q.price)) {
        const curr = q.currency || item.currency || 'USD';
        const provider = q.source || q.provider || '';
        row.textContent = `${curr} ${q.price.toLocaleString('en-US', { maximumFractionDigits: 2 })}${provider ? ' · ' + provider : ''}`;
      }
    }).catch(() => {});
  });
}

function _gsBadgeFor(type) {
  const k = String(type || '').toLowerCase();
  const map = { crypto:'CRYPTO', stock:'STOCK', etf:'ETF', fund:'FUND', index:'INDEX', commodity:'COMM', metal:'METAL' };
  return { kind: k, label: map[k] || '' };
}

function _gsEscape(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function _gsRenderResults(items) {
  if (!_GLOBAL_SEARCH.results || !items.length) return;
  const addLabel   = t('gs_add_to_portfolio') || '+ Añadir';
  // SEARCH-1: primary "Ver gráfico" action reuses the existing Market
  // Preview chart (no new chart engine, no new endpoint). "Añadir"
  // becomes the secondary glass button.
  const chartLabel = t('gs_view_chart') || 'Ver gráfico';
  _GLOBAL_SEARCH.results.innerHTML = items.map((item, i) => {
    const b = _gsBadgeFor(item.type);
    return `
      <li class="gs-row" data-gs-ticker="${_gsEscape(item.ticker)}" data-gs-index="${i}">
        <div class="gs-row-main">
          <div class="gs-row-line">
            <span class="gs-row-ticker">${_gsEscape(item.ticker)}</span>
            ${b.label ? `<span class="gs-row-badge is-${_gsEscape(b.kind)}">${_gsEscape(b.label)}</span>` : ''}
            <span class="gs-row-name">${_gsEscape((typeof getDisplayName === 'function') ? getDisplayName(item) : item.name)}</span>
          </div>
          <div class="gs-row-meta">—</div>
        </div>
        <div class="gs-row-actions">
          <button class="gs-row-btn is-primary"   type="button" data-gs-action="chart">${_gsEscape(chartLabel)}</button>
          <button class="gs-row-btn is-secondary" type="button" data-gs-action="add">${_gsEscape(addLabel)}</button>
        </div>
      </li>
    `;
  }).join('');
}

// SEARCH-1: normalize a search result into the item shape the Market
// Preview expects. The preview reads:
//   symbol (ticker), name, type, coinId | marketSymbol, current_price,
//   change24h. Search results already carry most of these — this is
//   mostly a passthrough that uppercases the symbol and ensures the
//   adapter ids are surfaced verbatim.
function _searchResultToMarketItem(result) {
  if (!result) return null;
  const ticker = String(result.ticker || result.symbol || '').toUpperCase();
  if (!ticker) return null;
  return {
    symbol:         ticker,
    ticker,
    name:           result.name || ticker,
    type:           String(result.type || 'other').toLowerCase(),
    coinId:         result.coinId       || null,
    marketSymbol:   result.marketSymbol || null,
    // MARKET-V2-02B — `/api/search/assets` YA publica `exchange` (exchDisp de Yahoo) y este
    // puente lo estaba descartando, así que el mercado no llegaba nunca a la ficha aunque
    // existiera. Paso directo, sin transformar ni deducir: si la fuente no lo trae, null.
    exchange:       result.exchange     || null,
    isin:           result.isin         || null,
    currency:       result.currency     || 'USD',
    current_price:  result.price        ?? result.current_price ?? null,
    price:          result.price        ?? result.current_price ?? null,
    change24h:      result.change24h    ?? null,
    // SPEC ASSET-DISCOVERY-IDENTITY.V1 — la identidad canónica viaja INTACTA hasta Market: la fila
    // de discovery ya no se identifica por símbolo, así que dos tokens con el mismo ticker abren
    // fichas distintas y el paso a Add Asset conserva red y contrato. Campos aditivos: si el
    // resultado no los trae, quedan null (nunca se deducen).
    canonicalKey:   result.canonicalKey  || (typeof _aurixCanonicalAssetKey === 'function' ? _aurixCanonicalAssetKey(result) : null),
    chain:          result.chain         || null,
    networkId:      result.networkId     || null,
    contract:       result.contract      || null,
    // El logo del proveedor (CoinGecko) ya venía en el resultado y este puente lo descartaba, así
    // que un activo long-tail (HYPE) perdía su icono al pasar por Market. getAssetLogo lo prefiere.
    image:          result.image         || null,
    source:         result.source        || null,
    // señal REAL de capitalización del proveedor (CoinGecko la publica en /search): decide qué
    // resultado es el dueño demostrable de un símbolo compartido en _aurixMktHydrateQuotes.
    marketCapRank:  Number.isFinite(result.marketCapRank) ? result.marketCapRank : null,
    symbolCollision: result.symbolCollision === true,
    matchedBy:      result.matchedBy     || null,
    priceable:      result.priceable !== false,
  };
}

// ── Render suggestions ────────────────────────────────────
// TYPE_LABEL is derived from translations at render time — no static const needed

function showDefaultSuggestions() {
  const defaults = DEFAULTS[activeSearchFilter] || [];
  // ADD-ASSET-DISCOVERY-1: never bail with no UI — when a filter has
  // no curated set (e.g. real_estate routes elsewhere), show a calm
  // hint instead of an empty surface so the user always knows what
  // to do next.
  if (!defaults.length) {
    assetSuggestionsEl.innerHTML =
      `<div class="suggestion-empty">${escHtml(t('searchEmptyHint') || 'Search by name, ticker or ISIN.')}</div>`;
    assetSuggestionsEl.classList.add('open');
    renderedSuggestions = [];
    return;
  }
  renderedSuggestions = defaults;

  // Contextual label per filter — "Criptos populares" / "ETFs populares"
  // / etc. — falls back to the generic "Populares" key.
  const labelText = t(`searchPopularLabel_${activeSearchFilter}`) || t('searchPopularLabel') || 'Populares';

  assetSuggestionsEl.innerHTML = `
    <div class="sugg-section-label">${escHtml(labelText)}</div>
    ${defaults.map((a, i) => `
      <div class="suggestion-item" data-idx="${i}">
        ${_assetIconHtml(a, a.ticker, 'sugg-badge ' + a.type)}
        <div class="sugg-info">
          <div class="sugg-name">${escHtml(getDisplayName(a))}</div>
          <div class="sugg-ticker">${escHtml((typeof _aurixSearchSubtitle === 'function') ? _aurixSearchSubtitle(a) : a.ticker)}</div>
        </div>
      </div>`).join('')}`;

  assetSuggestionsEl.classList.add('open');
  assetSuggestionsEl.querySelectorAll('.suggestion-item[data-idx]').forEach((item, i) => {
    item.addEventListener('click',      () => { closeSuggestions(); selectAsset(defaults[i]); });
    item.addEventListener('mouseenter', () => setFocusedSugg(i));
  });
}

function renderSuggestions(results, query, loading = false) {
  renderedSuggestions = results;

  const loadingHtml = loading
    ? `<div class="suggestion-loading"><span class="sugg-dot-anim">···</span> ${t('searchLoading')}</div>`
    : '';

  if (!results.length) {
    // SPEC ASSET-DISCOVERY-IDENTITY.V1 — §7 DATA HONESTY. Un contrato que no resuelve no puede
    // leerse como "no hay nada": hay que distinguir "ese contrato no existe en las redes que
    // soportamos" de "el proveedor no ha respondido". El texto genérico se mantiene para todo lo demás.
    let emptyHtml = `<div class="suggestion-empty">${t('noResults')(escHtml(query))}</div>`;
    try {
      if (typeof _AURIX_DISCOVERY_IDENTITY_V1 !== 'undefined' && _AURIX_DISCOVERY_IDENTITY_V1
          && typeof _aurixLooksLikeContract === 'function' && _aurixLooksLikeContract(query)) {
        const st = (typeof _aurixContractLookup === 'object' && _aurixContractLookup) ? _aurixContractLookup.state : null;
        const msg = (st === 'provider_unavailable') ? t('contractProviderDown') : (st === 'not_found' ? t('contractNotFound') : null);
        if (msg) emptyHtml = `<div class="suggestion-empty">${escHtml(msg)}</div>`;
      }
    } catch (_) {}
    assetSuggestionsEl.innerHTML = loadingHtml || emptyHtml;
    assetSuggestionsEl.classList.add('open');
    return;
  }

  assetSuggestionsEl.innerHTML = results.map((a, i) => `
    <div class="suggestion-item" data-idx="${i}">
      ${_assetIconHtml(a, a.ticker, 'sugg-badge ' + a.type)}
      <div class="sugg-info">
        <div class="sugg-name">${escHtml(getDisplayName(a))}</div>
        <div class="sugg-ticker">${escHtml((typeof _aurixSearchSubtitle === 'function') ? _aurixSearchSubtitle(a) : a.ticker)}</div>
      </div>
    </div>`).join('') + loadingHtml;

  assetSuggestionsEl.classList.add('open');
  assetSuggestionsEl.querySelectorAll('.suggestion-item[data-idx]').forEach((item, i) => {
    item.addEventListener('click',      () => { closeSuggestions(); selectAsset(results[i]); });
    item.addEventListener('mouseenter', () => setFocusedSugg(i));
  });
}

function closeSuggestions() {
  assetSuggestionsEl.classList.remove('open');
  focusedSuggIdx = -1;
  // SPEC 63 — refresh the sheet flow state so closing the results list (with no
  // query / chip) lets the sheet return to its resting anchor.
  if (typeof _updateSearchEmptyHint === 'function') _updateSearchEmptyHint();
}

function setFocusedSugg(idx) {
  focusedSuggIdx = idx;
  assetSuggestionsEl.querySelectorAll('.suggestion-item[data-idx]').forEach((el, i) => {
    el.classList.toggle('focused', i === idx);
  });
}

async function selectAsset(entry) {
  selectedDbAsset     = entry;
  pendingCoinId       = null;
  pendingMarketSymbol = null;
  pendingPrice        = null;
  pendingCurrency     = null;
  pendingIsManualNav  = false;

  // Show chip, hide search
  chipBadgeEl.textContent         = entry.ticker.slice(0, 4);
  chipBadgeEl.className           = `chip-badge ${entry.type}`;
  chipNameEl.textContent          = getDisplayName(entry);
  chipSubEl.textContent           = `${entry.ticker} · ${T[lang].typeLabel[entry.type] || entry.type}`;
  chipPriceEl.textContent         = '⋯';
  selectedChipEl.style.display    = '';
  searchInputWrapEl.style.display = 'none';
  if (searchFiltersEl) searchFiltersEl.style.display = 'none';
  if (typeof _updateSearchEmptyHint === 'function') _updateSearchEmptyHint();
  // ADD-V4.2: populate the desktop preview header as soon as the
  // selection happens; price line updates again once the async fetch
  // resolves below (chipPrice / pendingPrice).
  if (typeof _addV4RenderPreview === 'function') _addV4RenderPreview();

  // Reveal qty + submit
  qtyGroup.style.display    = '';
  formPreviewEl.style.display = '';
  btnSubmitEl.style.display  = '';
  // PURCHASE-PRICE-V1 — reveal the optional purchase-price field for every priced
  // market/DB asset (stock/etf/fund/crypto AND gold). For gold the canonical price unit
  // is troy OUNCE (asset.price / pendingPrice / the stored tx price are all per-oz spot,
  // and assetPnLBase consumes qty×price) — so the field is entered + persisted per oz
  // (no parallel conversion), and the unit is labelled explicitly. Real-estate/manual/
  // cash paths never reach this reveal.
  { const _ppg = document.getElementById('purchasePriceGroup'); if (_ppg) _ppg.style.display = '';
    const _ppu = document.getElementById('purchasePriceUnit'); if (_ppu) _ppu.textContent = (entry.ticker === 'XAU') ? t('purchasePricePerOz') : ''; }
  // GOLD-UX-2: per-asset CTA copy. Non-gold assets keep the canonical
  // "Añadir a cartera" / "Add to portfolio"; gold enters disabled
  // with "Completa los datos" until the user finishes the flow.
  if (entry.ticker === 'XAU') {
    btnSubmitEl.textContent = t('gold_cta_complete');
    btnSubmitEl.disabled    = true;
    btnSubmitEl.classList.add('btn-submit--disabled');
  } else {
    btnSubmitEl.textContent = t('addToPortfolio');
    btnSubmitEl.disabled    = false;
    btnSubmitEl.classList.remove('btn-submit--disabled');
  }

  // GOLD-1: physical gold section + karat/unit selectors. Section
  // banner header shows the live spot reference so the user grasps
  // the price-per-gram before entering quantity.
  // GOLD-1B: ISIN input is irrelevant for physical gold (rings, coins,
  // bars, jewelry) — hide it whenever XAU is selected; restore for
  // anything else.
  const isGoldEntry = entry.ticker === 'XAU';
  const goldSectionEl = document.getElementById('goldSection');
  const isinOrWrapEl  = document.getElementById('isinOrWrap');
  if (goldSectionEl)   goldSectionEl.style.display   = isGoldEntry ? '' : 'none';
  if (karatGroupEl)    karatGroupEl.style.display    = isGoldEntry ? '' : 'none';
  if (goldUnitGroupEl) goldUnitGroupEl.style.display = isGoldEntry ? '' : 'none';
  if (isinOrWrapEl)    isinOrWrapEl.style.display    = isGoldEntry ? 'none' : '';
  if (qtyLabelEl)      qtyLabelEl.textContent        = isGoldEntry ? t('qtyGold')(pendingGoldUnit) : t('qty');
  if (!isGoldEntry) _renderGoldSpotLine(null);
  // ADD-V4.1: sync the new gold buttons to the pending state so the
  // active highlights match whether the user landed via the picker
  // shortcut or via the search dropdown. Also rehome the qty input
  // into the "What do you own?" group, or restore it when leaving.
  if (isGoldEntry) {
    if (typeof _addV4SyncGoldUI === 'function')      _addV4SyncGoldUI();
    if (typeof _addV4MoveQtyIntoGold === 'function') _addV4MoveQtyIntoGold();
  } else {
    if (typeof _addV4RestoreQty === 'function') _addV4RestoreQty();
  }

  setLookupStatus('loading', t('lookupLoading'));

  try {
    let price = null;

    if (entry.type === 'crypto' && entry.coinId) {
      pendingCoinId = entry.coinId;
      const data    = await fetchLivePrices([entry.coinId]);
      price         = data[entry.coinId]?.usd ?? null;
      // Some coins return 0 as price (stablecoin edge cases) — treat as valid
      if (price === null || price === undefined) price = null;
    } else if (entry.marketSymbol) {
      pendingMarketSymbol = entry.marketSymbol;
      if (entry.ticker === 'XAU') {
        // Gold: dedicated source chain (XAU/USD → GC=F → fallback) via snapshot.
        // Always USD-denominated, so no currency capture needed.
        price = await fetchGoldSpotPrice();
      } else {
        // MC-6D: use resolveSymbolQuote so we can stamp the real provider
        // quote currency onto the asset at push time. Falls back to legacy
        // fallback data (USD) if the gateway returned nothing.
        const quote = await resolveSymbolQuote(entry.marketSymbol);
        if (quote) {
          price = quote.price;
          if (quote.currency) pendingCurrency = quote.currency;
        } else {
          const fb = getFallbackData(entry.marketSymbol);
          price   = fb?.price ?? null;
        }
      }
    } else if (entry.type === 'fund' && entry.isin && !entry.marketSymbol) {
      // SPEC 70 — AUTOMATIC NAV for discovered/curated funds. A curated catalog fund carries an ISIN but
      // no priceable marketSymbol, so it previously fell straight to the MC-7 MANUAL NAV path (frozen).
      // Resolve the automatic priceable symbol via the SAME owner the ISIN add-path uses
      // (_yahooFundSymbolByISIN → the Morningstar 0P* code Yahoo serves fund NAVs for, broker-ticker
      // fallback otherwise) and ADOPT it as the provider key: pricing here, persistence (submit reads
      // selectedDbAsset.marketSymbol === entry.marketSymbol) and the per-symbol refresh then all run the
      // automatic Yahoo NAV path — identical to a fund added directly by ISIN. General (every curated
      // fund), NO per-ISIN exception. If no symbol resolves, price stays null and the existing MC-7
      // manual-NAV path (explicitly labelled "Manual NAV") handles genuinely non-automatic funds.
      const _fundSym = await _yahooFundSymbolByISIN(entry.isin);
      if (_fundSym) {
        entry.marketSymbol  = _fundSym;   // persisted at submit → survives reopen → same provider on refresh
        pendingMarketSymbol = _fundSym;
        const quote = await resolveSymbolQuote(_fundSym);
        if (quote) { price = quote.price; if (quote.currency) pendingCurrency = quote.currency; }
        else { const fb = getFallbackData(_fundSym); price = fb?.price ?? null; }
      }
    }

    if (price) {
      pendingPrice            = price;
      chipPriceEl.textContent = formatDisplay(price, 'USD');
      setLookupStatus('ok', '');
      if (typeof _addV4RenderPreview === 'function') _addV4RenderPreview();
    } else if (entry.type === 'fund') {
      // MC-7: provider couldn't price this fund — let the user enter NAV.
      chipPriceEl.textContent = t('noPrice');
      _showManualNavPrompt(entry);
    } else {
      chipPriceEl.textContent = t('noPrice');
      // GOLD-PRICE-1: physical gold no longer falls back to a hardcoded
      // simulated price, so surface a gold-specific message that nudges
      // the user to retry instead of the generic "no disponible".
      setLookupStatus('error', entry.ticker === 'XAU' ? t('goldPriceUnavail') : t('priceUnavail'));
    }
  } catch (err) {
    // Network error: try local fallback for non-crypto.
    // GOLD-PRICE-1: gold is excluded — physical gold confirmation must
    // never lock in a simulated price, even from the offline fallback.
    const fb = (entry.marketSymbol && entry.ticker !== 'XAU') ? getFallbackData(entry.marketSymbol) : null;
    if (fb) {
      pendingPrice            = fb.price;
      chipPriceEl.textContent = formatDisplay(fb.price, 'USD');
      setLookupStatus('ok', '');
    } else if (entry.type === 'fund') {
      // MC-7: also offer manual NAV when the provider call threw.
      chipPriceEl.textContent = t('noPrice');
      _showManualNavPrompt(entry);
    } else {
      chipPriceEl.textContent = t('noPrice');
      setLookupStatus('error', entry.ticker === 'XAU' ? t('goldPriceUnavail') : t('priceNoConn'));
    }
  }

  updatePreview();
  qtyInput.focus();
}

function clearSelectedAsset() {
  selectedDbAsset      = null;
  pendingCoinId        = null;
  pendingMarketSymbol  = null;
  pendingPrice         = null;
  pendingCurrency      = null;
  pendingIsManualNav   = false;
  pendingKarat         = 18;
  pendingGoldUnit      = 'g';
  pendingResaleMargin  = 8;
  // Reset margin chip active state so a future XAU selection starts
  // from the 8% default (matches the persisted default factor 0.92).
  document.querySelectorAll('#goldMarginChips [data-margin]').forEach(b => {
    b.classList.toggle('active', b.dataset.margin === '8');
  });
  selectedChipEl.style.display = 'none';
  if (karatGroupEl)    karatGroupEl.style.display    = 'none';
  if (goldUnitGroupEl) goldUnitGroupEl.style.display = 'none';
  const _gsEl = document.getElementById('goldSection');
  if (_gsEl) _gsEl.style.display = 'none';
  // PURCHASE-PRICE-V1 — deselecting hides the purchase-price field so it never lingers
  // into the real-estate / manual / idle flows (re-selecting a priced asset re-reveals it).
  { const _ppg = document.getElementById('purchasePriceGroup'); if (_ppg) _ppg.style.display = 'none'; }
  // GOLD-1B: restore the ISIN entry when leaving a physical-gold
  // selection so the user can switch to ETF/fund/manual input again.
  const _isinEl = document.getElementById('isinOrWrap');
  if (_isinEl) _isinEl.style.display = '';
  _renderGoldSpotLine(null);
  if (qtyLabelEl)      qtyLabelEl.textContent        = t('qty');
  setLookupStatus('');
  updatePreview();
  if (typeof _updateSearchEmptyHint === 'function') _updateSearchEmptyHint();
  // ADD-V4.1: when leaving gold, restore qty input to its original spot.
  if (typeof _addV4RestoreQty === 'function') _addV4RestoreQty();
  // ADD-V4.2: reset the desktop preview panel to its placeholder.
  if (typeof _addV4RenderPreview === 'function') _addV4RenderPreview();
}

function enterSearchMode() {
  isRealEstateMode = false;
  if (isManualMode) exitManualMode();
  const isinOrWrap = document.getElementById('isinOrWrap');
  if (isinOrWrap) isinOrWrap.style.display = '';
  const reNameGroupEl = document.getElementById('reNameGroup');
  const reCurrGroupEl = document.getElementById('reCurrGroup');
  const reRentGroupEl = document.getElementById('reRentGroup');
  if (reNameGroupEl) reNameGroupEl.style.display = 'none';
  if (reCurrGroupEl) reCurrGroupEl.style.display = 'none';
  if (reRentGroupEl) reRentGroupEl.style.display = 'none';

  clearSelectedAsset();
  searchInputWrapEl.style.display = '';
  if (searchFiltersEl) searchFiltersEl.style.display = '';
  searchInput.value            = '';
  searchClearBtn.style.display = 'none';
  qtyGroup.style.display       = 'none';
  formPreviewEl.style.display  = 'none';
  btnSubmitEl.style.display    = 'none';
  closeSuggestions();
  searchInput.placeholder = T[lang].searchPH[activeSearchFilter] || T[lang].searchPH.all;
  // ADD-ASSET-DISCOVERY-1: when returning from a selected asset to
  // browse mode, surface curated defaults again instead of leaving
  // the suggestion area empty.
  setTimeout(() => {
    if (!searchInput.value.trim()) showDefaultSuggestions();
  }, 40);
  suppressFocusDefaults = true;
  setTimeout(() => searchInput.focus(), 0);
}

function enterRealEstateMode() {
  isRealEstateMode   = true;
  rePendingCurrency  = 'EUR';
  rePendingRent      = 0;
  clearSelectedAsset();
  closeSuggestions();

  // Also exit manual mode if active and hide ISIN section
  if (isManualMode) exitManualMode();
  const isinOrWrap = document.getElementById('isinOrWrap');
  if (isinOrWrap) isinOrWrap.style.display = 'none';

  searchInputWrapEl.style.display = 'none';

  const reNameGroupEl = document.getElementById('reNameGroup');
  const reCurrGroupEl = document.getElementById('reCurrGroup');
  const reRentGroupEl = document.getElementById('reRentGroup');
  if (reNameGroupEl) reNameGroupEl.style.display = '';
  if (reCurrGroupEl) reCurrGroupEl.style.display = '';
  if (reRentGroupEl) reRentGroupEl.style.display = '';

  // Reset currency toggle to EUR
  document.querySelectorAll('.re-curr-btn').forEach(b =>
    b.classList.toggle('active', b.dataset.curr === 'EUR'));

  // Clear rent input
  const reRentInput = document.getElementById('reRent');
  if (reRentInput) reRentInput.value = '';

  if (qtyLabelEl) qtyLabelEl.textContent = t('reValueLabel');
  qtyGroup.style.display      = '';
  formPreviewEl.style.display = '';
  btnSubmitEl.style.display   = '';
  setLookupStatus('');

  const reNameInput = document.getElementById('reName');
  if (reNameInput) { reNameInput.value = ''; reNameInput.focus(); }
}

// ── Search event listeners (two-phase: instant local + debounced API) ──
searchInput.addEventListener('input', () => {
  const q = searchInput.value.trim();
  searchClearBtn.style.display = q ? '' : 'none';

  clearTimeout(searchDebounceTimer);
  clearTimeout(searchSpinnerTimer);
  if (searchAbortCtrl) { searchAbortCtrl.abort(); searchAbortCtrl = null; }

  if (!q) {
    // ADD-ASSET-DISCOVERY-1: clearing the query restores the curated
    // set for the current tab instead of closing the suggestion
    // surface. Keeps the picker actionable at all times.
    showDefaultSuggestions();
    return;
  }

  // Phase 1 — instant local results. Loading state is intentionally
  // suppressed here; the 150 ms delayed spinner below covers the
  // API-pending window, so fast responses never flash a loading row.
  // For the 'all' filter (or any filter whose local set is empty) we
  // skip the immediate paint and let the popover keep whatever it had
  // until either the spinner fires or the API returns.
  const localResults = getLocalResults(q, activeSearchFilter);
  currentSuggestions = localResults;
  if (localResults.length > 0 && activeSearchFilter !== 'all') {
    renderSuggestions(localResults, q, false);
  }

  // Phase 2 — API results after 300ms (skip for metals, they're local only)
  if (activeSearchFilter === 'metal') return;

  searchDebounceTimer = setTimeout(async () => {
    searchAbortCtrl = new AbortController();
    const { signal } = searchAbortCtrl;

    // SEARCH-DELAYED-SPINNER-1: only paint the loading indicator if the
    // request is still in flight after 150 ms. The signal + query guards
    // make sure a search the user has already abandoned cannot paint
    // a spinner over the new one.
    searchSpinnerTimer = setTimeout(() => {
      if (signal.aborted) return;
      if (searchInput.value.trim() !== q) return;
      renderSuggestions(currentSuggestions, q, true);
    }, 150);

    try {
      const results = await searchByFilter(q, activeSearchFilter, signal);
      clearTimeout(searchSpinnerTimer);
      if (signal.aborted || searchInput.value.trim() !== q) return;
      if (results && results.length) currentSuggestions = results;
      renderSuggestions(currentSuggestions, q, false);
    } catch (err) {
      clearTimeout(searchSpinnerTimer);
      if (err.name === 'AbortError') return;
      if (searchInput.value.trim() !== q) return;
      renderSuggestions(currentSuggestions, q, false);
    }
  }, 300);
});

searchInput.addEventListener('keydown', e => {
  if (!assetSuggestionsEl.classList.contains('open')) return;
  if (e.key === 'ArrowDown') {
    e.preventDefault();
    setFocusedSugg(Math.min(focusedSuggIdx + 1, renderedSuggestions.length - 1));
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    setFocusedSugg(Math.max(focusedSuggIdx - 1, 0));
  } else if (e.key === 'Enter') {
    e.preventDefault();
    if (focusedSuggIdx >= 0 && renderedSuggestions[focusedSuggIdx]) {
      closeSuggestions();
      selectAsset(renderedSuggestions[focusedSuggIdx]);
    }
  } else if (e.key === 'Escape') {
    closeSuggestions();
  }
});

searchClearBtn.addEventListener('click', () => {
  searchInput.value = '';
  searchClearBtn.style.display = 'none';
  clearTimeout(searchDebounceTimer);
  clearTimeout(searchSpinnerTimer);
  if (searchAbortCtrl) { searchAbortCtrl.abort(); searchAbortCtrl = null; }
  closeSuggestions();
  suppressFocusDefaults = true;
  searchInput.focus();
});

// ADD-ASSET-DISCOVERY-1: focus on the empty search now ALWAYS shows
// the curated defaults (including the 'all' tab), so the picker
// never feels blank just because the user tapped the input.
searchInput.addEventListener('focus', () => {
  if (suppressFocusDefaults) { suppressFocusDefaults = false; return; }
  if (!searchInput.value.trim()) {
    showDefaultSuggestions();
  }
});


chipClearBtn.addEventListener('click', () => enterSearchMode());

// ── Mobile ISIN toggle ─────────────────────────────────────
// On phones the ISIN field is collapsed by default — most users search by
// name/ticker, so the advanced ISIN entry stays one tap away rather than
// dominating the sheet. Desktop keeps the original always-visible layout.
const _isinToggleBtn = document.getElementById('isinToggleMobile');
const _searchWrapEl  = document.getElementById('searchWrap');
function _setIsinRevealed(revealed) {
  if (!_searchWrapEl || !_isinToggleBtn) return;
  _searchWrapEl.classList.toggle('isin-revealed', revealed);
  _isinToggleBtn.setAttribute('aria-expanded', revealed ? 'true' : 'false');
  const labelEl = _isinToggleBtn.querySelector('.isin-toggle-label');
  if (labelEl) labelEl.textContent = revealed ? t('isinToggleHide') : t('isinToggleShow');
  const iconEl = _isinToggleBtn.querySelector('.isin-toggle-icon');
  if (iconEl)  iconEl.textContent  = revealed ? '−' : '+';
}
if (_isinToggleBtn) {
  _isinToggleBtn.addEventListener('click', () => {
    const revealed = !_searchWrapEl.classList.contains('isin-revealed');
    _setIsinRevealed(revealed);
    if (revealed) {
      const isinEl = document.getElementById('isinInput');
      setTimeout(() => isinEl && isinEl.focus(), 60);
    }
  });
}

// Helper hint visibility — show only when the user has nothing typed,
// no chip selected, and the suggestions list is empty. JS-driven so we
// can hook into the existing search lifecycle without CSS :has() gaps.
// ADD-V2.2: also toggles the quick-picks block via a class so the CSS
// rule that's mode-gated can do the rest.
const _searchEmptyHintEl = document.getElementById('searchEmptyHint');
function _updateSearchEmptyHint() {
  const hasChip   = selectedChipEl && selectedChipEl.style.display !== 'none';
  const hasQuery  = !!(searchInput && searchInput.value.trim());
  const inputOpen = !!(searchInputWrapEl && searchInputWrapEl.style.display !== 'none');
  const idle = inputOpen && !hasChip && !hasQuery;
  if (_searchEmptyHintEl) _searchEmptyHintEl.style.display = idle ? '' : 'none';
  const quickEl = document.getElementById('addV2Quick');
  if (quickEl) quickEl.classList.toggle('is-hidden', !idle);
  // SPEC 63 — expose the asset-sheet flow state to the layout so the mobile
  // sheet stays TOP-anchored while a query / results / selection is active,
  // not only while an input is :focus-within. Done/blur removes focus but must
  // NOT drop the sheet (bug A); keeping the sheet put also stops the tapped
  // result from sliding out from under the finger onto the backdrop (bug B).
  // This fn is already invoked on input / focus / blur / selectAsset /
  // clearSelectedAsset, so the attribute tracks the real search state. Pure
  // layout signal — no search/ranking/pricing/selection logic is touched.
  try {
    const _sheet = document.querySelector('#modalOverlay .modal');
    if (_sheet) {
      const _sugOpen = !!(assetSuggestionsEl && assetSuggestionsEl.classList.contains('open'));
      _sheet.dataset.assetFlow = hasChip ? 'form' : ((hasQuery || _sugOpen) ? 'search' : 'idle');
    }
  } catch (_) {}
}
if (searchInput) {
  searchInput.addEventListener('input', _updateSearchEmptyHint);
  searchInput.addEventListener('focus', _updateSearchEmptyHint);
  searchInput.addEventListener('blur',  _updateSearchEmptyHint);
}

// Close dropdown on outside click
document.addEventListener('click', e => {
  if (!e.target.closest('#searchWrap')) closeSuggestions();
}, true);

document.addEventListener('click', trackInteraction);

// Logo → home. AURIX-DASHBOARD-PREMIUM-POLISH-1 (#7): the AURIX logo is the
// global "Home" from ANY internal state (category, asset detail, market,
// metrics, workspace, an open overlay/modal/menu). It closes every transient
// surface and then lands on a clean dashboard. The dashboard sub-states
// (activeCategory / activeAssetId) are cleared by _applyTab('home') below.
document.addEventListener('click', (e) => {
  const logo = e.target.closest('#logoHome');
  if (!logo) return;
  try { if (typeof closeModal        === 'function') closeModal(); }        catch (_) {}
  try { if (typeof closeGlobalSearch === 'function') closeGlobalSearch(); } catch (_) {}
  try { if (typeof closeAssetManage  === 'function') closeAssetManage(); }  catch (_) {}
  try { if (typeof closeSuggestions  === 'function') closeSuggestions(); }  catch (_) {}
  try { if (typeof _closeAdsMenu     === 'function') _closeAdsMenu(); }     catch (_) {}
  if (typeof switchTab === 'function') switchTab('home');
});

// ── Modal ──────────────────────────────────────────────────

// AURIX-METALS-ADD-SHEET-FIX — supported metals for the "+ Añadir metal" picker.
// EXTENSIBLE registry: add an entry here once a metal's pricing is wired and it
// will appear in the sheet automatically (no other change needed). Copper
// (XCU / HG=F) is intentionally omitted for now — api/prices/snapshot.js has no
// HG=F spot proxy, so it would be an unpriceable holding; add it when wired.
//   mode 'gold'  → the premium physical-gold flow (weight + purity).
//   mode 'asset' → the standard quantity + price flow (e.g. silver via SI=F).
const _AURIX_METAL_ADD = [
  { key: 'gold',   mode: 'gold',  icon: '◉', asset: { ticker: 'XAU', name: 'Gold',   type: 'metal', marketSymbol: 'GC=F' } },
  { key: 'silver', mode: 'asset', icon: '◍', asset: { ticker: 'XAG', name: 'Silver', type: 'metal', marketSymbol: 'SI=F' } },
];
function _aurixRenderMetalPicker() {
  const wrap = document.getElementById('addV2MetalOptions');
  if (!wrap) return;
  wrap.innerHTML = _AURIX_METAL_ADD.map(m => `
    <button type="button" class="add-v2-card" data-metal-pick="${escHtml(m.key)}">
      <span class="add-v2-icon add-v2-icon--metal">${aurixMetalIconSvg(m.key === 'silver' ? 'silver' : 'gold', 'bullion')}</span>
      <span class="add-v2-text">
        <span class="add-v2-title">${escHtml(t('metalPick_' + m.key + '_title'))}</span>
        <span class="add-v2-sub">${escHtml(t('metalPick_' + m.key + '_sub'))}</span>
      </span>
      <span class="add-v2-chevron" aria-hidden="true">›</span>
    </button>`).join('');
}
// Open the concrete add flow for a chosen metal. Gold → premium gold flow; other
// metals → standard asset flow with the metal pre-selected via the canonical
// selectAsset pipeline (so pricing/quantity behave exactly as a searched pick).
function _aurixMetalPick(key) {
  const m = _AURIX_METAL_ADD.find(x => x.key === key);
  if (!m) return;
  _modalContext = (m.mode === 'gold') ? 'gold' : 'asset';
  _modalAssetFilterContext = 'metal';
  if (typeof _addV2SetMode === 'function') _addV2SetMode(m.mode === 'gold' ? 'gold' : 'asset');
  if (typeof _addV2Activate === 'function') _addV2Activate('form');
  setTimeout(() => {
    try { if (typeof selectAsset === 'function') selectAsset(Object.assign({}, m.asset)); } catch (_) {}
  }, 30);
}

// Opens the add-asset modal pre-filtered to the given category type.
// Reuses openModal() then programmatically clicks the matching filter button.
// ADD-V2.1: skips the type picker — contextual entry points already
// know which type the user is adding.
// ADD-V2.2: maps the category type onto the right contextual mode so
// the Step-2 chrome matches (RE → real_estate mode, anything else →
// asset mode with quick picks).
// CAT-CONTEXT-1: the user already chose the category — opening the
// modal must inherit that decision and bypass any generic discovery
// surface. Metal lands directly on the gold flow (XAU pre-selected);
// real_estate lands on the property form; crypto/stock/etf land on the
// asset flow with the matching filter already engaged and the placeholder
// + quick picks tuned to that intent. Also publishes the live filter
// context so other surfaces (intelligence, debug) can read it.
function openContextualModal(type) {
  openModal({ skipPicker: true });
  // Real estate is its own flow — no asset search, no filter button.
  if (type === 'real_estate') {
    _modalContext = 'real_estate';
    _modalAssetFilterContext = 'real_estate';
    if (typeof _addV2SetMode === 'function') _addV2SetMode('real_estate');
    try { if (typeof enterRealEstateMode === 'function') enterRealEstateMode(); } catch (_) {}
    return;
  }
  // AURIX-METALS-ADD-SHEET-FIX — "+ Añadir metal" must let the user CHOOSE the
  // metal, not jump straight to gold. Open the metal picker sheet (Oro / Plata,
  // from the metals registry). Each option then opens its concrete add flow.
  if (type === 'metal') {
    _modalContext = 'metal-picker';
    _modalAssetFilterContext = 'metal';
    if (typeof _aurixRenderMetalPicker === 'function') _aurixRenderMetalPicker();
    if (typeof _addV2Activate === 'function') _addV2Activate('metal-picker');
    return;
  }
  // Financial assets — keep the asset surface, just lock the filter so
  // crypto means crypto, stocks means stocks, etc.
  const filterKey = { crypto: 'crypto', stock: 'stock', etf: 'etf', fund: 'etf' }[type];
  // HOTFIX ADD-FROM-CATEGORY-PARITY — este camino se había quedado atrás. SPEC 59 ya identificó
  // que sintetizar `btn.click()` sobre la pestaña de filtro enruta por el handler del filtro, que
  // termina en `showDefaultSuggestions()` y ABRE el panel de sugerencias sin que el usuario haya
  // escrito; lo corrigió en la ruta del picker in-modal, pero `openContextualModal` —la entrada
  // "+ Añadir cripto" desde una categoría— conservó el clic antiguo. De ahí que el modal se abra
  // con una lista desplegada sobre la card premium, que el estado inicial no coincida con el del
  // Dashboard y que, al enfocar, el teclado encuentre la geometría del panel abierto en lugar de
  // la del estado de reposo. Se replica AQUÍ el tratamiento de SPEC 59, sin nueva lógica:
  //   activeSearchFilter primero (SPEC 60) → refresco de Recientes/Populares → resaltado de la
  //   pestaña y placeholder, SIN clic sintético y por tanto sin abrir el panel.
  // Y se invoca el reset que el picker sí hacía (SPEC 45 STATE ISOLATION), para que consulta,
  // selección y sugerencias de la sesión anterior no sobrevivan a la reapertura.
  try { if (typeof _addV2ResetForCategory === 'function') _addV2ResetForCategory(); } catch (_) {}
  if (typeof _addV2SetMode === 'function') _addV2SetMode('asset');
  try { if (typeof _addV2SetCategoryHeader === 'function') _addV2SetCategoryHeader(type); } catch (_) {}   // SPEC 45 — per-category header
  _modalContext = 'asset';
  _modalAssetFilterContext = filterKey || null;
  try { activeSearchFilter = filterKey || 'all'; } catch (_) {}                                   // SPEC 60 — antes del refresco
  try { if (typeof _addV42UpdateFilterAttr === 'function') _addV42UpdateFilterAttr(filterKey || 'all'); } catch (_) {}
  if (typeof _addV2RefreshQuick === 'function') _addV2RefreshQuick();
  try { if (typeof _updateSearchEmptyHint === 'function') _updateSearchEmptyHint(); } catch (_) {}
  if (filterKey) {
    try { document.querySelectorAll('.filter-btn').forEach(b => b.classList.toggle('active', b.dataset.filter === filterKey)); } catch (_) {}
    try { if (typeof searchInput !== 'undefined' && searchInput) searchInput.placeholder = T[lang].searchPH[filterKey] || T[lang].searchPH.all; } catch (_) {}
  }
}

// ── ISIN / Manual mode helpers ──────────────────────────────
function detectTypeFromISIN(isin) {
  const cc = isin.slice(0, 2).toUpperCase();
  if (cc === 'IE' || cc === 'LU') return 'etf';           // fund domiciles
  if (['US', 'CA', 'GB', 'DE', 'FR', 'ES', 'IT',
       'NL', 'CH', 'JP', 'AU', 'SE', 'DK', 'NO'].includes(cc)) return 'stock';
  return 'other';
}

function enterManualMode(isin, prefill = {}) {
  isManualMode         = true;
  manualAssetType      = prefill.type     || detectTypeFromISIN(isin);
  manualCurrency       = prefill.currency || 'USD';
  manualPendingSymbol  = prefill.symbol   || null;
  manualPendingCoinId  = prefill.coinId   || null;

  // Hide search UI
  searchInputWrapEl.style.display = 'none';
  if (searchFiltersEl) searchFiltersEl.style.display = 'none';
  clearSelectedAsset();
  closeSuggestions();
  setLookupStatus('');

  // Show manual fields
  const mf = document.getElementById('manualFields');
  if (mf) mf.style.display = '';

  // Auto-fill name if resolved
  const nameEl = document.getElementById('manualName');
  if (nameEl && prefill.name) nameEl.value = prefill.name;

  // Activate detected/resolved type
  document.querySelectorAll('#manualTypeToggle [data-mtype]').forEach(btn =>
    btn.classList.toggle('active', btn.dataset.mtype === manualAssetType));

  // Activate currency
  document.querySelectorAll('#manualCurrToggle [data-mcurr]').forEach(btn =>
    btn.classList.toggle('active', btn.dataset.mcurr === manualCurrency));

  // Show qty + preview + submit
  if (qtyLabelEl) qtyLabelEl.textContent = t('qty');
  qtyGroup.style.display      = '';
  formPreviewEl.style.display = '';
  btnSubmitEl.style.display   = '';

  // Auto-fill price if resolved (optional — user can override)
  if (prefill.price != null && prefill.price > 0) {
    const priceEl = document.getElementById('manualPrice');
    if (priceEl) {
      priceEl.value = prefill.price < 100
        ? prefill.price.toFixed(4)
        : prefill.price.toFixed(2);
      updatePreview();
    }
  }

  // Focus: if name was auto-filled, go straight to quantity
  setTimeout(() => {
    if (prefill.name) qtyInput.focus();
    else nameEl?.focus();
  }, 50);
}

function exitManualMode() {
  isManualMode        = false;
  manualPendingSymbol = null;
  manualPendingCoinId = null;
  const mf = document.getElementById('manualFields');
  if (mf) mf.style.display = 'none';
  searchInputWrapEl.style.display = '';
  if (searchFiltersEl) searchFiltersEl.style.display = '';
  qtyGroup.style.display      = 'none';
  formPreviewEl.style.display = 'none';
  btnSubmitEl.style.display   = 'none';
  const isinStatus = document.getElementById('isinStatus');
  if (isinStatus) isinStatus.textContent = '';
}

function resetISINInput() {
  // Cancel any in-flight lookup
  if (isinLookupAbortCtrl) { isinLookupAbortCtrl.abort(); isinLookupAbortCtrl = null; }
  const isinInput  = document.getElementById('isinInput');
  const isinStatus = document.getElementById('isinStatus');
  if (isinInput)  { isinInput.value = ''; }
  if (isinStatus) { isinStatus.textContent = ''; isinStatus.className = 'isin-status'; }
  if (isManualMode) exitManualMode();
}

// AURIX-ACTIVATION-2: tracked across openModal / closeModal so the
// header copy and the post-save toast both know whether the current
// modal session is the user's first ever asset.
let _firstAssetMode = false;

function _applyFirstAssetModalCopy(firstMode) {
  // Title swap — h3 inside the modal header. The HTML still carries
  // `data-i18n="modalAddTitle"`, so the next applyI18n() pass would
  // overwrite this; that's fine because applyI18n only fires on
  // language switches (not on modal open) and modal closes clear the
  // mode anyway. If applyI18n races us, the user simply sees the
  // generic title — never a broken state.
  const modalTitle = document.querySelector('#modalOverlay .modal-header h3');
  const subEl      = document.getElementById('addV2HeaderSub');
  if (firstMode) {
    if (modalTitle) modalTitle.textContent = t('modalAddTitleFirst');
    if (subEl) {
      subEl.textContent = t('modalAddSubFirst');
      subEl.hidden = false;
    }
  } else {
    if (modalTitle) modalTitle.textContent = t('modalAddTitle');
    if (subEl) {
      subEl.textContent = '';
      subEl.hidden = true;
    }
  }
}

// ── ADD-ASSET-MOBILE-INTERACTION · FIX 3 — visual-viewport height publisher ──────────────
// PROBLEM (owner: styles.css `.modal-overlay > .modal { max-height: calc(100dvh - …) }`).
// iOS Safari does NOT shrink the layout viewport — nor `dvh` — when the software keyboard
// opens; only `window.visualViewport` reflects it. So the Add Asset sheet keeps measuring the
// FULL screen while the keyboard covers its lower half: SPEC 63's top-anchor kept the header
// and Search reachable, but Results still extend underneath the keyboard and the tail of the
// list cannot be reached. No pure-CSS expression can know the keyboard's height, so the one
// missing input is published here as a custom property and consumed by ONE mobile CSS rule.
//
// Deliberately NOT wired into _onAurixViewportChange: that owner is debounced 200 ms and
// rebuilds the charts (initMobileCharts/updateChart) — reusing it would drag the Chart Engine
// into a keyboard event. This listens only to visualViewport, which that owner ignores.
//
// visualViewport is a standard browser API (already probed in the capability report), not a
// dependency, and it is feature-detected: where it is absent NOTHING is written and the CSS
// falls back to the existing 100dvh rule (unchanged behaviour). Android, which usually DOES
// resize the layout viewport, simply reports no meaningful delta and stays on the same path.
// Writes only a length + a boolean attribute: no layout is read back, no scroll is forced, no
// element is moved, and on keyboard close both are cleared so the resting layout is restored
// byte-for-byte. Desktop is excluded by the media query that consumes it.
if (typeof window !== 'undefined' && !window.__AURIX_VVH_LISTENER__) {
  window.__AURIX_VVH_LISTENER__ = true;
  const _vv = window.visualViewport || null;
  if (_vv) {
    // Threshold: a keyboard occupies far more than any browser-chrome collapse (address bar
    // ~60–110 px). 120 px keeps chrome changes from ever being mistaken for a keyboard.
    const _KB_MIN_DELTA = 120;
    let _kbRaf = 0;
    const _syncVv = () => {
      if (_kbRaf) return;                                   // coalesce bursts into one write per frame
      _kbRaf = requestAnimationFrame(() => {
        _kbRaf = 0;
        try {
          const de = document.documentElement;
          if (!de) return;
          const open = (window.innerHeight - _vv.height) > _KB_MIN_DELTA;
          if (open) {
            de.style.setProperty('--aurix-vvh', _vv.height + 'px');
            de.setAttribute('data-aurix-kb', 'open');
          } else {
            de.removeAttribute('data-aurix-kb');
            de.style.removeProperty('--aurix-vvh');          // exact restore — no residual cap
          }
        } catch (_) {}
      });
    };
    try {
      _vv.addEventListener('resize', _syncVv, { passive: true });
      _vv.addEventListener('scroll', _syncVv, { passive: true });   // iOS shifts the visual viewport on focus
    } catch (_) {}
  }
}

function openModal(opts) {
  // ADD-V2.1: optional Step-1 type picker. Default = show picker.
  // Internal callers that need to skip the picker (edit-RE, category
  // contextual entry points, etc.) pass { skipPicker: true } so they
  // land directly in the existing form. No submit logic touched.
  const skipPicker = !!(opts && opts.skipPicker);
  // ADD-FLOW-ARCH-1: claim asset context and tear down any in-flight
  // liquidity flow so state from one intent can never bleed into the
  // other (e.g. user opens liquidity, closes mid-input, opens asset).
  _modalContext = 'asset';
  // WL.2: clear any location/custodian left from a previous add so it never
  // bleeds into the next asset. Pre-fill on edit is handled at the call site.
  try { _wlResetLocationForm(); } catch (_) {}
  try {
    if (typeof liquidityOverlay !== 'undefined' && liquidityOverlay &&
        liquidityOverlay.classList.contains('open')) {
      closeLiquidityModal();
    }
  } catch (_) {}
  const _modalEl = document.querySelector('#modalOverlay .modal');
  if (_modalEl) {
    _modalEl.dataset.step       = skipPicker ? 'form' : 'picker';
    _modalEl.dataset.fromPicker = skipPicker ? '0'    : '1';
  }
  // AURIX-ACTIVATION-2: arm first-asset mode based on the canonical
  // source of truth (assets.length). Applied once per open — the post-
  // save toast still gates on the 0→1+ transition independently so a
  // user editing an existing asset never triggers the success copy.
  _firstAssetMode = (Array.isArray(assets) && assets.length === 0);
  _applyFirstAssetModalCopy(_firstAssetMode);
  assetForm.reset();
  previewTotal.textContent = formatBase(0);

  // Reset state
  selectedDbAsset      = null;
  pendingCoinId        = null;
  pendingMarketSymbol  = null;
  pendingPrice         = null;
  pendingCurrency      = null;
  pendingIsManualNav   = false;
  pendingKarat         = 18;
  pendingGoldUnit      = 'g';
  pendingResaleMargin  = 8;
  // ADD-V4.1: reset valuation mode to canonical spot on every open.
  if (typeof pendingGoldValuationMode !== 'undefined') pendingGoldValuationMode = 'spot';
  // GOLD-UX-PREMIUM-REBUILD — reset the type step + scenario
  // disclosure so each re-open lands cleanly on STEP 1 with no leaked
  // selection state from the previous session.
  const _goldSecReset = document.getElementById('goldSection');
  if (_goldSecReset) {
    _goldSecReset.dataset.goldType = '';
    _goldSecReset.dataset.goldQty  = '0';
    _goldSecReset.querySelectorAll('.gold-type-chip').forEach(b => b.classList.remove('is-active'));
  }
  // Collapse the "Ajustar escenario de venta" disclosure so the user
  // always lands on the single clean spot estimate.
  const _goldAdjPanelReset = document.getElementById('goldAdjustPanel');
  if (_goldAdjPanelReset) _goldAdjPanelReset.hidden = true;
  const _goldAdjToggleReset = document.getElementById('goldBuyerToggle');
  if (_goldAdjToggleReset) {
    _goldAdjToggleReset.setAttribute('aria-expanded', 'false');
    const _adjIcon = _goldAdjToggleReset.querySelector('.gold-more-icon');
    if (_adjIcon) _adjIcon.textContent = '›';
  }
  // Clear the CTA secondary line + the count-up tween state so the
  // next valid estimate animates from zero.
  const _goldCtaSumReset = document.getElementById('goldCtaSummary');
  if (_goldCtaSumReset) { _goldCtaSumReset.hidden = true; _goldCtaSumReset.textContent = ''; }
  _goldEstLast = 0;
  currentSuggestions   = [];
  renderedSuggestions  = [];
  activeSearchFilter   = 'all';
  focusedSuggIdx       = -1;
  // ADD-V4.2 hotfix: reset the modal's filter attribute every open so
  // a previous session's filter never leaks into the ISIN visibility.
  if (typeof _addV42UpdateFilterAttr === 'function') _addV42UpdateFilterAttr('all');
  if (karatGroupEl)    karatGroupEl.style.display    = 'none';
  if (goldUnitGroupEl) goldUnitGroupEl.style.display = 'none';
  const _gsEl = document.getElementById('goldSection');
  if (_gsEl) _gsEl.style.display = 'none';
  _renderGoldSpotLine(null);
  // ADD-V4.1: restore qty input to its original parent so reopening
  // the modal in a non-gold flow doesn't strand it inside a hidden
  // gold section.
  if (typeof _addV4RestoreQty === 'function') _addV4RestoreQty();
  if (qtyLabelEl)      qtyLabelEl.textContent        = t('qty');
  isRealEstateMode  = false;
  isManualMode      = false;
  rePendingCurrency = 'EUR';
  rePendingRent     = 0;
  reEditTargetId    = null;
  // Reset ISIN + manual fields
  resetISINInput();
  const isinOrWrap = document.getElementById('isinOrWrap');
  if (isinOrWrap) isinOrWrap.style.display = '';
  const manualFields = document.getElementById('manualFields');
  if (manualFields) manualFields.style.display = 'none';
  const reNameGroupEl = document.getElementById('reNameGroup');
  const reCurrGroupEl = document.getElementById('reCurrGroup');
  const reRentGroupEl = document.getElementById('reRentGroup');
  if (reNameGroupEl) reNameGroupEl.style.display = 'none';
  if (reCurrGroupEl) reCurrGroupEl.style.display = 'none';
  if (reRentGroupEl) reRentGroupEl.style.display = 'none';

  searchInput.value               = '';
  searchClearBtn.style.display    = 'none';
  selectedChipEl.style.display    = 'none';
  searchInputWrapEl.style.display = '';
  chipPriceEl.textContent         = '';
  qtyGroup.style.display          = 'none';
  formPreviewEl.style.display     = 'none';
  btnSubmitEl.style.display       = 'none';

  closeSuggestions();
  setLookupStatus('');

  if (searchFiltersEl) searchFiltersEl.style.display = '';
  filterBtns.forEach(b => b.classList.toggle('active', b.dataset.filter === 'all'));

  searchInput.placeholder = T[lang].searchPH.all;
  // AURIX-ACTIVATION-2: re-apply the modal header (title + subtitle).
  // Edit mode and a previous open may have left either in a stale
  // state, so the helper writes the right copy based on _firstAssetMode.
  _applyFirstAssetModalCopy(_firstAssetMode);
  // Collapse the mobile ISIN section + refresh the empty hint on every open.
  if (typeof _setIsinRevealed === 'function') _setIsinRevealed(false);
  if (typeof _updateSearchEmptyHint === 'function') _updateSearchEmptyHint();
  modalOverlay.classList.add('open');
  document.body.classList.add('modal-open');
  suppressFocusDefaults = true;
  // ── ADD-ASSET-MOBILE-INTERACTION · FIX 2 — clean initial state on mobile ──────────────
  // SPEC 59/60 removed the synthetic click that opened the suggestion panel from the
  // CATEGORY entry point (openContextualModal), but openContextualModal calls openModal
  // FIRST and these two timers fire 50/70 ms LATER — i.e. AFTER that reset — so they put
  // the forced focus (keyboard) and the open dropdown straight back. That is why "Add
  // crypto" still opened with the list deployed and the keyboard up: the fix was applied
  // one layer above its actual owner. This IS the owner.
  // On mobile the sheet must open at rest — Search + Recent + Popular, which
  // _addV2RefreshQuick already rendered — and reveal results only once the user taps or
  // types (the existing input/focus handlers do that, unchanged). Desktop keeps the
  // previous behaviour byte-for-byte: there is no keyboard to displace the layout and the
  // curated defaults are what stops the wide form looking blank.
  // Mobile: no programmatic focus, no auto-suggestions. Leave the panel closed and release the
  // focus-suppression latch so the user's OWN tap on Search behaves exactly as a normal focus
  // (which is what opens the panel). Returning here leaves the two desktop timers below
  // untouched — they are the certified behaviour and still run verbatim on desktop.
  if ((typeof window !== 'undefined') && window.innerWidth <= 768) {
    try { if (assetSuggestionsEl) assetSuggestionsEl.classList.remove('open'); } catch (_) {}
    // Not opening the keyboard is not enough: closeModal() never blurs, so a sheet closed WITH
    // the keyboard up leaves searchInput as document.activeElement and the next open inherits
    // both the focus and the keyboard (reproduced on the stock/etf re-entry in the live probe).
    // Blur whatever inside the sheet still holds focus so every mobile open starts at rest.
    try {
      const _ae = document.activeElement;
      if (_ae && typeof _ae.blur === 'function' && _ae !== document.body) _ae.blur();
    } catch (_) {}
    suppressFocusDefaults = false;
    return;
  }
  setTimeout(() => searchInput.focus(), 50);
  // ADD-ASSET-DISCOVERY-1: surface curated defaults right away so the
  // form never appears blank — works for skipPicker paths AND for the
  // picker → "Activo" transition (the suggestions stay rendered while
  // hidden behind the picker, then reveal naturally on step change).
  setTimeout(() => {
    if (!searchInput.value.trim()) showDefaultSuggestions();
  }, 70);
}

function closeModal() {
  modalOverlay.classList.remove('open');
  document.body.classList.remove('modal-open');
  clearTimeout(searchDebounceTimer);
  clearTimeout(searchSpinnerTimer);
  if (searchAbortCtrl) { searchAbortCtrl.abort(); searchAbortCtrl = null; }
  closeSuggestions();
  // AURIX-ACTIVATION-2: clear the first-asset flag and restore the
  // generic header copy so the next open starts from a clean state
  // even when re-opened with assets still empty (the flag is re-armed
  // inside openModal anyway).
  _firstAssetMode = false;
  _applyFirstAssetModalCopy(false);
  // ADD-FLOW-ARCH-1: release the asset context only if it still owns
  // it (an in-flight openLiquidityModal already overrode it).
  // CAT-CONTEXT-1: 'gold' and 'real_estate' are also asset-modal flows,
  // so they get released here too. Clear the assetFilterContext on every
  // close so the next session never inherits stale filter state.
  if (_modalContext === 'asset' || _modalContext === 'gold' || _modalContext === 'real_estate') {
    _modalContext = null;
  }
  _modalAssetFilterContext = null;
}

// ADD-V4.2 hotfix: ISIN advanced is only meaningful for traditional
// securities (stocks, ETFs, funds). Mirror the active filter on the
// modal so the CSS can hide the toggle and collapse the disclosure
// for crypto / metal / RE without touching the search backend.
function _addV42UpdateFilterAttr(filter) {
  const modal = document.querySelector('#modalOverlay .modal');
  if (modal) modal.dataset.searchFilter = filter || 'all';
  // SPEC CATEGORY-CONTEXT — when the modal was opened FROM a specific category
  // (_modalAssetFilterContext = stock/crypto/etf/fund/metal), lock it: the category
  // tabs are hidden (CSS) and the category stays fixed. Opened from All (null) → tabs
  // shown + switchable. real_estate has its own form (no tabs) so it's not "locked".
  if (modal) {
    const ctx = (typeof _modalAssetFilterContext === 'string') ? _modalAssetFilterContext : null;
    modal.dataset.categoryLocked = (ctx && ctx !== 'real_estate') ? '1' : '0';
  }
  const ISIN_OK = new Set(['all', 'stock', 'etf']);
  if (!ISIN_OK.has(filter) && typeof _setIsinRevealed === 'function') {
    // If the user had the disclosure open and switches to a filter
    // where ISIN doesn't apply, collapse it cleanly.
    _setIsinRevealed(false);
  }
}

// ── Filter bar ─────────────────────────────────────────────
filterBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    const newFilter = btn.dataset.filter;
    filterBtns.forEach(b => b.classList.toggle('active', b === btn));
    focusedSuggIdx = -1;

    // Real estate: switch to manual form — no live search needed
    if (newFilter === 'real_estate') {
      activeSearchFilter = 'real_estate';
      _addV42UpdateFilterAttr('real_estate');
      enterRealEstateMode();
      return;
    }

    // Switching away from RE mode: restore search UI (enterSearchMode already clears the selection).
    if (isRealEstateMode) enterSearchMode();
    // SPEC 45 STATE ISOLATION — switching the category filter clears the previous category's selection +
    // preview so it can never leak (e.g. a crypto pick surviving into the Stocks filter). The typed query,
    // if any, is intentionally kept below for a live re-search under the new filter.
    else { try { if (typeof clearSelectedAsset === 'function') clearSelectedAsset(); } catch (_) {} }

    activeSearchFilter = newFilter;
    _addV42UpdateFilterAttr(newFilter);

    // Update placeholder
    searchInput.placeholder = T[lang].searchPH[activeSearchFilter] || T[lang].searchPH.all;

    // ADD-FLOW-ARCHITECTURE-2: re-render the popular cards so they
    // mirror the new intent (Crypto tab → BTC/ETH/SOL…, Stocks tab →
    // AAPL/MSFT/NVDA…). No fetch, just a DOM swap from DEFAULTS.
    if (typeof _addV2RefreshQuick === 'function') _addV2RefreshQuick();

    // Cancel any pending search
    clearTimeout(searchDebounceTimer);
    clearTimeout(searchSpinnerTimer);
    if (searchAbortCtrl) { searchAbortCtrl.abort(); searchAbortCtrl = null; }

    const q = searchInput.value.trim();
    if (!q) {
      // ADD-ASSET-DISCOVERY-1: tab tap with empty query → show the
      // curated set immediately. No more blank surface until the
      // user searches; works for every filter including 'all'.
      showDefaultSuggestions();
      return;
    }

    // Re-run search with new filter. Same delayed-spinner contract as
    // the input handler above — local results are painted instantly
    // with loading=false, the 150 ms spinner only fires if the API
    // is genuinely slow.
    const localResults = getLocalResults(q, activeSearchFilter);
    currentSuggestions = localResults;
    if (localResults.length > 0 && activeSearchFilter !== 'all') {
      renderSuggestions(localResults, q, false);
    }

    if (activeSearchFilter === 'metal') return;

    searchDebounceTimer = setTimeout(async () => {
      searchAbortCtrl = new AbortController();
      const { signal } = searchAbortCtrl;

      searchSpinnerTimer = setTimeout(() => {
        if (signal.aborted) return;
        if (searchInput.value.trim() !== q) return;
        renderSuggestions(currentSuggestions, q, true);
      }, 150);

      try {
        const results = await searchByFilter(q, activeSearchFilter, signal);
        clearTimeout(searchSpinnerTimer);
        if (signal.aborted || searchInput.value.trim() !== q) return;
        if (results && results.length) currentSuggestions = results;
        renderSuggestions(currentSuggestions, q, false);
      } catch (err) {
        clearTimeout(searchSpinnerTimer);
        if (err.name === 'AbortError') return;
        if (searchInput.value.trim() !== q) return;
        renderSuggestions(currentSuggestions, q, false);
      }
    }, 300);
  });
});

// ── ISIN input: real-time validation + async API lookup ─────
const isinInputEl = document.getElementById('isinInput');
if (isinInputEl) {
  isinInputEl.addEventListener('input', () => {
    // Force uppercase + strip non-alphanumeric
    const raw = isinInputEl.value.toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (isinInputEl.value !== raw) isinInputEl.value = raw;

    // Cancel any in-flight lookup whenever the user types
    if (isinLookupAbortCtrl) { isinLookupAbortCtrl.abort(); isinLookupAbortCtrl = null; }

    const statusEl = document.getElementById('isinStatus');
    const n = raw.length;

    if (n === 0) {
      if (isManualMode) exitManualMode();
      if (statusEl) { statusEl.textContent = ''; statusEl.className = 'isin-status'; }
      return;
    }

    if (n < 12) {
      if (isManualMode) exitManualMode();
      if (statusEl) {
        statusEl.textContent = t('isinHint')(n);
        statusEl.className   = 'isin-status isin-status--hint';
      }
      return;
    }

    // 12 chars — validate format: 2 letters + 9 alphanumeric + 1 digit
    const valid = /^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(raw);
    if (!valid) {
      if (isManualMode) exitManualMode();
      if (statusEl) {
        statusEl.textContent = t('isinError');
        statusEl.className   = 'isin-status isin-status--error';
      }
      isinInputEl.classList.add('aes-shake');
      setTimeout(() => isinInputEl.classList.remove('aes-shake'), 450);
      return;
    }

    // Valid ISIN → show loading, then look up asynchronously
    if (statusEl) {
      statusEl.textContent = t('isinLooking');
      statusEl.className   = 'isin-status isin-status--loading';
    }
    if (isManualMode) exitManualMode(); // reset if user edited to a new ISIN

    isinLookupAbortCtrl = new AbortController();
    const { signal }    = isinLookupAbortCtrl;
    const isinSnap      = raw;

    (async () => {
      try {
        // Step 1: ISIN → ticker/name/type via OpenFIGI
        const figiResult = await getAssetFromISIN(isinSnap, signal);
        if (signal.aborted) return;

        const prefill = {};
        if (figiResult) {
          prefill.type   = figiResult.type;
          prefill.name   = figiResult.name;
          prefill.symbol = figiResult.symbol;

          // Step 2: fetch current price using the resolved symbol
          if (figiResult.type === 'crypto') {
            const cp = await fetchCryptoPrice(figiResult.symbol);
            if (!signal.aborted && cp) { prefill.price = cp.price; prefill.coinId = cp.coinId; }
          } else if (figiResult.symbol) {
            // MC-6D: surface currency too so enterManualMode pre-selects
            // the correct currency button (its prefill.currency consumer
            // already exists at app.js manualCurrency = prefill.currency).
            const quote = await resolveSymbolQuote(figiResult.symbol);
            if (!signal.aborted && quote) {
              prefill.price = quote.price;
              if (quote.currency) prefill.currency = quote.currency;
            }
          }
        }
        if (signal.aborted) return;

        // Step 3: update status + enter manual mode with prefilled data
        if (statusEl) {
          if (figiResult?.name) {
            statusEl.textContent = t('isinFound')(figiResult.name);
            statusEl.className   = 'isin-status isin-status--ok';
          } else {
            statusEl.textContent = t('isinNotFound');
            statusEl.className   = 'isin-status isin-status--warn';
          }
        }
        enterManualMode(isinSnap, prefill);

      } catch (err) {
        if (err.name === 'AbortError' || signal.aborted) return;
        if (statusEl) {
          statusEl.textContent = t('isinLookupError');
          statusEl.className   = 'isin-status isin-status--warn';
        }
        // Fallback: enter manual mode with heuristic type detection only
        enterManualMode(isinSnap);
      }
    })();
  });
}

// ── Manual type toggle ─────────────────────────────────────
document.getElementById('manualTypeToggle')?.addEventListener('click', e => {
  const btn = e.target.closest('[data-mtype]');
  if (!btn) return;
  manualAssetType = btn.dataset.mtype;
  document.querySelectorAll('#manualTypeToggle [data-mtype]').forEach(b =>
    b.classList.toggle('active', b === btn));
});

// ── Manual currency toggle ─────────────────────────────────
document.getElementById('manualCurrToggle')?.addEventListener('click', e => {
  const btn = e.target.closest('[data-mcurr]');
  if (!btn) return;
  manualCurrency = btn.dataset.mcurr;
  document.querySelectorAll('#manualCurrToggle [data-mcurr]').forEach(b =>
    b.classList.toggle('active', b === btn));
  updatePreview();
});

// ── Live Preview ───────────────────────────────────────────
function updatePreview() {
  const qty = parseLocalFloat(qtyInput.value) || 0;
  // Real estate: qty IS the value, already in rePendingCurrency
  if (isRealEstateMode) {
    previewTotal.textContent = formatDisplay(qty, rePendingCurrency);
    return;
  }
  // Manual ISIN mode: qty × manual price (if any), in selected manualCurrency
  if (isManualMode) {
    const price = parseLocalFloat(document.getElementById('manualPrice')?.value) || 0;
    previewTotal.textContent = formatDisplay(qty * price, manualCurrency);
    return;
  }
  const price = pendingPrice || 0;
  let value;
  let valueUnavail = false;
  if (selectedDbAsset?.ticker === 'XAU' && pendingKarat) {
    // GOLD-PRICE-1: when the live spot is unavailable, the estimate is
    // not meaningful. Render an explicit unavailable state instead of
    // ≈ 0 US$ so the user understands why the CTA is blocked.
    if (!Number.isFinite(price) || price <= 0) {
      _renderGoldSpotLine(null);
      const goldAmountEl = document.getElementById('goldSummaryAmount');
      if (goldAmountEl) goldAmountEl.textContent = '—';
      const goldSpotRefEl = document.getElementById('goldSummarySpotRef');
      if (goldSpotRefEl) { goldSpotRefEl.hidden = true; goldSpotRefEl.textContent = ''; }
      valueUnavail = true;
      value = 0;
    } else {
      // GOLD-1: physical gold preview uses the same formula as the
      // canonical assetNativeValue path so what the user sees here is
      // exactly what gets persisted and rendered on the dashboard.
      const grams = _goldGrams(qty, pendingGoldUnit);
      value = grams * _goldPurity(pendingKarat) * (price / OZ_TO_G);
      _renderGoldSpotLine(price);
      // GOLD-2: dual-value panel — spot stays canonical, resale is a
      // purely informational haircut on top.
      _renderGoldValuation(value);
    }
  } else {
    value = qty * price;
  }
  previewTotal.textContent = valueUnavail ? '—' : formatDisplay(value, 'USD');
  // ADD-V4.2: keep the desktop preview value in lockstep with the
  // inline preview text. Mobile ignores this element (display:none).
  if (typeof _addV4RenderPreview === 'function') _addV4RenderPreview();
  // GOLD-UX-2: refresh the gold-flow CTA gate every preview tick.
  if (typeof _updateGoldCtaState === 'function') _updateGoldCtaState();
}

// GOLD-UX-3: format the entered quantity for human display in CTA
// labels and the context line. Trims trailing zeros so "25.00" reads
// as "25", but keeps meaningful decimals like "0.5".
function _formatGoldQtyText(qty, unit) {
  if (!Number.isFinite(qty) || qty <= 0) return '';
  let s = String(qty);
  if (s.indexOf('.') !== -1) s = s.replace(/\.?0+$/, '');
  const unitLabel = unit === 'oz' ? 'oz' : (unit === 'kg' ? 'kg' : 'g');
  // Grams use no thin space (25g), troy ounce / kg use a thin one (2 oz).
  return unitLabel === 'g' ? `${s} g` : `${s} ${unitLabel}`;
}

// GOLD-UX-3: build the dynamic context line shown under the estimated
// value: "18K · 25 g · 75% pureza aprox." 24K reads as "pureza máxima".
function _buildGoldContextLine() {
  if (!selectedDbAsset || selectedDbAsset.ticker !== 'XAU') return '';
  const qty = parseLocalFloat(qtyInput.value);
  if (!Number.isFinite(qty) || qty <= 0) return '';
  const karat = pendingKarat | 0;
  if (!karat) return '';
  const qtyText = _formatGoldQtyText(qty, pendingGoldUnit);
  const purity  = (typeof _goldPurity === 'function') ? _goldPurity(karat) : 0;
  const purityText = (karat === 24)
    ? (t('gold_purity_max') || 'highest purity')
    : ((typeof t('gold_purity_approx') === 'function')
       ? t('gold_purity_approx')(Math.round(purity * 100))
       : `${Math.round(purity * 100)}%`);
  const fn = t('gold_summary_context');
  return (typeof fn === 'function') ? fn(`${karat}K`, qtyText, purityText) : '';
}

// GOLD-UX-3: soft count-up on the estimated-value figure so the
// number feels alive without flashing. ~320ms easeOutQuad, falls back
// to instant write under prefers-reduced-motion.
let _goldEstLast = 0;
let _goldEstRaf  = null;
// GOLD-UX-PREMIUM-REBUILD — the estimate is always indicative, so the
// amount renders with an ≈ prefix to signal that intent visually. The
// helper centralises the format so the animation tween and the static
// write paths share a single source of truth.
function _formatGoldEstimateText(usd) {
  return `≈ ${formatDisplay(usd, 'USD')}`;
}
function _animateGoldEstimate(targetUsd) {
  const el = document.getElementById('goldSummaryAmount');
  if (!el) return;
  const reduced = (typeof matchMedia === 'function')
    && matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduced || _goldEstLast === 0 || !Number.isFinite(_goldEstLast)) {
    _goldEstLast = targetUsd;
    el.textContent = _formatGoldEstimateText(targetUsd);
    return;
  }
  if (_goldEstRaf) cancelAnimationFrame(_goldEstRaf);
  const start = _goldEstLast;
  const end   = targetUsd;
  const dur   = 320;
  const t0    = performance.now();
  function easeOutQuad(p) { return 1 - (1 - p) * (1 - p); }
  (function step(now) {
    const p = Math.min((now - t0) / dur, 1);
    const v = start + (end - start) * easeOutQuad(p);
    el.textContent = _formatGoldEstimateText(v);
    if (p < 1) _goldEstRaf = requestAnimationFrame(step);
    else { _goldEstRaf = null; _goldEstLast = end; el.textContent = _formatGoldEstimateText(end); }
  })(t0);
}

// GOLD-UX-2: validate the physical gold entry form and mirror the
// result onto the sticky CTA. Required fields per the spec are:
// type (Joyería/Moneda/Lingote), karat, unit and quantity > 0.
function _isGoldFormValid() {
  if (!selectedDbAsset || selectedDbAsset.ticker !== 'XAU') return null;
  const section = document.getElementById('goldSection');
  if (!section) return null;
  const type     = section.dataset.goldType || '';
  const qty      = parseLocalFloat(qtyInput.value);
  const qtyValid = !isNaN(qty) && qty > 0;
  // GOLD-PRICE-1: a live spot price is now mandatory for the CTA. With
  // fetchGoldSpotPrice() returning null on failure, requiring it here
  // keeps the submit button disabled instead of allowing a stale
  // FALLBACK_PRICES['GC=F'] cost basis to be persisted.
  const priceValid = Number.isFinite(pendingPrice) && pendingPrice > 0;
  return {
    section,
    type,
    karat:    pendingKarat,
    unit:     pendingGoldUnit,
    qtyValid,
    priceValid,
    valid:    !!type && !!pendingKarat && !!pendingGoldUnit && qtyValid && priceValid,
  };
}

function _updateGoldCtaState() {
  const v = _isGoldFormValid();
  if (!v) return;
  // Reflect the qty validity on the section so CSS can reveal the
  // estimate card / scenario disclosure only when the user has entered
  // a valid amount.
  v.section.dataset.goldQty = v.qtyValid ? '1' : '0';
  // Context line under the estimated value — REBUILD format
  // "[qty] · [purity] · [purity %]".
  const ctxEl = document.getElementById('goldSummaryContext');
  if (ctxEl) ctxEl.textContent = _buildGoldContextLine();
  // GOLD-UX-PREMIUM-REBUILD — compact "1 g · ≈ 109 US$" line above the
  // CTA so the user always sees what they're about to add at a glance.
  // Reads the last animated estimate so currency formatting stays in
  // sync with the big amount.
  const ctaSummaryEl = document.getElementById('goldCtaSummary');
  if (ctaSummaryEl) {
    if (v.valid && _goldEstLast > 0) {
      const qty = parseLocalFloat(qtyInput.value);
      const qtyText = _formatGoldQtyText(qty, pendingGoldUnit);
      const valStr  = formatDisplay(_goldEstLast, 'USD');
      const fn      = t('gold_cta_secondary');
      ctaSummaryEl.textContent = (typeof fn === 'function')
        ? fn(qtyText, valStr)
        : `${qtyText} · ≈ ${valStr}`;
      ctaSummaryEl.hidden = false;
    } else {
      ctaSummaryEl.hidden = true;
      ctaSummaryEl.textContent = '';
    }
  }
  if (!btnSubmitEl) return;
  const enabled = v.valid;
  // AURIX-METALS-ADD-COIN-BUTTON-BUG — keep the gold CTA CLICKABLE even when the
  // form is incomplete (only the "incomplete" look is applied). A natively
  // `disabled` button swallows the click silently — that is exactly what made
  // the button feel dead for some types. Now an incomplete click triggers the
  // submit handler, which shows a specific toast instead of doing nothing.
  btnSubmitEl.disabled = false;
  btnSubmitEl.classList.toggle('btn-submit--disabled', !enabled);
  // REBUILD: CTA always reads "Añadir oro a cartera" once valid. The
  // qty-aware "Añadir 25 g de oro" variant is no longer used — the
  // secondary summary line above already surfaces qty + value.
  btnSubmitEl.textContent = enabled ? t('gold_cta_add') : t('gold_cta_complete');
}

// ADD-V4.1: gold market reference — small premium card above the
// purity/unit row. Same data source as before (pendingPrice = XAU/USD
// per troy ounce) so the figure follows the global currency toggle.
function _renderGoldSpotLine(spotPerOzUsd) {
  const el = document.getElementById('goldSpotLine');
  if (!el) return;
  if (!spotPerOzUsd || !Number.isFinite(spotPerOzUsd)) { el.textContent = '—'; return; }
  const perGram = spotPerOzUsd / OZ_TO_G;
  el.textContent = `${formatDisplay(perGram, 'USD')}/g · ${formatDisplay(spotPerOzUsd, 'USD')}/oz`;
}

// ADD-V4.1: one premium summary card that adapts to the chosen
// valuation mode. Spot stays the canonical metal math; resale is the
// existing spot × (1 - margin/100) — formula untouched. Buyer profile
// → margin mapping (5/8/15) preserves the persisted resaleMargin /
// resaleFactor fields so submit-time storage is unchanged.
let pendingGoldValuationMode = 'spot';  // 'spot' | 'resale'
function _renderGoldValuation(spotValueUsd) {
  const amountEl  = document.getElementById('goldSummaryAmount');
  const metaEl    = document.getElementById('goldSummaryMeta');
  const spotRefEl = document.getElementById('goldSummarySpotRef');
  const discEl    = document.getElementById('goldSummaryDisclaimer');
  if (!amountEl) return;
  const v = Number(spotValueUsd) || 0;
  const margin = Number(pendingResaleMargin) || 0;
  const factor = Math.max(0, Math.min(1, 1 - margin / 100));
  const isResale = pendingGoldValuationMode === 'resale';
  const shown = isResale ? v * factor : v;
  // GOLD-UX-3: animate the estimate with a short count-up tween so
  // the figure feels responsive when the user changes karat / unit
  // / qty. Falls back to instant write under prefers-reduced-motion.
  _animateGoldEstimate(shown);
  if (metaEl) metaEl.textContent = t(isResale ? 'gold_summary_meta_resale' : 'gold_summary_meta_spot');
  if (spotRefEl) {
    if (isResale && v > 0) {
      spotRefEl.hidden = false;
      const spotStr = formatDisplay(v, 'USD');
      spotRefEl.textContent = (typeof t('gold_summary_spot_ref') === 'function')
        ? t('gold_summary_spot_ref')(spotStr)
        : `Spot: ${spotStr}`;
    } else {
      spotRefEl.hidden = true;
      spotRefEl.textContent = '';
    }
  }
  if (discEl) discEl.hidden = !isResale;
}
qtyInput.addEventListener('input', updatePreview);
document.getElementById('manualPrice')?.addEventListener('input', updatePreview);

// ── Add Asset ──────────────────────────────────────────────
assetForm.addEventListener('submit', e => {
  e.preventDefault();
  // UN ENVÍO POR APERTURA. Al cerrarse, la hoja deja de recibir clics, pero el foco sigue
  // en su campo y un segundo Enter la volvía a enviar: un inmueble entraba dos veces.
  if (!modalOverlay.classList.contains('open')) return;

  // WL.2 (Fase 2 — Wealth Location): read the optional location/custodian once
  // so every add/buy/edit branch below can stamp it. null when left blank →
  // new assets persist no location, and a buy-more edit conserves the existing
  // asset.location instead of wiping it. Pure metadata; never affects valuation.
  const _newLoc = (typeof _wlReadLocationForm === 'function') ? _wlReadLocationForm() : null;

  // GOLD-UX-2: defensive guard. The CTA is disabled when the gold
  // flow is incomplete, but if a future tweak (or dev tools) enables
  // it, we still short-circuit here so the form can never persist a
  // half-filled gold asset. The shared qty/price checks below catch
  // every other branch.
  if (selectedDbAsset && selectedDbAsset.ticker === 'XAU') {
    // AURIX-METALS-ADD-COIN-BUTTON-BUG — the add flow must work for EVERY type
    // (jewelry / coin / bar) and must NEVER fail silently (spec #4/#5). Auto-recover
    // safe defaults, then — if still incomplete — tell the user exactly what's
    // missing (and re-fetch the spot price) instead of a dead button.
    if (typeof pendingGoldUnit === 'undefined' || !pendingGoldUnit) pendingGoldUnit = 'g';
    if (!pendingKarat) pendingKarat = 18;
    const gs = (typeof _isGoldFormValid === 'function') ? _isGoldFormValid() : null;
    if (gs && !gs.valid) {
      if (!gs.type) {
        try { _aurixShowToast((typeof lang !== 'undefined' && lang === 'es') ? 'Elige el tipo: joyería, moneda o lingote' : 'Choose a type: jewelry, coin or bar', { variant: 'error' }); } catch (_) {}
        try { document.getElementById('goldTypeRow')?.scrollIntoView({ block: 'center', behavior: 'smooth' }); } catch (_) {}
        return;
      }
      if (!gs.qtyValid) {
        try { _aurixShowToast((typeof lang !== 'undefined' && lang === 'es') ? 'Introduce una cantidad mayor que 0' : 'Enter a quantity greater than 0', { variant: 'error' }); } catch (_) {}
        try { qtyInput.focus(); } catch (_) {}
        return;
      }
      if (!gs.priceValid) {
        // Most likely transient cause: spot price not loaded yet → don't dead-end,
        // fetch it and let the user retry once it lands.
        try { _aurixShowToast((typeof lang !== 'undefined' && lang === 'es') ? 'Obteniendo el precio del oro… inténtalo de nuevo en un segundo' : 'Fetching the gold price… try again in a second', { variant: 'info' }); } catch (_) {}
        try { if (typeof fetchGoldSpotPrice === 'function') fetchGoldSpotPrice().then(p => { if (Number.isFinite(p) && p > 0) { pendingPrice = p; if (typeof updatePreview === 'function') updatePreview(); } }); } catch (_) {}
        return;
      }
      // Any other incomplete state — surface it, never silent.
      try { _aurixShowToast((typeof lang !== 'undefined' && lang === 'es') ? 'Completa los datos del metal para continuar' : 'Complete the metal details to continue', { variant: 'error' }); } catch (_) {}
      return;
    }
  }

  // ── Real estate branch: manual value entry, no live price ──
  if (isRealEstateMode) {
    const reNameInput = document.getElementById('reName');
    const name = (reNameInput?.value || '').trim();
    if (!name) { reNameInput?.focus(); return; }

    const value = parseLocalFloat(qtyInput.value);
    if (isNaN(value) || value <= 0) { qtyInput.focus(); return; }

    const rent = parseLocalFloat(document.getElementById('reRent')?.value) || 0;
    const ticker = name.replace(/[^a-zA-Z]/g, '').slice(0, 4).toUpperCase() || 'INMU';

    let reFlashId = reEditTargetId;
    if (reEditTargetId) {
      // Edit existing real estate asset
      const existing = assets.find(a => a.id === reEditTargetId);
      if (existing) {
        existing.name          = name;
        existing.ticker        = ticker;
        existing.qty           = value;
        existing.rent          = rent;
        existing.assetCurrency = rePendingCurrency;
        existing.costBasis     = value;
        if (_newLoc) existing.location = _newLoc;   // WL.2: conserve unless user set one
      }
    } else {
      reFlashId = Date.now().toString(36) + Math.random().toString(36).slice(2);
      assets.push({
        id:            reFlashId,
        name,
        ticker,
        type:          'real_estate',
        qty:           value,
        price:         1,                  // qty × price = value; price never changes
        coinId:        null,
        marketSymbol:  null,
        assetCurrency: rePendingCurrency,
        change24h:     null,
        prevPrice:     null,
        rent,
        costBasis:     value,
        location:      _newLoc,            // WL.2: optional Wealth Location metadata
      });
    }
    save();
    render(true);
    closeModal();
    _flashAssetCard(reFlashId);
    _flashCategoryCard('real_estate');
    onPortfolioChange(true);
    return;
  }

  // ── Manual ISIN branch ────────────────────────────────────
  if (isManualMode) {
    const isinVal = (document.getElementById('isinInput')?.value || '').toUpperCase().trim();
    const nameVal = (document.getElementById('manualName')?.value || '').trim();
    if (!nameVal) { document.getElementById('manualName')?.focus(); return; }

    const qty = parseLocalFloat(qtyInput.value);
    if (isNaN(qty) || qty <= 0) { qtyInput.focus(); return; }

    const price  = parseLocalFloat(document.getElementById('manualPrice')?.value) || 0;
    const ticker = nameVal.replace(/[^a-zA-Z]/g, '').slice(0, 4).toUpperCase() || 'MANU';

    // MANUAL-MERGE-1: merge only when the user typed a real ISIN AND
    // it matches an existing row with the same currency. Without an
    // ISIN the derived 4-letter ticker (e.g. "Vanguard ETF 1" and
    // "Vanguard Fund 2" → VANG) is not reliable identity, so manual
    // entries without an ISIN always create a new row to avoid silent
    // qty/costBasis collapse across unrelated assets.
    const newManualCurrency = (manualCurrency || 'USD').toUpperCase();
    const existing = isinVal
      ? assets.find(a => a.isin === isinVal && (a.assetCurrency || 'USD').toUpperCase() === newManualCurrency)
      : null;

    let manualFlashId = existing?.id;
    const _mBuyTs = Date.now();
    const _mBuyPx = price > 0 ? price : (existing ? (existing.price || 0) : 1);
    if (existing) {
      // AURIX-CLOSED-POSITIONS-1: reactivate if this ISIN row was closed.
      _reactivatePosition(existing);
      const manualAddedCost = qty * (price > 0 ? price : existing.price || 0);
      existing.costBasis = (existing.costBasis || existing.qty * (existing.price || 0)) + manualAddedCost;
      existing.qty = +(existing.qty + qty).toFixed(8);
      if (price > 0) existing.price = price;
      // Backfill symbols if a lookup ran after the original save
      if (manualPendingSymbol  && !existing.marketSymbol) existing.marketSymbol = manualPendingSymbol;
      if (manualPendingCoinId  && !existing.coinId)       existing.coinId       = manualPendingCoinId;
      if (_newLoc) existing.location = _newLoc;   // WL.2: conserve unless user set one
      _ledgerTrade(existing, 'buy', qty, _mBuyPx, _mBuyTs);
    } else {
      manualFlashId = Date.now().toString(36) + Math.random().toString(36).slice(2);
      assets.push({
        id:            manualFlashId,
        name:          nameVal,
        ticker,
        type:          manualAssetType,
        qty,
        price:         price > 0 ? price : 1,
        isin:          isinVal || null,
        coinId:        manualPendingCoinId || null,
        marketSymbol:  manualPendingSymbol || null,
        assetCurrency: manualCurrency,
        change24h:     null,
        prevPrice:     null,
        costBasis:     qty * (price > 0 ? price : 1),
        location:      _newLoc,            // WL.2: optional Wealth Location metadata
        transactions:  [{ type: 'buy', qty, price: price > 0 ? price : 1, ts: _mBuyTs }],
      });
      _ledgerTrade(assets.find(a => a.id === manualFlashId), 'buy', qty, _mBuyPx, _mBuyTs);
    }
    save();
    render(true);
    closeModal();
    _flashAssetCard(manualFlashId);
    _flashCategoryCard(manualAssetType);
    onPortfolioChange(true);
    return;
  }

  if (!selectedDbAsset) return;
  if (!pendingPrice) {
    setLookupStatus('error', t('lookupError'));
    return;
  }

  const qty = parseLocalFloat(qtyInput.value);
  if (isNaN(qty) || qty <= 0) { qtyInput.focus(); return; }

  // PURCHASE-PRICE-V1 — optional real purchase price → sourced into the first Buy
  // transaction (the single source of truth for cost basis / avg price / P&L). When the
  // user leaves it empty, we fall back to the live price `pendingPrice` (unchanged
  // behaviour). The gold flow never shows the field (spot-based valuation), so `_ppRaw`
  // is empty for XAU and `_effectivePrice === pendingPrice`. The live price (`asset.price`,
  // `spotPriceAtAdd`, `manualNav`) is NEVER overwritten by this value.
  const _ppRaw = (function () { const el = document.getElementById('assetPurchasePrice'); return el ? parseLocalFloat(el.value) : NaN; })();
  const _effectivePrice = (Number.isFinite(_ppRaw) && _ppRaw > 0) ? _ppRaw : pendingPrice;

  const { ticker, type, coinId = null, marketSymbol = null } = selectedDbAsset;
  const isGoldAsset = ticker === 'XAU';
  const karat       = isGoldAsset ? pendingKarat    : undefined;
  const goldUnit    = isGoldAsset ? pendingGoldUnit : undefined;
  // AURIX-METALS-ADD-COIN-BUTTON-BUG / VISUAL-SYSTEM — the chosen physical type
  // (bar→bullion / coin / jewelry). Computed once so the dedup AND persistence
  // agree: a coin and a bar at the same karat+unit are DIFFERENT positions and
  // must never silently merge (that merge was hiding freshly-added coins).
  const goldVisualType = isGoldAsset
    ? (() => {
        const gt = (((document.getElementById('goldSection') || {}).dataset) || {}).goldType || '';
        return gt === 'coin' ? 'coin' : gt === 'jewelry' ? 'jewelry' : 'bullion';
      })()
    : undefined;
  const name        = isGoldAsset ? `Gold ${karat}K` : selectedDbAsset.name;

  // Merge into existing position
  // Gold: always isolated by karat + unit — never merged across combinations
  // MANUAL-MERGE-1: market and ticker-fallback paths additionally require
  // the same currency. Same ticker on different exchanges (e.g. IWDA.L
  // in USD vs IWDA.AS in EUR) must NOT collapse into one row — qty/cost
  // basis would silently mix denominations and corrupt PnL. Crypto and
  // gold paths are always USD-denominated, so the currency check is
  // unnecessary for those branches.
  const newCurrency = (pendingCurrency || 'USD').toUpperCase();
  const existing = assets.find(a => {
    const aCurrency = (a.assetCurrency || 'USD').toUpperCase();
    if (coinId && a.coinId) return a.coinId === coinId;
    if (isGoldAsset)        return a.ticker === 'XAU' && a.karat === karat && a.goldUnit === goldUnit && (a.visualType || 'bullion') === goldVisualType;
    if (marketSymbol && a.marketSymbol) return a.marketSymbol === marketSymbol && aCurrency === newCurrency;
    return a.ticker.toUpperCase() === ticker.toUpperCase() && a.type === type && aCurrency === newCurrency;
  });

  // Cost basis for this purchase (in asset's native USD). Uses the effective purchase
  // price (user-entered when provided, else live). Gold keeps its spot formula intact —
  // `_effectivePrice === pendingPrice` for XAU (field hidden).
  const newPurchaseCost = isGoldAsset
    ? _goldGrams(qty, pendingGoldUnit) * _goldPurity(pendingKarat) * (_effectivePrice / OZ_TO_G)
    : qty * _effectivePrice;

  let normalFlashId = existing?.id;
  const _buyTs = Date.now();
  if (existing) {
    // AURIX-CLOSED-POSITIONS-1: re-buying a closed position reactivates the
    // SAME row (history stays unified) — never a duplicate. costBasis on a
    // closed row is 0, so this naturally re-bases to the new purchase cost.
    _reactivatePosition(existing);
    existing.costBasis = (existing.costBasis || assetNativeValue(existing)) + newPurchaseCost;
    existing.qty    = +(existing.qty + qty).toFixed(8);
    existing.price  = pendingPrice;
    if (!existing.transactions) existing.transactions = [];
    existing.transactions.push({ type: 'buy', qty, price: _effectivePrice, ts: _buyTs });
    if (_newLoc) existing.location = _newLoc;   // WL.2: conserve unless user set one
    _ledgerTrade(existing, 'buy', qty, _effectivePrice, _buyTs);
  } else {
    let initialChange24h = null;
    if (marketSymbol && type !== 'crypto') {
      const fb = getFallbackData(marketSymbol);
      if (fb) initialChange24h = fb.change24h;
    }
    normalFlashId = Date.now().toString(36) + Math.random().toString(36).slice(2);
    assets.push({
      id:            normalFlashId,
      name, ticker, type, qty,
      price:         pendingPrice,
      coinId, marketSymbol,
      // AURIX-ASSET-ICON-1: persist the provider logo URL captured from the
      // search result so the correct icon (e.g. HYPE) survives refresh + device.
      image:         (selectedDbAsset && typeof selectedDbAsset.image === 'string') ? selectedDbAsset.image : null,
      // MC-6D: stamp the provider-reported quote currency when available
      // (Yahoo meta.currency surfaced through the snapshot endpoint).
      // Falls back to USD for crypto, gold, and any asset where the
      // provider didn't surface a currency code. Crypto and gold paths
      // intentionally do not set pendingCurrency, so they keep USD.
      assetCurrency: pendingCurrency || 'USD',
      change24h:     initialChange24h,
      prevPrice:     null,
      costBasis:     newPurchaseCost,
      location:      _newLoc,            // WL.2: optional Wealth Location metadata
      // MC-7: fund-only manual NAV fallback. Persisted only when the
      // user actually went through the manual-NAV prompt (provider had
      // no price). The refresh loop falls back to manualNav whenever
      // the provider didn't write a fresh price for the asset.
      ...(pendingIsManualNav && type === 'fund'
        ? { manualNav: pendingPrice, manualNavUpdatedAt: Date.now() }
        : {}),
      // GOLD-1: physical-gold metadata. karat + goldUnit are the inputs
      // the user picked; weightGrams + purityFactor + spotPriceAtAdd
      // are persisted so any downstream tool (reports, exports) can
      // reproduce the value without re-running the formula.
      // GOLD-2: also persist the chosen dealer-margin estimate. Spot
      // remains the canonical portfolio number — these fields are
      // display/reporting only.
      ...(isGoldAsset ? {
        karat,
        goldUnit,
        // AURIX-METALS-VISUAL-SYSTEM-V1 — persist the chosen visual type so the icon
        // system shows the right glyph everywhere (computed once, above).
        visualType:        goldVisualType,
        physicalGold:      true,
        metal:             'gold',
        purityFactor:      _goldPurity(karat),
        weightInput:       qty,
        weightGrams:       _goldGrams(qty, goldUnit),
        spotPriceAtAdd:    pendingPrice,
        goldValuationMode: 'spot',
        resaleMargin:      pendingResaleMargin,
        resaleFactor:      +(Math.max(0, Math.min(1, 1 - pendingResaleMargin / 100))).toFixed(4),
      } : {}),
      transactions:  [{ type: 'buy', qty, price: _effectivePrice, ts: _buyTs }],
    });
    _ledgerTrade(assets.find(a => a.id === normalFlashId), 'buy', qty, _effectivePrice, _buyTs);
  }

  _persistDebug('[persist-add-asset]', {
    added: ticker, type,
    totalNow: Array.isArray(assets) ? assets.length : 0,
    symbols: Array.isArray(assets) ? assets.map(a => a && (a.ticker || a.symbol)) : [],
    authed: !!currentUser,
  });
  save();
  render(true);
  closeModal();
  _flashAssetCard(normalFlashId);
  _flashCategoryCard(type);
  onPortfolioChange(true);
});

// ── Reduce Modal ───────────────────────────────────────────
function openReduceModal(id) {
  const asset = assets.find(a => a.id === id);
  if (!asset) return;
  reduceTargetId = id;

  const assetCurr  = (asset.assetCurrency || 'USD').toUpperCase();
  const isCash     = asset.type === 'cash';
  const isGold     = asset.ticker === 'XAU' && asset.karat;
  const totalBase  = toBase(assetNativeValue(asset), assetCurr);
  const badgeText  = isGold ? `${asset.karat}K` : escHtml(asset.ticker.toUpperCase().slice(0, 4));
  const qtyLabel   = isCash
    ? formatCurrency(asset.qty, assetCurr)
    : isGold
      ? `${formatQty(asset.qty)} ${asset.goldUnit || 'g'}`
      : `${formatQty(asset.qty)} ${t('unidades')}`;

  _reduceApplyMode(isCash);
  reduceAssetInfo.innerHTML = `
    ${buildBadgeHtml(asset, badgeText)}
    <div>
      <div class="reduce-info-name">${escHtml(getDisplayName(asset))}</div>
      <div class="reduce-info-qty">${qtyLabel} · ${formatBase(totalBase)}</div>
    </div>
  `;

  reduceMaxEl.textContent = isGold
    ? t('maxLabel')(formatQty(asset.qty), asset.goldUnit || 'g')
    : t('maxLabel')(formatQty(asset.qty), null);
  reduceQtyInput.value = '';
  previewQtyLeft.textContent   = isCash
    ? formatCurrency(asset.qty, assetCurr)
    : isGold
    ? `${formatQty(asset.qty)} ${asset.goldUnit || 'g'}`
    : formatQty(asset.qty);
  { const r = document.getElementById('previewOpRow'); if (r) r.hidden = true; }
  previewValueLeft.textContent = formatBase(totalBase);
  reduceWarning.classList.remove('visible');
  reduceError.textContent = '';

  reduceOverlay.classList.add('open');
  document.body.classList.add('modal-open');
  reduceQtyInput.focus();
}

// ── LIQUIDEZ: AÑADIR / RETIRAR, NO «REDUCIR POSICIÓN» ─────────────────────
// La hoja es la misma para vender unidades y para retirar efectivo, pero con
// efectivo «cantidad» y «valor» son el MISMO importe: se publicaban dos filas
// iguales y una tercera («Valor de la operación —») que debía estar oculta. Con
// liquidez se habla de importe a retirar y saldo restante, en su divisa. Los
// textos de venta se restauran desde su clave i18n al abrir otro activo.
function _reduceApplyMode(isCash) {
  const ov = document.getElementById('reduceOverlay'); if (!ov) return;
  const set = (sel, cashKey) => {
    const el = ov.querySelector(sel); if (!el) return;
    const base = el.getAttribute('data-i18n');
    el.textContent = isCash ? t(cashKey) : (base ? t(base) : el.textContent);
  };
  set('[data-i18n="modalReduceTitle"]', 'reduceCashTitle');
  set('label[for="reduceQty"]', 'reduceCashAmount');
  set('[data-i18n="qtyRemaining"]', 'reduceCashLeft');
  set('button[type="submit"]', 'reduceCashConfirm');
  const valRow = document.getElementById('previewValueLeft');
  if (valRow && valRow.parentElement) valRow.parentElement.hidden = !!isCash;
  const note = ov.querySelector('[data-trade-note]'); if (note) note.hidden = !!isCash;
}

function closeReduceModal() {
  reduceOverlay.classList.remove('open');
  document.body.classList.remove('modal-open');
  reduceTargetId = null;
}

function updateReducePreview() {
  const asset  = assets.find(a => a.id === reduceTargetId);
  if (!asset) return;

  const amount  = parseLocalFloat(reduceQtyInput.value) || 0;
  const cur     = (asset.assetCurrency || 'USD').toUpperCase();
  const isGold  = asset.ticker === 'XAU' && asset.karat;
  reduceError.textContent = '';

  if (amount > asset.qty) {
    const maxLabel = isGold ? `${formatQty(asset.qty)} ${asset.goldUnit || 'g'}` : formatQty(asset.qty);
    reduceError.textContent = t('cantExceed')(maxLabel);
    previewQtyLeft.textContent   = '—';
    previewValueLeft.textContent = '—';
    { const r = document.getElementById('previewOpRow'); if (r) r.hidden = true; }
    reduceWarning.classList.remove('visible');
    return;
  }

  // P0 §25 — EL VALOR DE LO QUE SE QUITA. Se publica sólo si hay un precio con el que
  // calcularlo: sin precio fiable no se inventa un cero, se deja la fila fuera —que es la
  // misma regla que ya gobierna el resto de Aurix (§38).
  {
    const opRow = document.getElementById('previewOpRow');
    const opLbl = document.getElementById('previewOpLabel');
    const opVal = document.getElementById('previewOpValue');
    if (opRow && opVal) {
      const px = Number(asset.price);
      const canValue = asset.type !== 'cash' && Number.isFinite(px) && px > 0 && amount > 0;
      if (asset.type === 'cash' && amount > 0) {
        if (opLbl) opLbl.textContent = t('reduceCashAmount');
        opVal.textContent = formatCurrency(amount, cur);
        opRow.hidden = false;
      } else if (canValue) {
        if (opLbl) opLbl.textContent = t('reduceOpValue');
        opVal.textContent = formatDisplay(assetNativeValue({ ...asset, qty: amount }), cur);
        opRow.hidden = false;
      } else {
        opRow.hidden = true;
        opVal.textContent = '—';
      }
    }
  }
  const remaining      = asset.qty - amount;
  const remainingAsset = { ...asset, qty: remaining };
  previewQtyLeft.textContent   = asset.type === 'cash'
    ? formatCurrency(remaining, cur)
    : isGold
      ? `${formatQty(remaining)} ${asset.goldUnit || 'g'}`
      : formatQty(remaining);
  previewValueLeft.textContent = formatDisplay(assetNativeValue(remainingAsset), cur);
  reduceWarning.classList.toggle('visible', remaining === 0 && amount > 0);
}

reduceQtyInput.addEventListener('input', updateReducePreview);

reduceForm.addEventListener('submit', e => {
  e.preventDefault();
  const asset  = assets.find(a => a.id === reduceTargetId);
  if (!asset) return;

  const amount = parseLocalFloat(reduceQtyInput.value);
  if (isNaN(amount) || amount <= 0) {
    reduceError.textContent = t('errQtyPositive');
    return;
  }
  if (amount > asset.qty) {
    reduceError.textContent = t('cantExceed')(formatQty(asset.qty));
    return;
  }

  const remaining  = asset.qty - amount;
  const wasRemoved = remaining === 0;
  const reduceType = asset.type;
  // Tax-lot-ready ledger: record the sell at the current price.
  // Realized P&L uses blended avg cost (current accounting model) and is
  // added to a persistent realizedPnL field. Tax-lot methods (FIFO/LIFO)
  // can later consume the transactions[] array without schema changes.
  const avgCostPerUnit = (asset.costBasis && asset.qty > 0) ? asset.costBasis / asset.qty : 0;
  const currentPrice   = Number(asset.price);
  const realized       = (Number.isFinite(currentPrice) && currentPrice > 0)
    ? (currentPrice - avgCostPerUnit) * amount
    : 0;
  if (!Array.isArray(asset.transactions)) asset.transactions = [];
  const _sellTs    = Date.now();
  const _sellPrice = Number.isFinite(currentPrice) ? currentPrice : 0;
  const _isCashReduce = (asset.type === 'cash');
  // AURIX-CASH-LEDGER-TRUTH — retirar liquidez es una RETIRADA, no la venta de un
  // instrumento: no realiza plusvalía ni prorratea coste. La escribe el owner
  // económico (transacción + flujo + costBasis + saldo) unas líneas más abajo.
  if (!_isCashReduce) {
    asset.transactions.push({
      type:  'sell',
      qty:   amount,
      price: _sellPrice,
      ts:    _sellTs,
    });
    asset.realizedPnL = Number(asset.realizedPnL || 0) + (Number.isFinite(realized) ? realized : 0);
  }
  // AURIX-WEALTH-LEDGER-CAPTURE-1: cash reductions are withdrawals; everything
  // else is a sell (with durable realized PnL on the event).
  // WN.8 AUDIT: a NON-cash sell here only REDUCES/CLOSES the asset — it does NOT
  // add the proceeds to any cash/liquidity asset. So selling ~30k of BTC drops
  // investable value by ~30k with no offsetting cash leg, which is why the chart
  // showed a 7D crash. WN.8 classifies this as an INTERNAL_SELL (proceeds assumed
  // to stay in the portfolio) and the chart's flow layer neutralises the
  // asset_remove so it reads as a value-preserving transfer, not a market loss.
  // (Real assets are NOT auto-mutated here — too risky / could double-count if
  // the user later records the cash manually; the reconciliation is visual +
  // metric only, anchored to the real current value.)
  if (_isCashReduce) {
    const _cashRes = aurixCashOperation('withdrawal', {
      asset, amount, currency: (asset.assetCurrency || 'USD'), ts: _sellTs, source: asset.source || null,
    });
    if (!_cashRes.ok) { reduceError.textContent = t('errQtyPositive'); return; }
    // Retirar TODA la liquidez cierra la posición igual que antes (saldo 0), y el
    // owner ya dejó el saldo y el ledger en su sitio.
    if (wasRemoved) _closePosition(asset, _sellTs);
  } else {
    _ledgerTrade(asset, 'sell', amount, _sellPrice, _sellTs, (Number.isFinite(realized) ? realized : 0));
    if (wasRemoved) {
      // AURIX-CLOSED-POSITIONS-1: full sell → CLOSE, never delete. History +
      // realizedPnL (already accrued above) stay attached to the row.
      _closePosition(asset, _sellTs);
    } else {
      if (asset.costBasis && asset.qty > 0) asset.costBasis *= remaining / asset.qty;
      asset.qty = remaining;
    }
  }

  const sellToastName = (typeof getDisplayName === 'function') ? getDisplayName(asset) : (asset.name || asset.ticker || '');
  _persistEmptyPortfolioIfNeeded('reduce');
  save();
  render(true);
  closeReduceModal();
  if (!wasRemoved) _flashAssetCard(reduceTargetId);
  _flashCategoryCard(reduceType);
  onPortfolioChange(true);
  try {
    if (typeof _aurixShowToast === 'function')
      _aurixShowToast(t('sellToast')(formatQty(amount), sellToastName), { variant: 'info', duration: 2200 });
  } catch (_) {}
});

reduceClose.addEventListener('click', closeReduceModal);
reduceOverlay.addEventListener('click', e => {
  if (e.target === reduceOverlay) closeReduceModal();
});

// ── Add position modal ─────────────────────────────────────
const addOverlay          = document.getElementById('addOverlay');
const addClose            = document.getElementById('addClose');
const addForm             = document.getElementById('addForm');
const addAssetInfo        = document.getElementById('addAssetInfo');
const addQtyInput         = document.getElementById('addQty');
const addQtyLabelEl       = document.getElementById('addQtyLabel');
const previewAddQtyTotal  = document.getElementById('previewAddQtyTotal');
const previewAddValueTotal= document.getElementById('previewAddValueTotal');
const addError            = document.getElementById('addError');

let addTargetId = null;

function openAddModal(id) {
  const asset = assets.find(a => a.id === id);
  if (!asset) return;
  addTargetId = id;

  const assetCurr  = (asset.assetCurrency || 'USD').toUpperCase();
  const isCash     = asset.type === 'cash';
  const isGold     = asset.ticker === 'XAU' && asset.karat;
  const totalBase  = toBase(assetNativeValue(asset), assetCurr);
  const badgeText  = isGold ? `${asset.karat}K` : escHtml(asset.ticker.toUpperCase().slice(0, 4));
  const qtyLabel   = isCash
    ? formatCurrency(asset.qty, assetCurr)
    : isGold
      ? `${formatQty(asset.qty)} ${asset.goldUnit || 'g'}`
      : `${formatQty(asset.qty)} ${t('unidades')}`;

  addAssetInfo.innerHTML = `
    ${buildBadgeHtml(asset, badgeText)}
    <div>
      <div class="reduce-info-name">${escHtml(getDisplayName(asset))}</div>
      <div class="reduce-info-qty">${qtyLabel} · ${formatBase(totalBase)}</div>
    </div>
  `;

  addQtyLabelEl.textContent = isCash ? t('addQtyLabelCash') : t('addQtyLabel')(isGold ? asset.goldUnit || 'g' : null);
  { const n = document.querySelector('#addOverlay [data-trade-note]'); if (n) n.hidden = !!isCash; }
  addQtyInput.value         = '';
  addError.textContent      = '';
  previewAddQtyTotal.textContent   = isCash
    ? formatCurrency(asset.qty, assetCurr)
    : isGold ? `${formatQty(asset.qty)} ${asset.goldUnit || 'g'}` : formatQty(asset.qty);
  previewAddValueTotal.textContent = formatBase(totalBase);

  addOverlay.classList.add('open');
  document.body.classList.add('modal-open');
  addQtyInput.focus();
}

function closeAddModal() {
  addOverlay.classList.remove('open');
  document.body.classList.remove('modal-open');
  addTargetId = null;
}

function updateAddPreview() {
  const asset = assets.find(a => a.id === addTargetId);
  if (!asset) return;

  const amount    = parseLocalFloat(addQtyInput.value) || 0;
  const assetCurr = (asset.assetCurrency || 'USD').toUpperCase();
  const isCash    = asset.type === 'cash';
  const isGold    = asset.ticker === 'XAU' && asset.karat;
  addError.textContent = '';

  if (amount < 0) {
    addError.textContent = t('errQtyMustPositive');
    previewAddQtyTotal.textContent    = '—';
    previewAddValueTotal.textContent  = '—';
    return;
  }

  const newQty   = asset.qty + amount;
  const newAsset = { ...asset, qty: newQty };
  previewAddQtyTotal.textContent   = isCash
    ? formatCurrency(newQty, assetCurr)
    : isGold ? `${formatQty(newQty)} ${asset.goldUnit || 'g'}` : formatQty(newQty);
  previewAddValueTotal.textContent = formatDisplay(assetNativeValue(newAsset), assetCurr);
}

addQtyInput.addEventListener('input', updateAddPreview);

addForm.addEventListener('submit', e => {
  e.preventDefault();
  const asset = assets.find(a => a.id === addTargetId);
  if (!asset) return;

  const amount = parseLocalFloat(addQtyInput.value);
  if (isNaN(amount) || amount <= 0) {
    addError.textContent = t('errQtyPositive');
    return;
  }

  // AURIX-CONTEXTUAL-ADD-FIX-1 — record the buy through the SAME durable path as
  // every real holdings edit (the canonical re-buy + the contextual sell): push a
  // 'buy' transaction AND log the ledger trade. Without this the qty-only mutation
  // did not survive: save() → recomputeDerivedFinancialState (and the holdings
  // merge) recompute the quantity FROM the transaction ledger, so an add with no
  // transaction reverted to the previous value on render/refresh (the reported
  // "10 → +1 → still 10"). qty + costBasis are still updated here for the instant
  // optimistic paint; the ledger makes it persist. Mirrors the sell handler.
  const _buyTs    = Date.now();
  const _buyPrice = Number.isFinite(Number(asset.price)) ? Number(asset.price) : 0;
  // AURIX-CASH-LEDGER-TRUTH — la liquidez sale de esta rama. Un "+" sobre un
  // activo cash es una APORTACIÓN, no la compra de un instrumento: emitía a la vez
  // una transacción `buy` y un `deposit` (doble representación del mismo hecho) y
  // calculaba el coste con la ruta de valoración de activos. Ahora lo resuelve el
  // owner económico, exactamente igual que el modal de liquidez.
  if (asset.type === 'cash') {
    const _cashRes = aurixCashOperation('deposit', {
      asset, amount, currency: (asset.assetCurrency || 'USD'), ts: _buyTs, source: asset.source || null,
    });
    if (!_cashRes.ok) { addError.textContent = t('errQtyPositive'); return; }
  } else {
    const addedCostNative = assetNativeValue({ ...asset, qty: amount });
    asset.costBasis = (asset.costBasis || assetNativeValue(asset)) + addedCostNative;
    asset.qty = +(asset.qty + amount).toFixed(8);
    if (!Array.isArray(asset.transactions)) asset.transactions = [];
    asset.transactions.push({ type: 'buy', qty: amount, price: _buyPrice, ts: _buyTs });
    _ledgerTrade(asset, 'buy', amount, _buyPrice, _buyTs);
  }
  const addFlashId   = asset.id;
  const addFlashType = asset.type;
  const addToastName = (typeof getDisplayName === 'function') ? getDisplayName(asset) : (asset.name || asset.ticker || '');
  save();
  render(true);
  closeAddModal();
  _flashAssetCard(addFlashId);
  _flashCategoryCard(addFlashType);
  onPortfolioChange(true);
  try {
    if (typeof _aurixShowToast === 'function')
      _aurixShowToast(t('buyToast')(formatQty(amount), addToastName), { variant: 'success', duration: 2200 });
  } catch (_) {}
});

addClose.addEventListener('click', closeAddModal);
addOverlay.addEventListener('click', e => {
  if (e.target === addOverlay) closeAddModal();
});

// ── Edit Real Estate Modal ──────────────────────────────────
function openEditRealEstateModal(id) {
  const asset = assets.find(a => a.id === id);
  if (!asset || asset.type !== 'real_estate') return;

  // Open modal (resets state), then enter RE mode, then prefill.
  // ADD-V2.1: skips the type picker — this is an edit entry point, not
  // a new-asset flow, so dropping into Step 2 directly is correct.
  // ADD-V2.2: pin the RE mode so the contextual CSS hides search/gold.
  openModal({ skipPicker: true });
  if (typeof _addV2SetMode === 'function') _addV2SetMode('real_estate');
  // Activate the RE filter button visually
  filterBtns.forEach(b => b.classList.toggle('active', b.dataset.filter === 'real_estate'));
  enterRealEstateMode();

  // Set edit target
  reEditTargetId    = id;
  rePendingCurrency = (asset.assetCurrency || 'EUR').toUpperCase();

  // Prefill name
  const reNameInput = document.getElementById('reName');
  if (reNameInput) reNameInput.value = asset.name || '';

  // Prefill value
  const locale = lang === 'es' ? 'es-ES' : 'en-US';
  qtyInput.value = new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(asset.qty);

  // Prefill rent
  const reRentInput = document.getElementById('reRent');
  if (reRentInput) reRentInput.value = asset.rent > 0
    ? new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(asset.rent)
    : '';

  // Set currency toggle
  document.querySelectorAll('.re-curr-btn').forEach(b =>
    b.classList.toggle('active', b.dataset.curr === rePendingCurrency));

  // Update modal title
  const modalTitle = document.querySelector('#modalOverlay .modal-header h3');
  if (modalTitle) modalTitle.textContent = t('modalEditRETitle');

  // Trigger qty preview update
  qtyInput.dispatchEvent(new Event('input'));
}

// ── Delete / Reduce / Add click dispatcher ─────────────────
assetsListEl.addEventListener('click', e => {
  const mngBtn = e.target.closest('.dar-manage');
  if (mngBtn) { openAssetManage(mngBtn.dataset.id); return; }

  const editREBtn = e.target.closest('.btn-edit-re');
  if (editREBtn) { openEditRealEstateModal(editREBtn.dataset.id); return; }

  // AURIX-HOLDING-CONTEXTUAL-BUY-SELL-1 — the +/− card buttons open the dedicated
  // contextual panels (Aumentar / Reducir posición), never an inline form inside
  // the card. A holding card stays visual-only.
  const addBtn = e.target.closest('.btn-add-pos');
  if (addBtn) { openAddModal(addBtn.dataset.id); return; }

  const reduceBtn = e.target.closest('.btn-reduce');
  if (reduceBtn) { openReduceModal(reduceBtn.dataset.id); return; }

  const deleteBtn = e.target.closest('.btn-delete');
  if (deleteBtn) {
    const delId   = deleteBtn.dataset.id;
    const delAsset = assets.find(a => a.id === delId);
    if (!delAsset) return;
    const delType = delAsset.type;
    const delName = (typeof getDisplayName === 'function') ? getDisplayName(delAsset) : (delAsset.name || delAsset.ticker || '');
    // HARDEN: the dashboard card "✕" used to delete with NO confirmation.
    // Route it through the same premium confirm as the manage sheet so a
    // mistap can never wipe a position.
    _aurixConfirm({
      title: t('deleteAssetTitle'), message: t('deleteAssetMsg')(delName),
      confirmLabel: t('btnDelete'), cancelLabel: t('keepBtn'), danger: true,
    }).then(ok => {
      if (!ok || !assets.find(a => a.id === delId)) return;
      const commit = () => {
        // AURIX-WEALTH-TRANSACTION-INTEGRITY — la contrapartida en el ledger ANTES
        // de quitar la fila (después ya no hay saldo que leer), y `save` con el
        // contexto destructivo que el guard de persistencia exige: sin él la
        // reducción se bloqueaba en disco y `save()` restauraba la fila desde el
        // último estado válido, así que la eliminación no persistía.
        try { _aurixLedgerAssetRemoval(delAsset, Date.now()); } catch (_) {}
        assets = assets.filter(a => a.id !== delId);
        _persistEmptyPortfolioIfNeeded('delete');
        save('delete-asset');
        render(true);
        _flashCategoryCard(delType);
        onPortfolioChange(true);
      };
      const delCard = assetsListEl.querySelector(`[data-asset-id="${delId}"]`);
      if (delCard && !reducedMotion) {
        delCard.classList.add('card--exiting');
        setTimeout(commit, 200);
      } else {
        commit();
      }
    });
  }
});

// ── Base currency toggle (menu) ─────────────────────────────
function _applyCurrencyChange(currency) {
  baseCurrency = currency;
  localStorage.setItem(BASE_KEY, baseCurrency);
  // AURIX-LAUNCH-P0-PERSISTENCE: stamp + flush so this explicit choice wins.
  try { _touchPrefs(); } catch (_) {}
  document.querySelectorAll('.menu-curr-btn')
    .forEach(b => b.classList.toggle('active', b.dataset.currency === baseCurrency));
  _syncPerfCurrencyButtons();
  try { _aurixFxNoteRender(); } catch (_) {}
  render(true);
  updateChart(true);
  updateDonut();
  // Propagate currency change to other surfaces that read baseCurrency at
  // render time (workspace summary cards, market list).
  if (currentTab === 'workspace' && typeof renderWorkspace === 'function') {
    renderWorkspace();
  } else if (currentTab === 'market' && typeof renderMarket === 'function') {
    renderMarket();
  }
}

document.querySelectorAll('.menu-curr-btn').forEach(btn => {
  btn.addEventListener('click', () => _applyCurrencyChange(btn.dataset.currency));
});

// ── DSH.SETTINGS.TOGGLE.01 — language/currency are real buttons everywhere ─────
// The Idioma/Moneda buttons now live in the Settings modal, which is parsed in
// index.html AFTER this <script> tag. The boot-time direct addEventListener calls
// above therefore bound to ZERO elements (the old menu copies were removed), so
// clicking did nothing. Delegate from document to the EXISTING switchLang /
// _applyCurrencyChange (no parallel logic) so clicks work no matter when the
// markup is parsed, and keep .active + aria-pressed in exact sync.
function _aurixSyncLangCurrencyButtons() {
  try {
    document.querySelectorAll('[data-lang]').forEach(b => {
      const on = b.dataset.lang === lang;
      b.classList.toggle('active', on);
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    document.querySelectorAll('.menu-curr-btn').forEach(b => {
      const on = b.dataset.currency === baseCurrency;
      b.classList.toggle('active', on);
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
  } catch (_) {}
}
if (typeof document !== 'undefined') {
  document.addEventListener('click', e => {
    const langBtn = e.target.closest && e.target.closest('[data-lang]');
    if (langBtn && langBtn.dataset.lang) {
      if (typeof switchLang === 'function') switchLang(langBtn.dataset.lang);
      _aurixSyncLangCurrencyButtons();
      return;
    }
    const curBtn = e.target.closest && e.target.closest('.menu-curr-btn');
    if (curBtn && curBtn.dataset.currency) {
      if (typeof _applyCurrencyChange === 'function') _applyCurrencyChange(curBtn.dataset.currency);
      _aurixSyncLangCurrencyButtons();
      return;
    }
  });
}


// ── Liquidity Modal ────────────────────────────────────────
const liquidityOverlay  = document.getElementById('liquidityOverlay');
const liquidityClose    = document.getElementById('liquidityClose');
const liquidityForm     = document.getElementById('liquidityForm');
const liquidityQtyInput = document.getElementById('liquidityQty');
const liquidityCurrIn   = document.getElementById('liquidityCurrency');
const liqBtns           = document.querySelectorAll('.liq-btn');

// Attach live formatters
attachFormatter(qtyInput,       true);   // asset qty — allow decimals (e.g. 0.0015 BTC)
attachFormatter(reduceQtyInput, true);   // reduce qty
attachFormatter(addQtyInput,    true);   // add to position qty

// Liquidity: direct integer formatter (no decimals, no cursor complexity)
liquidityQtyInput.addEventListener('input', e => {
  const digits = e.target.value.replace(/\D/g, '');
  if (!digits) { e.target.value = ''; return; }
  e.target.value = new Intl.NumberFormat('es-ES', { maximumFractionDigits: 0 }).format(parseInt(digits, 10));
});

function openLiquidityModal() {
  // ADD-FLOW-ARCH-1: claim liquidity context and force-close any open
  // asset modal so the two intents are mutually exclusive on screen
  // and in state. Asset side resets its own pending fields via
  // closeModal → openModal cycles, so we never leak across.
  _modalContext = 'liquidity';
  try {
    if (typeof modalOverlay !== 'undefined' && modalOverlay &&
        modalOverlay.classList.contains('open')) {
      closeModal();
    }
  } catch (_) {}
  liquidityForm.reset();
  liquidityCurrIn.value = 'EUR';
  liqBtns.forEach(b => b.classList.toggle('active', b.dataset.curr === 'EUR'));
  // ADD-FLOW-ARCHITECTURE-2: reset the optional source row to the
  // "Sin especificar" default so each open starts clean.
  try {
    const srcInput = document.getElementById('liquiditySource');
    if (srcInput) srcInput.value = '';
    document.querySelectorAll('#liqSourceRow .liq-source-pill').forEach(b => {
      b.classList.toggle('active', (b.dataset.source || '') === '');
    });
  } catch (_) {}
  liquidityOverlay.classList.add('open');
  document.body.classList.add('modal-open');
  setTimeout(() => liquidityQtyInput.focus(), 50);
}

function closeLiquidityModal() {
  liquidityOverlay.classList.remove('open');
  document.body.classList.remove('modal-open');
  // ADD-FLOW-ARCH-1: release context only if liquidity still owns it.
  if (_modalContext === 'liquidity') _modalContext = null;
}

liqBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    liquidityCurrIn.value = btn.dataset.curr;
    liqBtns.forEach(b => b.classList.toggle('active', b === btn));
  });
});

// ADD-FLOW-ARCHITECTURE-2: source-pill row wiring. Pure UI selector
// over a hidden input — the form submit handler reads the canonical
// value off `#liquiditySource` so callers don't have to know about
// the pill DOM. Empty string means "no source specified".
document.querySelectorAll('#liqSourceRow .liq-source-pill').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('#liqSourceRow .liq-source-pill').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    const srcInput = document.getElementById('liquiditySource');
    if (srcInput) srcInput.value = btn.dataset.source || '';
  });
});

// ── Real estate currency toggle ─────────────────────────────
document.querySelectorAll('.re-curr-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    rePendingCurrency = btn.dataset.curr;
    document.querySelectorAll('.re-curr-btn')
      .forEach(b => b.classList.toggle('active', b === btn));
    updatePreview();
  });
});

liquidityForm.addEventListener('submit', e => {
  e.preventDefault();
  // UN ENVÍO POR APERTURA: un doble Enter registraba la aportación dos veces (1.000 € → 2.000 €
  // con dos operaciones). Reducir/añadir ya lo evitaban anulando su destino al cerrar.
  if (!liquidityOverlay.classList.contains('open')) return;
  const curr = liquidityCurrIn.value || 'EUR';
  const qty  = parseLocalFloat(liquidityQtyInput.value);
  if (isNaN(qty) || qty <= 0) { liquidityQtyInput.focus(); return; }
  // ADD-FLOW-ARCHITECTURE-2: optional source label — informational
  // only, never feeds valuation. Allowed values are constrained so a
  // stale DOM can't smuggle arbitrary strings into stored assets.
  const _ALLOWED_SRC = new Set(['bank', 'broker', 'wallet', 'cash']);
  const srcInput = document.getElementById('liquiditySource');
  const rawSource = srcInput ? String(srcInput.value || '').trim() : '';
  const source = _ALLOWED_SRC.has(rawSource) ? rawSource : null;

  // LIQ-1: cash storage uses price = 1. The value of a cash position is
  // qty in its assetCurrency — there is no unit price to attach. The
  // legacy storage stamped EUR cash with price = 1/usdToEur, which the
  // valuation path then mis-converted. New entries store price:1 so
  // qty * price reads cleanly in any consumer; assetNativeValue
  // additionally short-circuits cash to qty, covering legacy rows.
  // AURIX-CASH-LEDGER-TRUTH — este handler ya NO hace contabilidad. Localiza (o
  // crea vacío) el activo y delega en el owner económico único, el mismo que usan
  // el "+" y el "−" contextuales. Antes incrementaba el saldo aquí sin dejar
  // transacción ni costBasis, así que la misma aportación registrada por el otro
  // botón producía un estado distinto y el saldo no era reconstruible.
  let existingCash = assets.find(a => a.type === 'cash' && a.assetCurrency === curr);
  if (!existingCash) {
    existingCash = {
      id:            Date.now().toString(36) + Math.random().toString(36).slice(2),
      name:          curr === 'EUR' ? 'Euros' : 'Dólares',
      ticker:        curr === 'EUR' ? '€' : '$',
      type:          'cash',
      qty:           0,                  // el saldo lo pone la operación, no el alta
      price:         1,
      coinId:        null,
      marketSymbol:  null,
      assetCurrency: curr,
      change24h:     null,
      prevPrice:     null,
      costBasis:     0,
      transactions:  [],
      source:        source || null,
    };
    assets.push(existingCash);
  }
  const _liqRes = aurixCashOperation('deposit', { asset: existingCash, amount: qty, currency: curr, source });
  if (!_liqRes.ok) { liquidityQtyInput.focus(); return; }
  // AURIX-WEALTH-LEDGER-CAPTURE-1: el evento del wealthLedger opcional sigue
  // emitiéndose; el flujo de capital ya lo escribió el owner con id estable.
  try {
    const WL = window.wealthLedger;
    if (WL && WL.record) WL.record({ type: 'deposit', amount: qty, currency: curr, ts: Date.now(), origin: 'user',
                                     assetId: existingCash.id, ticker: existingCash.ticker, source: source || undefined });
  } catch (_) {}

  save();
  render(true);
  closeLiquidityModal();
  onPortfolioChange(true);
});

liquidityClose.addEventListener('click', closeLiquidityModal);
liquidityOverlay.addEventListener('click', e => {
  if (e.target === liquidityOverlay) closeLiquidityModal();
});
document.getElementById('btnAddLiquidity').addEventListener('click', openLiquidityModal);

