// ── ADD-V4.1: premium gold UX — delegated wiring ───────────────────
// The new selectors (purity / unit / valuation mode / buyer) live
// inside #goldSection. They mutate the same pending* state vars the
// existing gold logic reads (pendingKarat, pendingGoldUnit,
// pendingResaleMargin) so submit-time persistence and the canonical
// formulas (assetNativeValue, _goldGrams, _goldPurity) keep working
// unchanged. No new persisted fields.

// Move #qtyGroup inside the gold section so purity/unit/qty group
// visually under "What do you own?"; restored to its original parent
// when leaving gold mode. Position uses an anchor div + a sentinel
// so multiple back-and-forth transitions stay correct.
let _addV4QtyHome = null;
let _addV4QtyNext = null;
function _addV4MoveQtyIntoGold() {
  const anchor = document.getElementById('goldQtyAnchor');
  if (!anchor || !qtyGroup) return;
  if (anchor.contains(qtyGroup)) return;  // already moved
  if (!_addV4QtyHome) {
    _addV4QtyHome = qtyGroup.parentNode;
    _addV4QtyNext = qtyGroup.nextSibling;
  }
  anchor.appendChild(qtyGroup);
}
function _addV4RestoreQty() {
  if (!_addV4QtyHome || !qtyGroup) return;
  if (qtyGroup.parentNode === _addV4QtyHome) return;
  if (_addV4QtyNext && _addV4QtyNext.parentNode === _addV4QtyHome) {
    _addV4QtyHome.insertBefore(qtyGroup, _addV4QtyNext);
  } else {
    _addV4QtyHome.appendChild(qtyGroup);
  }
}
function _addV4SyncGoldUI() {
  const section = document.getElementById('goldSection');
  if (!section) return;
  section.querySelectorAll('[data-gold-karat]').forEach(b =>
    b.classList.toggle('is-active', Number(b.dataset.goldKarat) === Number(pendingKarat))
  );
  section.querySelectorAll('[data-gold-unit]').forEach(b =>
    b.classList.toggle('is-active', String(b.dataset.goldUnit) === String(pendingGoldUnit))
  );
  section.querySelectorAll('[data-gold-mode]').forEach(b =>
    b.classList.toggle('is-active', b.dataset.goldMode === pendingGoldValuationMode)
  );
  section.querySelectorAll('[data-gold-buyer]').forEach(b =>
    b.classList.toggle('is-active', Number(b.dataset.marginInternal) === Number(pendingResaleMargin))
  );
  // GOLD-UX-PREMIUM-REBUILD — scenario pills are visible whenever the
  // "Ajustar escenario de venta" disclosure is open. Visibility is
  // owned by the panel toggle, not the valuation mode.
  const buyerRowEl = document.getElementById('goldBuyerRow');
  if (buyerRowEl) buyerRowEl.hidden = false;
}

(function _addV4WireGold() {
  const section = document.getElementById('goldSection');
  if (!section) return;
  section.addEventListener('click', e => {
    const target = e.target.closest && e.target.closest('button');
    if (!target || target.disabled) return;

    // GOLD-UX-PREMIUM-REBUILD STEP 1 — type chip click. Stamps the
    // selection on the section so CSS reveals STEP 2 / STEP 3 / the
    // estimate card. Preselects a sensible default karat per type so
    // the user can keep moving without a second tap.
    if (target.dataset.goldType !== undefined &&
        target.classList.contains('gold-type-chip')) {
      const chosen = target.dataset.goldType;
      if (!chosen) return;
      section.dataset.goldType = chosen;
      // Update active class on the type chip row.
      section.querySelectorAll('.gold-type-chip').forEach(b =>
        b.classList.toggle('is-active', b.dataset.goldType === chosen));
      // Default karat per type — exact spec mapping.
      const DEFAULTS = { jewelry: 18, coin: 22, bar: 24 };
      if (DEFAULTS[chosen] != null) pendingKarat = DEFAULTS[chosen];
      _addV4SyncGoldUI();
      updatePreview();
      return;
    }

    // GOLD-UX-PREMIUM-REBUILD STEP 2 — "No lo sé" chip maps
    // conservatively to 18K. Sits next to the numeric purity chips so
    // a non-expert never feels blocked.
    if (target.dataset.goldKaratUnknown) {
      pendingKarat = 18;
      _addV4SyncGoldUI();
      updatePreview();
      return;
    }
    if (target.dataset.goldKarat) {
      pendingKarat = parseInt(target.dataset.goldKarat, 10) || pendingKarat;
      _addV4SyncGoldUI();
      updatePreview();
      return;
    }
    if (target.dataset.goldUnit) {
      pendingGoldUnit = target.dataset.goldUnit;
      if (qtyLabelEl) qtyLabelEl.textContent = t('qtyGold')(pendingGoldUnit);
      _addV4SyncGoldUI();
      updatePreview();
      return;
    }
    if (target.dataset.goldMode) {
      pendingGoldValuationMode = target.dataset.goldMode === 'resale' ? 'resale' : 'spot';
      _addV4SyncGoldUI();
      updatePreview();
      return;
    }
    if (target.dataset.goldBuyer) {
      // GOLD-UX-PREMIUM-REBUILD — picking a scenario pill auto-flips
      // valuation to "resale" so the user doesn't have to make a second
      // decision after opening the disclosure. The (now-hidden) mode
      // toggle stays in the DOM so the existing valuation math reads
      // the same `pendingGoldValuationMode` flag.
      const m = parseInt(target.dataset.marginInternal, 10);
      if (Number.isFinite(m)) pendingResaleMargin = m;
      pendingGoldValuationMode = 'resale';
      _addV4SyncGoldUI();
      updatePreview();
      return;
    }
    if (target.id === 'goldBuyerToggle') {
      // Toggles the "Ajustar escenario de venta" disclosure (scenario
      // pills). Resting state shows only the clean spot estimate.
      const panel = document.getElementById('goldAdjustPanel');
      if (!panel) return;
      const willOpen = panel.hidden;
      panel.hidden = !willOpen;
      target.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
      const icon = target.querySelector('.gold-more-icon');
      if (icon) icon.textContent = willOpen ? '‹' : '›';
      return;
    }
  });
})();

function validateTransaction(asset, tx) {
  syncQtyFromTransactions(asset);
  const qty   = Number(tx.qty)   || 0;
  const price = Number(tx.price) || 0;
  if (qty   <= 0) { alert(t('invalidQty'));   return false; }
  if (price <= 0) { alert(t('invalidPrice')); return false; }
  if (tx.type === 'sell') {
    const currentQty = asset.qty || 0;
    if (qty > currentQty) { alert(t('sellExceeds')(currentQty)); return false; }
  }
  return true;
}

// ── Transaction system ─────────────────────────────────────
function addTransaction(assetId, type, qty, price) {
  const asset = assets.find(a => a.id === assetId);
  if (!asset) return;
  if (!asset.transactions) asset.transactions = [];
  const tx = { type, qty, price, ts: Date.now(), assetName: asset.name };
  asset.transactions.push(tx);
  if (type === 'buy') recordBuy(tx);
  save();
}

let _txAssetId       = null;
let _editingTxIndex  = null;
const txOverlay    = document.getElementById('txOverlay');
const txForm       = document.getElementById('txForm');
const txQtyInput   = document.getElementById('txQty');
const txPriceInput = document.getElementById('txPrice');
const txErrorEl    = document.getElementById('txError');
const txTypeHidden = document.getElementById('txTypeHidden');

function openTxModal(assetId) {
  _txAssetId = assetId;
  txForm.reset();
  txTypeHidden.value = 'buy';
  document.querySelectorAll('#txTypeToggle [data-txtype]')
    .forEach(b => b.classList.toggle('active', b.dataset.txtype === 'buy'));
  txErrorEl.textContent = '';
  const asset = assets.find(a => a.id === assetId);
  if (asset && asset.price && !isNaN(asset.price)) {
    txPriceInput.value = asset.price;
  }
  { const b = document.getElementById('txPreview'); if (b) b.hidden = true; }
  txOverlay.classList.add('open');
  document.body.classList.add('modal-open');
  setTimeout(() => txQtyInput.focus(), 50);
}

function closeTxModal() {
  txOverlay.classList.remove('open');
  document.body.classList.remove('modal-open');
  _txAssetId      = null;
  _editingTxIndex = null;
}

document.getElementById('txClose').addEventListener('click', closeTxModal);
txOverlay.addEventListener('click', e => { if (e.target === txOverlay) closeTxModal(); });

// ── P0 §25 · LO QUE CUESTA O LO QUE SE COBRA, EN VIVO ─────────────────────
// Esta hoja sólo pedía unidades y precio por unidad, así que el usuario tenía que
// multiplicar de cabeza para saber cuánto dinero movía una compra o una venta.
// Ahora se publica mientras teclea, y con dos naturalezas DISTINTAS que no se
// mezclan:
//   · el VALOR DE LA OPERACIÓN es exacto — cantidad y precio los declara él;
//   · el VALOR DE LA POSICIÓN resultante es ESTIMADO, porque usa el precio de
//     mercado del activo, que él no ha declarado. Se rotula como estimado.
// Y si no hay precio de mercado con el que valorar la posición, esa fila NO se
// publica: un cero ahí diría que la posición no vale nada (§38).
// Todo en la divisa del ACTIVO, que es la del precio por unidad: no se mezcla.
function _aurixTxUpdatePreview() {
  const box = document.getElementById('txPreview');
  if (!box) return;
  const asset = assets.find(a => a.id === _txAssetId);
  const qty   = parseLocalFloat(txQtyInput.value);
  const price = normalizePriceInput(txPriceInput.value);
  const okQty = Number.isFinite(qty) && qty > 0;
  const okPx  = Number.isFinite(price) && price > 0;
  if (!asset || !okQty || !okPx) { box.hidden = true; return; }
  const isSell = txTypeHidden.value === 'sell';
  const cur    = (asset.assetCurrency || 'USD').toUpperCase();
  const held   = Number(asset.qty) || 0;
  const after  = isSell ? (held - qty) : (held + qty);
  const set = (id, v) => { const e = document.getElementById(id); if (e) e.textContent = v; };
  set('txOpLabel', t(isSell ? 'txOpProceeds' : 'txOpCost'));
  set('txOpValue', formatDisplay(qty * price, cur));
  set('txAfterQtyLabel', t('txQtyAfter'));
  set('txAfterQty', formatQty(Math.max(0, after)));
  const mkt = Number(asset.price);
  const row = document.getElementById('txAfterValRow');
  if (Number.isFinite(mkt) && mkt > 0 && after > 0) {
    set('txAfterValLabel', t('txValueAfterEst'));
    set('txAfterVal', formatDisplay(assetNativeValue({ ...asset, qty: after }), cur));
    if (row) row.hidden = false;
  } else if (row) { row.hidden = true; }
  box.hidden = false;
}
txQtyInput.addEventListener('input', _aurixTxUpdatePreview);
txPriceInput.addEventListener('input', _aurixTxUpdatePreview);

document.querySelectorAll('#txTypeToggle [data-txtype]').forEach(btn => {
  btn.addEventListener('click', () => {
    txTypeHidden.value = btn.dataset.txtype;
    document.querySelectorAll('#txTypeToggle [data-txtype]')
      .forEach(b => b.classList.toggle('active', b === btn));
    // Cambiar de compra a venta cambia el signo de la operación y su rótulo.
    _aurixTxUpdatePreview();
  });
});

txForm.addEventListener('submit', e => {
  e.preventDefault();
  if (!_txAssetId) return;
  const qty   = parseLocalFloat(txQtyInput.value);
  const price = normalizePriceInput(txPriceInput.value);
  if (isNaN(qty)   || qty   <= 0) { txQtyInput.focus();   return; }
  if (isNaN(price) || price <= 0) { txPriceInput.focus(); return; }

  const asset = assets.find(a => a.id === _txAssetId);
  if (!asset) return;
  if (!validateTransaction(asset, { type: txTypeHidden.value, qty, price })) return;

  if (_editingTxIndex !== null) {
    if (asset.transactions && asset.transactions[_editingTxIndex]) {
      const originalTs = asset.transactions[_editingTxIndex].ts;
      asset.transactions[_editingTxIndex] = {
        type:  txTypeHidden.value,
        qty,
        price,
        ts:    originalTs,
      };
      syncCostBasisFromTransactions(asset);
      save();
      render();
      onPortfolioChange(true);
      const editedAssetId = _txAssetId;
      closeTxModal();
      openAssetDetailModal(editedAssetId);
    }
  } else {
    const addedAssetId = _txAssetId;
    addTransaction(_txAssetId, txTypeHidden.value, qty, price);
    render();
    onPortfolioChange(true);
    closeTxModal();
    openAssetDetailModal(addedAssetId);
  }
});

// ── Asset detail modal ─────────────────────────────────────
const assetDetailOverlay = document.getElementById('assetDetailOverlay');

function openAssetDetailModal(assetId) {
  const asset = assets.find(a => a.id === assetId);
  if (!asset) return;
  syncCostBasisFromTransactions(asset);

  const isRE   = asset.type === 'real_estate';
  const isCash = asset.type === 'cash';
  const assetCurr = (asset.assetCurrency || 'USD').toUpperCase();

  document.getElementById('adName').textContent = getDisplayName(asset);

  // Price row (hide for real estate / cash where price isn't meaningful)
  const priceRow = document.getElementById('adPrice').closest('.ad-row');
  if (isRE || isCash) {
    priceRow.style.display = 'none';
  } else {
    priceRow.style.display = '';
    document.getElementById('adPrice').textContent =
      asset.price != null ? formatDisplay(asset.price, assetCurr) : '—';
  }

  // Total value — LIQ-2: cash shows nominal in its own currency (with
  // an ≈ base hint when cross-currency); every other type shows the
  // base-currency value via formatDisplay.
  const valueBase = assetNativeValue(asset);
  const adValueEl = document.getElementById('adValue');
  if (isCash) {
    const nominalStr = formatCurrency(liquidityNominal(asset), assetCurr);
    adValueEl.textContent = assetCurr !== baseCurrency
      ? `${nominalStr} (≈ ${formatBase(liquidityBaseValue(asset))})`
      : nominalStr;
  } else {
    adValueEl.textContent = valueBase != null ? formatDisplay(valueBase, assetCurr) : '—';
  }
  document.getElementById('adValueLabel').textContent = t('adValueLabel');

  // PnL
  const pnl = assetPnLBase(asset);
  const pnlEl  = document.getElementById('adPnL');
  const pnlRow = document.getElementById('adPnLRow');
  if (pnl) {
    const sign = pnl.abs >= 0 ? '+' : '';
    pnlEl.textContent = `${sign}${formatBase(pnl.abs)} (${sign}${pnl.pct.toFixed(2)}%)`;
    pnlEl.className = 'ad-value ' + (pnl.abs >= 0 ? 'ad-value--pos' : 'ad-value--neg');
    pnlRow.style.display = '';
  } else {
    pnlRow.style.display = 'none';
  }

  // Transactions section
  const txSection = document.getElementById('adTxSection');
  const txList    = document.getElementById('adTxList');
  const addTxBtn  = document.getElementById('adAddTx');
  document.getElementById('adTxTitle').textContent = t('adTxLabel');
  addTxBtn.textContent = t('adAddBtn');

  if (isRE || isCash) {
    txSection.style.display = 'none';
  } else {
    txSection.style.display = '';
    const txs = asset.transactions || [];
    txList.dataset.assetId = assetId;
    if (!txs.length) {
      txList.innerHTML = `<div class="ad-tx-empty">${t('noTransactions')}</div>`;
    } else {
      txList.innerHTML = txs.map((tx, i) => {
        const date  = new Date(tx.ts).toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: '2-digit' });
        const label = tx.type === 'buy' ? t('txTypeBuy') : t('txTypeSell');
        const cls   = tx.type === 'buy' ? 'tx-buy' : 'tx-sell';
        return `<div class="ad-tx-row">
          <span class="ad-tx-badge ${cls}">${label}</span>
          <div class="ad-tx-detail">
            <span class="ad-tx-qty">${formatQty(tx.qty)}</span>
            <span class="ad-tx-sub">@ ${formatCurrency(tx.price, assetCurr)} · ${date}</span>
          </div>
          <button class="ad-tx-edit"   data-index="${i}" title="${t('btnEditShort')}">✎</button>
          <button class="ad-tx-delete" data-index="${i}" title="${t('btnDeleteShort')}">✕</button>
        </div>`;
      }).reverse().join('');
    }
    addTxBtn.dataset.id = assetId;
  }

  assetDetailOverlay.classList.add('open');
  document.body.classList.add('modal-open');
  // CHART-6: mount the asset-history chart for this asset. No-op when
  // the feature flag is off, the engine is missing, or the asset has
  // no addressable adapter (cash / real estate / unmapped tickers).
  try { _aurixAssetMount(asset); } catch (_) {}
}

function closeAssetDetailModal() {
  assetDetailOverlay.classList.remove('open');
  document.body.classList.remove('modal-open');
  // CHART-6: tear down the chart + abort any in-flight history fetch.
  try { _aurixAssetTeardown(); } catch (_) {}
  render();
}

document.getElementById('adClose').addEventListener('click', closeAssetDetailModal);
assetDetailOverlay.addEventListener('click', e => {
  if (e.target === assetDetailOverlay) closeAssetDetailModal();
});
document.getElementById('adAddTx').addEventListener('click', function () {
  const id = this.dataset.id;
  closeAssetDetailModal();
  if (id) openTxModal(id);
});

document.getElementById('adTxList').addEventListener('click', e => {
  const assetId = document.getElementById('adTxList').dataset.assetId;
  const asset   = assets.find(a => a.id === assetId);

  const editBtn = e.target.closest('.ad-tx-edit');
  if (editBtn) {
    if (!asset || !asset.transactions) return;
    const idx = parseInt(editBtn.dataset.index, 10);
    if (isNaN(idx) || idx < 0 || idx >= asset.transactions.length) return;
    const tx = asset.transactions[idx];
    _editingTxIndex = idx;
    closeAssetDetailModal();
    openTxModal(assetId);
    txQtyInput.value   = tx.qty;
    txPriceInput.value = tx.price;
    txTypeHidden.value = tx.type;
    document.querySelectorAll('#txTypeToggle [data-txtype]')
      .forEach(b => b.classList.toggle('active', b.dataset.txtype === tx.type));
    return;
  }

  const delBtn = e.target.closest('.ad-tx-delete');
  if (delBtn) {
    if (!asset || !asset.transactions) return;
    const idx = parseInt(delBtn.dataset.index, 10);
    if (isNaN(idx) || idx < 0 || idx >= asset.transactions.length) return;
    asset.transactions.splice(idx, 1);
    syncCostBasisFromTransactions(asset);
    save('edit-transaction');
    render();
    onPortfolioChange(true);
    openAssetDetailModal(assetId);
  }
});

// AURIX-HOLDINGS-PREMIUM-UI-1: the asset card / detail row BODY is no longer a
// click trigger — tapping a holding does nothing, to prevent accidental opens.
// Actions are reached ONLY via the explicit "Gestionar" button, which the
// `.dar-manage` delegate above (openAssetManage) already handles. The manage
// overlay and every buy / sell / view-transactions flow are unchanged.

/* ───────── AURIX-ASSET-MANAGE-OVERLAY-1 · compact manage sheet ─────────
   Stays inside the category view. Reuses existing flows (openModal /
   openReduceModal / delete). No Wealth Engine / Ledger / chart touched. */
let _mngAssetId = null;
function openAssetManage(id) {
  const a = assets.find(x => x.id === id); if (!a) return;
  _mngAssetId = id;
  const ov = document.getElementById('assetManageOverlay'); if (!ov) return;
  const $ = s => document.getElementById(s);
  const badge = $('mngBadge');
  if (badge) {
    try {
      // AURIX-ASSET-ACTION-SHEET-PREMIUM-1: premium fallback shown only when no
      // logo loads — institutional monogram for ETFs/funds (iShares/SPDR/…),
      // else the ticker initial. Pure presentation; reuses the shared resolver.
      const _mt = String(a.type || '').toLowerCase();
      const _fb = ((_mt === 'etf' || _mt === 'fund') && typeof _aurixProviderBadge === 'function')
        ? _aurixProviderBadge(a.name, a.ticker)
        : (String(a.ticker || a.name || '?').charAt(0) || '?').toUpperCase();
      badge.innerHTML = buildBadgeHtml(a, escHtml(_fb), 'mng-badge-inner');
    } catch (_) { badge.innerHTML = ''; }
  }
  if ($('mngName'))   $('mngName').textContent   = getDisplayName(a);
  if ($('mngTicker')) $('mngTicker').textContent = a.ticker || '';
  const tx = $('mngTx'); if (tx) { tx.hidden = true; tx.innerHTML = ''; }
  const txBtn = ov.querySelector('[data-mng-act="tx"]'); if (txBtn) txBtn.setAttribute('aria-expanded', 'false');
  ov.classList.add('open'); ov.setAttribute('aria-hidden', 'false');
  document.body.classList.add('modal-open');
}
function closeAssetManage() {
  _mngAssetId = null;
  const ov = document.getElementById('assetManageOverlay');
  if (ov) { ov.classList.remove('open'); ov.setAttribute('aria-hidden', 'true'); }
  document.body.classList.remove('modal-open');
}
function _mngRenderTx() {
  const a = assets.find(x => x.id === _mngAssetId);
  const el = document.getElementById('mngTx'); if (!el || !a) return;
  const txs = Array.isArray(a.transactions) ? a.transactions : [];
  const cur = (a.assetCurrency || 'USD').toUpperCase();
  if (!txs.length) {
    // AURIX-ASSET-MANAGE-FLOW-1 — asset-specific empty state.
    const _nm  = (typeof getDisplayName === 'function') ? getDisplayName(a) : (a.name || a.ticker || '');
    const _msg = (typeof lang !== 'undefined' && lang === 'en') ? `No transactions yet for ${_nm}` : `Aún no hay transacciones para ${_nm}`;
    el.innerHTML = `<div class="mng-tx-empty">${escHtml(_msg)}</div>`;
    return;
  }
  el.innerHTML = txs.slice().reverse().map(tx => {
    let date = ''; try { date = new Date(tx.ts).toLocaleDateString(lang === 'en' ? 'en-GB' : 'es-ES', { day: '2-digit', month: 'short', year: 'numeric' }); } catch (_) {}
    const isBuy  = tx.type === 'buy';
    const label  = isBuy ? t('txTypeBuy') : t('txTypeSell');
    const amount = (Number(tx.qty) || 0) * (Number(tx.price) || 0);
    return `<div class="mng-tx-row ${isBuy ? 'up' : 'down'}">
      <span class="mng-tx-type">${escHtml(label)}</span>
      <span class="mng-tx-meta">${escHtml([formatQty(tx.qty), '@ ' + formatCurrency(tx.price, cur), date].filter(Boolean).join(' · '))}</span>
      <span class="mng-tx-amount">${escHtml(formatCurrency(amount, cur))}</span>
    </div>`;
  }).join('');
}
async function _mngDelete() {
  const id = _mngAssetId; const a = assets.find(x => x.id === id); if (!a) return;
  const _nm = (typeof getDisplayName === 'function') ? getDisplayName(a) : (a.name || a.ticker || '');
  const ok = await _aurixConfirm({
    title: t('deleteAssetTitle'), message: t('deleteAssetMsg')(_nm),
    confirmLabel: t('btnDelete'), cancelLabel: t('keepBtn'), danger: true,
  });
  if (!ok) return;
  // Re-resolve in case state changed while the dialog was open.
  if (!assets.find(x => x.id === id)) return;
  const delType = a.type;
  // AURIX-WEALTH-TRANSACTION-INTEGRITY — la contrapartida en el ledger, por el
  // mismo owner que las demás rutas de eliminación: el valor sale del patrimonio
  // y queda registrado, así que la caída no se lee como pérdida de mercado.
  try { _aurixLedgerAssetRemoval(a, Date.now()); } catch (_) {}
  assets = assets.filter(x => x.id !== id);
  try { _persistEmptyPortfolioIfNeeded('delete'); } catch (_) {}
  save('delete-asset'); closeAssetManage(); render(true);
  try { _flashCategoryCard(delType); } catch (_) {}
  onPortfolioChange(true);
}
(function _wireAssetManage() {
  const ov = document.getElementById('assetManageOverlay'); if (!ov) return;
  document.getElementById('mngClose')?.addEventListener('click', closeAssetManage);
  ov.addEventListener('click', e => { if (e.target === ov) closeAssetManage(); });
  ov.querySelector('.manage-actions')?.addEventListener('click', e => {
    const b = e.target.closest('[data-mng-act]'); if (!b) return;
    const act = b.dataset.mngAct, id = _mngAssetId;
    // AURIX-HOLDING-CONTEXTUAL-BUY-SELL-1 — Buy and Sell behave identically:
    // both open a DEDICATED contextual panel for the selected asset. Buy →
    // openAddModal ("Aumentar posición"), Sell → openReduceModal ("Reducir
    // posición"). Never the generic add-asset picker, never an inline form in
    // the card. tx/delete were already contextual.
    if (act === 'buy')       { closeAssetManage(); if (id) openAddModal(id); }
    else if (act === 'sell') { closeAssetManage(); if (id) openReduceModal(id); }
    else if (act === 'del')  { _mngDelete(); }
    else if (act === 'tx')   {
      const tx = document.getElementById('mngTx'); if (!tx) return;
      const show = tx.hidden; if (show) _mngRenderTx();
      tx.hidden = !show; b.setAttribute('aria-expanded', show ? 'true' : 'false');
    }
  });
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && ov.classList.contains('open')) closeAssetManage(); });
})();

/* ───────── AURIX-ASSET-DETAIL-1 · own-screen controller ─────────
   Consumes wealthEngine.getPosition / positionInsights + wealthLedger
   .eventsForAsset. No new calculations in the UI. */
function _adsHideMain() {
  const hide = el => { if (el) el.style.display = 'none'; };
  hide(document.querySelector('.dashboard-top'));
  hide(document.getElementById('distributionSection'));
  hide(document.getElementById('categoriesSection'));
  hide(document.getElementById('assetsSection'));
}
function _closeAdsMenu() {
  const m = document.getElementById('adsManageMenu');
  const b = document.getElementById('adsManageBtn');
  if (m) m.hidden = true;
  if (b) b.setAttribute('aria-expanded', 'false');
}
function openAssetDetail(id) {
  if (!id || !assets.find(a => a.id === id)) return;
  activeAssetId = id;
  const sec = document.getElementById('assetDetailSection');
  if (!sec) return;
  _adsHideMain();
  sec.style.display = '';
  renderAssetDetail();
  try { window.scrollTo({ top: 0, behavior: reducedMotion ? 'auto' : 'smooth' }); } catch (_) { try { window.scrollTo(0, 0); } catch (__) {} }
}
function closeAssetDetail() {
  activeAssetId = null;
  _closeAdsMenu();
  const sec = document.getElementById('assetDetailSection');
  if (sec) sec.style.display = 'none';
  render(); // repaints the category drill-down (activeCategory still set) or dashboard
}
function _adsHistoryRow(ev) {
  const cur   = ev.currency || baseCurrency;
  const label = { buy: 'adBuy', sell: 'adSell', deposit: 'adDeposit', withdrawal: 'adWithdrawal' }[ev.type] || 'adMove';
  let date = '';
  try { date = new Date(ev.ts).toLocaleDateString(lang === 'en' ? 'en-GB' : 'es-ES', { day: '2-digit', month: 'short', year: 'numeric' }); } catch (_) {}
  if (ev.tsEstimated) date += ' · ' + t('adApprox');
  const cls   = (ev.type === 'sell' || ev.type === 'withdrawal') ? 'down' : 'up';
  const parts = [];
  if (ev.qty != null)   parts.push(formatQty(ev.qty));
  if (ev.price != null) parts.push('@ ' + formatCurrency(ev.price, cur));
  if (date)             parts.push(date);
  const amount = (ev.amount != null) ? formatCurrency(ev.amount, cur) : '';
  return `<div class="ad2-tx ${cls}">
    <span class="ad2-tx-type">${escHtml(t(label))}</span>
    <span class="ad2-tx-meta">${escHtml(parts.filter(Boolean).join(' · '))}</span>
    <span class="ad2-tx-amount">${escHtml(amount)}</span>
  </div>`;
}
function _adsInsightText(i) {
  switch (i.kind) {
    case 'costVsMarket':   return t('insAvg')(formatBase(i.avgBase), i.ticker, formatBase(i.currentBase), i.pct.toFixed(1), i.dir);
    case 'realized':       return t('insRealized')(formatBase(i.amountBase), i.name);
    case 'weightCategory': return t('insWeight')(i.ticker, i.pct.toFixed(1), i.category);
    default:               return t('ad.insufficient');
  }
}
function renderAssetDetail() {
  const id = activeAssetId; if (!id) return;
  const a  = assets.find(x => x.id === id);
  const WE = window.wealthEngine, WL = window.wealthLedger;
  if (!a || !WE || !WE.getPosition) { closeAssetDetail(); return; }
  const p = WE.getPosition(id);
  if (!p) { closeAssetDetail(); return; }
  const $ = s => document.getElementById(s);
  const badge = $('adsBadge'); if (badge) { try { badge.innerHTML = buildBadgeHtml(a, '', 'ad2-badge-inner'); } catch (_) { badge.innerHTML = ''; } }
  if ($('adsName'))   $('adsName').textContent   = getDisplayName(a);
  if ($('adsTicker')) $('adsTicker').textContent = a.ticker || '';
  if ($('adsValue'))  $('adsValue').textContent  = formatBase(p.value.base);
  if ($('adsQty'))    $('adsQty').textContent    = formatQty(p.quantity) + (a.type === 'cash' ? '' : (a.ticker ? ' ' + a.ticker : ''));
  if ($('adsAvg'))    $('adsAvg').textContent    = p.avgBuyPrice ? formatBase(p.avgBuyPrice.base) : '—';
  const glEl = $('adsGl');
  if (glEl) {
    if (p.gainLoss) {
      const pos = p.gainLoss.abs.base >= 0;
      glEl.textContent = `${pos ? '+' : '−'}${formatBase(Math.abs(p.gainLoss.abs.base))} (${pos ? '+' : '−'}${Math.abs(p.gainLoss.pct || 0).toFixed(1)}%)`;
      glEl.className   = 'ad2-v ' + (pos ? 'up' : 'down');
    } else { glEl.textContent = '—'; glEl.className = 'ad2-v'; }
  }
  if ($('adsWeight')) $('adsWeight').textContent = (p.weightInCategory != null) ? p.weightInCategory.toFixed(1) + '%' : '—';
  const hist = $('adsHistory');
  if (hist) {
    const evs = (WL && WL.eventsForAsset) ? WL.eventsForAsset(id).slice().reverse() : [];
    hist.innerHTML = evs.length ? evs.map(_adsHistoryRow).join('') : `<span class="ad2-muted">${escHtml(t('ad.insufficient'))}</span>`;
  }
  const insEl = $('adsInsights');
  if (insEl) {
    const ins = (WE.positionInsights ? WE.positionInsights(id) : []) || [];
    insEl.innerHTML = ins.map(i => `<div class="ad2-insight">${escHtml(_adsInsightText(i))}</div>`).join('');
  }
}
async function _adsDeleteActive() {
  const id = activeAssetId; if (!id) return;
  const a = assets.find(x => x.id === id); if (!a) return;
  const _nm = (typeof getDisplayName === 'function') ? getDisplayName(a) : (a.name || a.ticker || '');
  const ok = await _aurixConfirm({
    title: t('deleteAssetTitle'), message: t('deleteAssetMsg')(_nm),
    confirmLabel: t('btnDelete'), cancelLabel: t('keepBtn'), danger: true,
  });
  if (!ok) return;
  if (!assets.find(x => x.id === id)) return;
  const delType = a.type;
  // AURIX-WEALTH-TRANSACTION-INTEGRITY — la contrapartida en el ledger, por el
  // mismo owner que las demás rutas de eliminación: el valor sale del patrimonio
  // y queda registrado, así que la caída no se lee como pérdida de mercado.
  try { _aurixLedgerAssetRemoval(a, Date.now()); } catch (_) {}
  assets = assets.filter(x => x.id !== id);
  try { _persistEmptyPortfolioIfNeeded('delete'); } catch (_) {}
  save('delete-asset');
  closeAssetDetail();
  try { _flashCategoryCard(delType); } catch (_) {}
  onPortfolioChange(true);
}
(function _wireAssetDetail() {
  document.getElementById('adsBack')?.addEventListener('click', closeAssetDetail);
  const mb = document.getElementById('adsManageBtn');
  mb?.addEventListener('click', e => {
    e.stopPropagation();
    const m = document.getElementById('adsManageMenu');
    if (!m) return;
    const willOpen = m.hidden;
    m.hidden = !willOpen;
    mb.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
  });
  document.getElementById('adsManageMenu')?.addEventListener('click', e => {
    const b = e.target.closest('[data-ad-act]'); if (!b) return;
    const act = b.dataset.adAct; _closeAdsMenu();
    if (act === 'buy')       openModal();
    else if (act === 'sell') { if (activeAssetId) openReduceModal(activeAssetId); }
    else if (act === 'tx')   { const h = document.getElementById('adsHistoryBlock'); if (h) h.scrollIntoView({ behavior: reducedMotion ? 'auto' : 'smooth', block: 'start' }); }
    else if (act === 'del')  _adsDeleteActive();
  });
  document.addEventListener('click', e => {
    const m = document.getElementById('adsManageMenu');
    if (m && !m.hidden && !e.target.closest('.ad2-manage')) _closeAdsMenu();
  });
  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    const m = document.getElementById('adsManageMenu');
    if (m && !m.hidden) { _closeAdsMenu(); return; }
    if (activeAssetId) closeAssetDetail();
  });
})();

