// ── ADD-V2.1/V2.2: Step-1 type picker — routing + mode-aware Step 2 ─
// All routes reuse the existing flows (selectAsset, enterRealEstateMode,
// openLiquidityModal). No submit / persistence logic is duplicated.
// Cards set the modal's data-mode so CSS hides every section irrelevant
// to the chosen flow — search/filters/ISIN for gold + RE, gold/RE
// controls for asset, etc. Header title swaps via JS so each flow
// reads "Añadir activo / Añadir oro físico / Añadir inmueble".
const _ADD_V2_TITLE_KEY = { asset: 'addV2_title_asset', gold: 'addV2_title_gold', real_estate: 'addV2_title_re' };
const _ADD_V2_SUB_KEY   = { asset: 'addV2_subtitle_asset', gold: 'addV2_subtitle_gold', real_estate: 'addV2_subtitle_re' };
// SPEC 45 CATEGORY HEADERS — the financial-asset mode ('asset') is shared by stocks/crypto/ETF, so it showed
// one generic header. This overrides the title + subtitle with the picked category's own copy (no reused
// generic header). Presentation-only: reads existing i18n; no logic/data/model change. Normalizes the picker
// keys (stocks/fund) and the contextual-entry keys (stock/etf) to one bucket. Unknown/legacy 'asset' → no-op
// (keeps the generic header set by _addV2SetMode).
const _ADD_V2_CAT_TITLE = { stock: 'addV2_title_stock', crypto: 'addV2_title_crypto', etf: 'addV2_title_etf' };
const _ADD_V2_CAT_SUB   = { stock: 'addV2_subtitle_stock', crypto: 'addV2_subtitle_crypto', etf: 'addV2_subtitle_etf' };
function _addV2SetCategoryHeader(cat) {
  const c = ({ stocks: 'stock', stock: 'stock', crypto: 'crypto', fund: 'etf', etf: 'etf' })[String(cat || '').toLowerCase()];
  if (!c || !_ADD_V2_CAT_TITLE[c]) return;
  try { const titleEl = document.querySelector('#modalOverlay .modal-header h3'); if (titleEl) titleEl.textContent = t(_ADD_V2_CAT_TITLE[c]); } catch (_) {}
  try { const subEl = document.getElementById('addV2HeaderSub'); if (subEl) { subEl.textContent = t(_ADD_V2_CAT_SUB[c]); subEl.hidden = false; } } catch (_) {}
}

function _addV2Activate(targetStep) {
  const modal = document.querySelector('#modalOverlay .modal');
  if (modal) modal.dataset.step = targetStep;
}
// SPEC 45 STATE ISOLATION — ONE clean-state reset for the shared add-asset modal, invoked at EVERY in-modal
// category switch (picker route + filter bar) so no search / selection / preview / suggestion from one
// category can leak into the next (Metales showing Bitcoin, Crypto showing Apple, a stale preview card).
// Pure UX/state: reuses the existing reset primitives (clearSelectedAsset resets selectedDbAsset + pending*
// + chip + preview); creates/alters NO data, calc, model or portfolio state.
function _addV2ResetForCategory() {
  try { if (typeof isManualMode !== 'undefined' && isManualMode && typeof exitManualMode === 'function') exitManualMode(); } catch (_) {}
  try { if (typeof clearSelectedAsset === 'function') clearSelectedAsset(); } catch (_) {}
  try { if (typeof closeSuggestions === 'function') closeSuggestions(); } catch (_) {}
  try { currentSuggestions = []; renderedSuggestions = []; focusedSuggIdx = -1; } catch (_) {}
  try { if (typeof searchInput !== 'undefined' && searchInput) { searchInput.value = ''; if (typeof searchClearBtn !== 'undefined' && searchClearBtn) searchClearBtn.style.display = 'none'; } } catch (_) {}
}
function _addV2SetMode(mode) {
  const modal = document.querySelector('#modalOverlay .modal');
  if (modal) modal.dataset.mode = mode || '';
  // SPEC 63 — reset the sheet flow to its resting (idle) state on every
  // mode/category entry; focus/typing/selection recompute it via
  // _updateSearchEmptyHint. Prevents a stale 'form' from a prior session
  // leaving the CTA bar (and top-anchor) engaged on a fresh picker entry.
  if (modal) modal.dataset.assetFlow = 'idle';
  const titleEl = document.querySelector('#modalOverlay .modal-header h3');
  if (titleEl) {
    const key = _ADD_V2_TITLE_KEY[mode] || 'modalAddTitle';
    titleEl.textContent = t(key);
  }
  // ADD-V4.2: contextual subtitle under the header so each mode reads
  // "Add financial asset / Stocks, ETFs, funds, crypto and indices".
  const subEl = document.getElementById('addV2HeaderSub');
  if (subEl) {
    const subKey = _ADD_V2_SUB_KEY[mode];
    if (subKey) {
      subEl.textContent = t(subKey);
      subEl.hidden = false;
    } else {
      subEl.textContent = '';
      subEl.hidden = true;
    }
  }
}

// ADD-FLOW-ARCHITECTURE-2: quick picks are now filter-aware. Tapping
// Crypto / Stocks / ETFs / Metals re-renders the curated list so the
// surface answers the user's stated intent immediately. The canonical
// DEFAULTS table already encodes the premium picks per category, so
// quick picks consume the same source — no second source of truth.
function _addV2RenderQuickPicks() {
  const wrap = document.getElementById('addV2PopularChips');
  if (!wrap) return;
  const filter = (typeof activeSearchFilter === 'string' && activeSearchFilter)
    ? activeSearchFilter
    : 'all';
  const picks = ((DEFAULTS && Array.isArray(DEFAULTS[filter]) && DEFAULTS[filter].length)
    ? DEFAULTS[filter]
    : (DEFAULTS.all || []))
    .slice(0, 6);   // SPEC 59 — max 6 Popular cards (clean 2×3 grid); the rest stay reachable via Search
  const typeLabel = T[lang].typeLabel || {};
  wrap.innerHTML = picks.map(p => `
    <button type="button" class="add-v2-asset-card" data-quick-ticker="${escHtml(p.ticker)}">
      ${_assetIconHtml(p, p.ticker, 'add-v2-asset-icon ' + p.type)}
      <span class="add-v2-asset-text">
        <span class="add-v2-asset-name">${escHtml(p.name)}</span>
        <span class="add-v2-asset-meta">
          <span class="add-v2-asset-ticker">${escHtml(p.ticker)}</span>
          <span class="add-v2-asset-type-pill ${escHtml(p.type)}">${escHtml(typeLabel[p.type] || p.type)}</span>
        </span>
      </span>
    </button>
  `).join('');
  wrap.querySelectorAll('[data-quick-ticker]').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = picks.find(p => p.ticker === btn.dataset.quickTicker);
      if (item && typeof selectAsset === 'function') {
        closeSuggestions();
        selectAsset(item);
      }
    });
  });
}

function _addV2RenderRecents() {
  const section = document.getElementById('addV2RecentSection');
  const wrap    = document.getElementById('addV2RecentChips');
  if (!section || !wrap) return;
  // Reuse the global-search recents store — query strings only, no
  // portfolio leakage. Tap pre-fills the search input and runs the
  // existing search pipeline.
  const all = (typeof _gsLoadRecent === 'function') ? _gsLoadRecent() : [];
  // SPEC CATEGORY-CONTEXT — Recent shows ONLY the active category's recents. The active
  // category is `activeSearchFilter` (= the locked opening category when tabs are hidden,
  // or the active tab in All mode). 'etf' covers both etf and fund types. In All mode
  // (activeSearchFilter==='all') every recent is shown. Legacy untyped recents (t:null)
  // appear only in All, never inside a specific category — no cross-category mixing.
  const af = (typeof activeSearchFilter === 'string') ? activeSearchFilter : 'all';
  const matches = (r) => {
    if (af === 'all') return true;
    if (af === 'etf') return r.t === 'etf' || r.t === 'fund';
    return r.t === af;
  };
  const list = all.filter(matches);
  if (!list.length) { section.hidden = true; return; }
  section.hidden = false;
  wrap.innerHTML = list.map(r => `
    <button type="button" class="add-v2-chip is-recent" data-recent-q="${escHtml(r.q)}">
      <span class="add-v2-chip-text">${escHtml(r.q)}</span>
    </button>
  `).join('');
  wrap.querySelectorAll('[data-recent-q]').forEach(btn => {
    btn.addEventListener('click', () => {
      const q = btn.dataset.recentQ || '';
      if (!searchInput) return;
      searchInput.value = q;
      searchInput.dispatchEvent(new Event('input', { bubbles: true }));
      try { searchInput.focus(); } catch (_) {}
    });
  });
}

function _addV2RefreshQuick() {
  _addV2RenderQuickPicks();
  _addV2RenderRecents();
}

// ADD-V4.2: desktop live preview panel. Reads from existing selected
// state (no new pricing logic, no provider calls). Called from the
// existing flow points: selectAsset (header populated), updatePreview
// (value updates with qty), clearSelectedAsset (reset to placeholder).
function _addV4RenderPreview() {
  const card  = document.getElementById('addV2PreviewCard');
  const empty = document.getElementById('addV2PreviewEmpty');
  const body  = document.getElementById('addV2PreviewBody');
  if (!card || !empty || !body) return;

  const asset = (typeof selectedDbAsset !== 'undefined') ? selectedDbAsset : null;
  if (!asset) {
    empty.hidden = false;
    body.hidden  = true;
    return;
  }

  empty.hidden = true;
  body.hidden  = false;

  const nameEl     = document.getElementById('addV2PreviewName');
  const typeEl     = document.getElementById('addV2PreviewType');
  const tickerEl   = document.getElementById('addV2PreviewTicker');
  const currencyEl = document.getElementById('addV2PreviewCurrency');
  const priceEl    = document.getElementById('addV2PreviewPrice');
  const valueEl    = document.getElementById('addV2PreviewValue');

  const displayName = (typeof getDisplayName === 'function') ? getDisplayName(asset) : (asset.name || asset.ticker || '');
  const ticker      = String(asset.ticker || asset.symbol || '').toUpperCase();
  const typeKey     = String(asset.type || '').toLowerCase();
  const typeLabel   = (T[lang]?.typeLabel || {})[typeKey] || typeKey;
  const currency    = (pendingCurrency || 'USD').toUpperCase();

  if (nameEl)     nameEl.textContent     = displayName;
  if (typeEl) {
    typeEl.textContent = typeLabel;
    typeEl.className = `add-v2-preview-type ${typeKey}`;
  }
  if (tickerEl)   tickerEl.textContent   = ticker;
  if (currencyEl) currencyEl.textContent = currency;

  if (priceEl) {
    if (typeof pendingPrice === 'number' && Number.isFinite(pendingPrice)) {
      priceEl.textContent = formatDisplay(pendingPrice, 'USD');
    } else {
      priceEl.textContent = '—';
    }
  }
  if (valueEl) {
    // Mirror the existing previewTotal computation result without
    // duplicating the formula — it's already written into #previewTotal
    // by updatePreview() right before this runs in the qty-input flow.
    const totalEl = document.getElementById('previewTotal');
    valueEl.textContent = totalEl ? totalEl.textContent : '—';
  }
}

(function _addV2Wire() {
  const picker      = document.getElementById('addV2Picker');
  const pickerClose = document.getElementById('addV2PickerClose');
  const backBtn     = document.getElementById('addV2Back');
  if (pickerClose) pickerClose.addEventListener('click', closeModal);
  // AURIX-METALS-ADD-SHEET-FIX — wire the metal picker sheet (Oro / Plata).
  const metalPicker = document.getElementById('addV2MetalPicker');
  const metalClose  = document.getElementById('addV2MetalPickerClose');
  if (metalClose) metalClose.addEventListener('click', closeModal);
  if (metalPicker) {
    metalPicker.addEventListener('click', e => {
      const card = e.target.closest && e.target.closest('[data-metal-pick]');
      if (!card || card.classList.contains('is-disabled')) return;
      if (typeof _aurixMetalPick === 'function') _aurixMetalPick(card.dataset.metalPick);
    });
  }
  if (backBtn) {
    backBtn.addEventListener('click', () => {
      // Reset every sub-flow state that Step 2 might have entered, then
      // return to Step 1. Mirrors the openModal() reset block.
      try { if (typeof exitManualMode === 'function') exitManualMode(); } catch (_) {}
      try { if (typeof clearSelectedAsset === 'function') clearSelectedAsset(); } catch (_) {}
      try { if (typeof enterSearchMode === 'function') enterSearchMode(); } catch (_) {}
      _addV2SetMode('');
      _addV2Activate('picker');
    });
  }
  if (!picker) return;
  picker.addEventListener('click', e => {
    const card = e.target.closest && e.target.closest('[data-pick]');
    if (!card || card.classList.contains('is-disabled')) return;
    const pick = card.dataset.pick;

    // ONBOARDING-V2 (FASE 1) — in-place category routing (the modal is already open; never re-open).
    // The search box lives in Step 2 (form), so it only appears AFTER a category is chosen here.

    // Liquidez → dedicated FORM (importe/divisa/tipo/nombre), NEVER straight to the success screen.
    if (pick === 'liquidity') {
      closeModal();
      if (typeof openLiquidityModal === 'function') openLiquidityModal();
      return;
    }

    // SPEC 45 STATE ISOLATION — every category entered from the picker starts from a clean state (no leaked
    // selection/preview/search/suggestions from the previously viewed category).
    _addV2ResetForCategory();

    // Metales / (legacy 'gold') → metal picker sheet: choose Oro/Plata first, then the type.
    if (pick === 'metal' || pick === 'gold') {
      try { _modalContext = 'metal-picker'; _modalAssetFilterContext = 'metal'; } catch (_) {}
      try { if (typeof _aurixRenderMetalPicker === 'function') _aurixRenderMetalPicker(); } catch (_) {}
      _addV2Activate('metal-picker');
      return;
    }

    // Inmuebles → property form.
    if (pick === 'real_estate') {
      _addV2SetMode('real_estate');
      _addV2Activate('form');
      try { if (typeof enterRealEstateMode === 'function') enterRealEstateMode(); } catch (_) {}
      return;
    }

    // Acciones / Criptomonedas / Fondos·ETF (and legacy 'asset') → asset search with the matching
    // market filter pre-engaged, so "Acciones" means stocks, "Criptomonedas" means crypto, etc.
    const filterKey = { stocks: 'stock', crypto: 'crypto', fund: 'etf', asset: null }[pick];
    _addV2SetMode('asset');
    try { _addV2SetCategoryHeader(pick); } catch (_) {}   // SPEC 45 — per-category header (stocks/crypto/ETF), not the generic one
    try { _modalContext = 'asset'; _modalAssetFilterContext = filterKey || null; } catch (_) {}
    // SPEC 60 — set the active category BEFORE rendering Recent/Popular. _addV2RefreshQuick()
    // below reads `activeSearchFilter` (Popular = DEFAULTS[activeSearchFilter]; Recent filters
    // by it). SPEC 59 set it AFTER the refresh, so Recent/Popular rendered with the stale 'all'
    // → other categories leaked into a specific-category entry. One shared context, set first.
    try { activeSearchFilter = filterKey || 'all'; } catch (_) {}
    _addV2Activate('form');
    // SPEC CATEGORY-CONTEXT — reflect the opening category (or All) onto the modal so the
    // tabs hide/show correctly even for the All entry (filterKey null → no filter-btn click below).
    try { if (typeof _addV42UpdateFilterAttr === 'function') _addV42UpdateFilterAttr(filterKey || 'all'); } catch (_) {}
    try { if (typeof _addV2RefreshQuick === 'function') _addV2RefreshQuick(); } catch (_) {}
    try { if (typeof _updateSearchEmptyHint === 'function') _updateSearchEmptyHint(); } catch (_) {}
    // SPEC 59 — engage the category WITHOUT opening the suggestions panel (the old btn.click()
    // routed through the filter handler → showDefaultSuggestions() auto-opened the panel).
    // activeSearchFilter is already set above (SPEC 60); here only the tab highlight + placeholder.
    if (filterKey) {
      try { filterBtns.forEach(b => b.classList.toggle('active', b.dataset.filter === filterKey)); } catch (_) {}
      try { searchInput.placeholder = T[lang].searchPH[filterKey] || T[lang].searchPH.all; } catch (_) {}
    }
  });
})();

